window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-preventiva-pre-1"]={"block":"medcurso:medcurso-preventiva-pre-1","label":"Medcurso · PRE 1","count":396,"questions":[{"id":"medcurso-preventiva-pre-1-281174","number":"281174","sourceNumber":"281174","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Na complexa cadeia de causalidade das doenças crônicas não transmissíveis, a OMS\npropõe um modelo para sintetizar a sua história natural, seus determinantes e desfechos. A esse\nrespeito, analise as colunas. ( ) Diabetes. ( ) Alimentação inadequada. ( ) Hipertensão. ( )\nIntolerância à glicose. ( ) Tabagismo. A. Determinantes sociais. B. Fatores intermediários de\nrisco.\n\nC. Desfechos. Assinale a coluna da esquerda segundo seu correspondente à direita e escolha a\nalternativa com a sequência assinalada correta.","options":{"A":"C, B, B, C, A.","B":"B, B, C, A, B.","C":"B, A, A, B, C.","D":"C, A, B, B, A.","E":"A, C, A, B, B."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-281182","number":"281182","sourceNumber":"281182","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil o câncer mais comum é o...","options":{"A":"melanoma.","B":"de pele não melanoma.","C":"adenocarcinoma de pulmão.","D":"adenocarcinoma de próstata.","E":"adenocarcinoma de mama."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-247229","number":"247229","sourceNumber":"247229","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que apresenta a principal causa de morte para homens de 20 a\n39 anos no Brasil.","options":{"A":"Doenças infecciosas e parasitárias.","B":"Neoplasias.","C":"Doenças do aparelho circulatório.","D":"Doenças do aparelho respiratório.","E":"Causas externas."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-247233","number":"247233","sourceNumber":"247233","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que preencha corretamente os espaços em branco da afirmação:\n\"Se alguém utilizasse os dados do\npara estudar no Brasil,\nestaria incluindo os eventos registrados \".","options":{"A":"SIM ... mortalidade ... todos ... no território nacional","B":"SIM ... mortalidades ... apenas ... por hospitais","C":"SINASC ... Natimortalidade ... todos ... no território nacional","D":"SINAN ... agravos notificáveis ... apenas ... por hospitais particulares","E":"SIH-SUS ... morbidade hospitalar ... todos ... território nacional"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-183161","number":"183161","sourceNumber":"183161","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Temos hoje no Brasil, cerca de 50 milhões de jovens entre 10 e 24 anos (IBGE, Censo\n2010), este é um grupo populacional sujeito\na uma série de riscos que são refletidos em indicadores\nde saúde. Assinale a alternativa CORRETA sobre este grupo etário.","options":{"A":"A mortalidade por causas endocrinometabólicas cresce com a obesidade e figura entre as mais\nimportantes.","B":"As principais causas de mortes por causas externas são os suicídios e afogamentos.","C":"A mortalidade é maior por causas infecciosas e a AIDS é a principal causa.","D":"A mortalidade está relacionada com a dependência de drogas, mormente do crack.","E":"As causas externas (acidentes e violências) são a maior causa de mortes, sendo bem maior\nentre pessoas do gênero masculino."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-183215","number":"183215","sourceNumber":"183215","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa CORRETA. A mortalidade infantil é importante indicador social\nem saúde coletiva. Quando ela é baixa, em\ntorno de 10 por 1.000 nascidos vivos, predominam as\nmortes no período:","options":{"A":"Infantil tardia (após 6 meses).","B":"Neonatal tardia (de 7 até 28 dias).","C":"Infantil precoce (até 10 dias).","D":"Infantil tardia (28 dias até 1 ano).","E":"Perinatal (0 a 6 dias)."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-159100","number":"159100","sourceNumber":"159100","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Várias pesquisas evidenciam um incremento, nas últimas décadas, no número de\nmortes por câncer no Brasil; além disso, a\nOrganização Mundial da Saúde (OMS) estima que, em\n2020, esta será a principal causa de mortes no mundo. Tais fatos demonstram a importância de se\ninstituirem ações que tenham como objetivo a prevenção das diversas formas dessa doença\natravés da orientação aos pacientes, visando a diminuir, ao máximo, a exposição aos seus fatores\nde risco. Considere as afirmações abaixo acerca desses fatores de risco. I - O uso crônico de\nestrógenos não está associado a um aumento no risco de adenocarcinoma de endométrio em\npacientes pós-menopáusicas. II - As neoplasias do cólon, reto, mama e útero ocorrem com maior\nfrequência em indivíduos obesos. III - A ingestão crônica de bebidas alcoólicas aumenta o risco de\nneoplasias de cavidade oral, faringe, hipofaringe, laringe, esôfago e fígado. Quais estão corretas?","options":{"A":"Apenas I e II.","B":"Apenas I e III.","C":"Apenas II e III.","D":"I, II e III."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-135986","number":"135986","sourceNumber":"135986","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação à mortalidade materna, qual dos conceitos abaixo está INCORRETO?","options":{"A":"Considera-se como morte materna obstétrica direta, aquela resultante de complicações\nobstétricas na gravidez, no parto ou no puerpério\ndevidas a intervenções, omissões, tratamento\nincorreto ou uma cadeia de eventos resultantes de qualquer uma das causas citadas;","B":"Considera-se como morte materna obstérica indireta, aquela ocorrida durante a pravidez, o parto\nou o puerpério resultante de doenças\npreexistentes ou que se desenvolveram durante a gravidez\ndevido aos efeitos fisiológicos desta;","C":"O conceito de morte materna depende da duração e da localização da gravidez e não engloba\nos óbitos acidentais ou incidentais;","D":"O coeficiente de mortalidade materna resulta da relação entre as mortes obstétricas diretas e\nindiretas e o número total de nascidos vivos em determinado local e período, considerando-se\n\n100.000 nascidos vivos;"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-108774","number":"108774","sourceNumber":"108774","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Como mostra a tabela abaixo (Tabela 1), o município com o maior número de casos\nprováveis de Dengue em 2014 foi Campinas (SP) com 42.373 casos. No entanto, o município de\nCruzeiro do Sul no Acre teve incidência 7,8 vezes maior que aquele município, sendo o município\ncom maior incidência de casos prováveis em 2014 no Brasil. Sobre esse fenômeno observado,\nassinale a opção CORRETA dentre as apresentadas abaixo. (VER IMAGEM)","options":{"A":"A incidência em Cruzeiro do Sul é bem maior que a de Campinas porque a população de\nCruzeiro do Sul é bem menor que a de Campinas;","B":"Essa diferença acontece porque o número total de casos representa a prevalência da doença, o\nque se diferencia do cálculo da incidência;","C":"Provavelmente trata-se de um erro de cálculo ou de digitação, pois o número que representa a\nincidência em Cruzeiro do Sul é muito maior que os outros, e o cálculo da incidência é utilizado\njustamente para diminuir essas discrepâncias;","D":"A incidência é bem maior em Cruzeiro do Sul, mas a prevalência deve ser bem maior em\nCampinas e São Paulo, porque são cidades\ncom a população bem maior que as outras analisadas;"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-341083","number":"341083","sourceNumber":"341083","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Brasil envelhece de forma rápida e intensa. Segundo o Censo IBGE de 2010, a\npopulação idosa brasileira é composta por 23\nmilhões de pessoas, totalizando 11,8% da população\ntotal do País. A expectativa de vida para a população brasileira aumentou para 74 anos, sendo 77,7\nanos para a mulher e 70,6 anos para o homem. Quanto ao aumento da expectativa de vida da\npopulação brasileira, pode-se dizer que se deve à","options":{"A":"redução da prevelência de doenças crônico-degenerativas.","B":"mudanças no acesso à saúde e nas condições de vida.","C":"redução da base da pirâmide etária e alargamento do ápice.","D":"redução da incidência de doenças cardiovasculares e diabetes."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-341086","number":"341086","sourceNumber":"341086","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Mulher, 57 anos de idade, foi à Unidade Básica de Saúde onde foi solicitada\nultrassonografia pélvica para acompanhamento de\nmenopausa. O resultado de exame revelou\ncistos ovarianos bilaterais, sendo que o cisto à esquerda foi considerado como O-RADS 4. A\npaciente foi encaminhada ao ginecologista que solicitou uma ultrassonografia endovaginal com\nDoppler. Após o resultado desse ultimo exame houve indicação para internamento hospitalar no\nSUS. Indique a ferramenta documental a ser preenchida pelo ginecologista, indispensável para a\ninternação hospitalar e o registro no DATA SUS:","options":{"A":"Autorização para internação Hospitalar (AIH).","B":"Laudo de solicitação para emissão de Autorização de Internação (Laudo para AIH).","C":"Autorização para Procedimentos de Alta Complexidade (APAC).","D":"Relatório Médico Circunstanciado e Assinado (RMCA)."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-343227","number":"343227","sourceNumber":"343227","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Parvovírus B19 e o Herpes-vírus-6:","options":{"A":"Têm sido cada vez mais descritos em biópsias cardíacas, havendo uma tendência de redução\nde identificação de enterovírus e adenovírus.","B":"Têm sido cada vez menos descritos em biópsias cardíacas, havendo uma tendência de redução\nde identificação de enterovírus e adenovírus.","C":"Têm sido cada vez mais descritos em biópsias cardíacas, havendo uma tendência de aumento\nde identificação de enterovírus e adenovírus.","D":"Têm sido cada vez mais descritos em biópsias cardíacas, havendo uma tendência de redução\nde identificação de enterovírus e não de\nadenovírus."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-343228","number":"343228","sourceNumber":"343228","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As doses de reforço das Vacinas contra COVID-19 ainda oferecem proteção adicional\ncontra formas graves tanto das variantes Ômicron quando Delta, que, não podemos negligenciar,\nainda circula em nosso meio. Sendo correto que:","options":{"A":"A terceira dose da vacina não confere eficácia em evitar atendimentos de urgência e\nemergência, e 90% em prevenir hospitalizações.","B":"A terceira dose da vacina confere eficácia de 82% em evitar atendimentos de urgência e\nemergência, e não em prevenir hospitalizações.","C":"A terceira dose da vacina confere eficácia de 82% em evitar atendimentos de urgência e\nemergência, e 90% em prevenir hospitalizações.","D":"A terceira dose da vacina confere eficácia de 82% em promover atendimentos de urgência e\nemergência, e 90% em prevenir hospitalizações."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-315182","number":"315182","sourceNumber":"315182","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O país já teve taxa de fecundidade de nação africana ? 5,8 filhos por mulher, em 1970.\nSe essa taxa se mantivesse, a população hoje\nseria de 300 milhões de habitantes. Como essa taxa\ncaiu para 1,8 filho por mulher, a população atual é de 193 milhões. [...]? (REVISTA VEJA. São\nPaulo: Ed. Abril, a. 43, n. 27, p. 97, 7 jul. 2010.) A taxa de fecundidade é um dos fatores da\ndinâmica populacional e reflete várias tendências da sociedade brasileira e mesmo mundial.\n\nEscolha a alternativa CORRETA sobre a demografia e sua dinâmica:","options":{"A":"O crescimento da população mundial sempre causou polêmicas. No século XVIII, Thomas\nMalthus já alertava sobre a falta de\nalimentos para uma população mundial que cresceria\ndescontroladamente e divulgou a sua teoria demográfica. Essa teoria não foi mais utilizada, uma\nvez que a produção de alimentos atende a toda a população mundial.","B":"O custo de formação do indivíduo é maior nos países desenvolvidos em razão da necessidade\nde dar educação mais completa, de maior\nquantidade de roupas, material escolar, aparelhos\neletrônicos e proibição de trabalho para menores. Tudo isso pode levar a um aumento da taxa de\nnatalidade.","C":"O superpovoamento é sempre relativo e se altera com as mudanças econômicas, sociais e\ntecnológicas. Os países mais desenvolvidos foram os primeiros a terem suas taxas de natalidade\nem declínio, e um aumento da expectativa de vida, seguidos de imediato pelos países mais pobres.","D":"Quando a taxa de fecundidade de um país é muito baixa (inferior a 2,1%), compromete a\nreposição da população que morre,\nocorrendo, muitas vezes, falta de mão-de-obra e levando a um\nincentivo às migrações.","E":"A dinâmica demográfica dos homens pode ser explicada somente pelos mecanismos naturais,\ndesconsiderando os mecanismos culturais e econômicos de regulação."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-315183","number":"315183","sourceNumber":"315183","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"É CORRETO afirmar-se sobre as características atuais da estrutura da população\nbrasileira:","options":{"A":"No Brasil, o crescimento vegetativo ou natural continua apresentando índices muito baixos,\ntípicos de países desenvolvidos.","B":"De 1992 para 2001, a participação dos menores de 10 anos na população total vem aumentando\nde 18,7% para 22,1%.","C":"A atual estrutura da população brasileira apresenta aumento das taxas de natalidade e de\nmortalidade e redução da expectativa de vida.","D":"No processo de transição demográfica, vem aumentando a participação da população de jovens\ne reduzindo-se a de idosos no conjunto total da\npopulação.","E":"No processo de transição demográfica, vem se reduzindo a participação da população jovem e\naumentando a de idosos no conjunto total da população."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-315184","number":"315184","sourceNumber":"315184","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"?Brasil discute nesta semana com ministros de países do Brics ? grupo de países\nemergentes integrado pela Rússia, Índia, China\ne África do Sul ? como conter a aceleração do\nenvelhecimento da população, entre outros assuntos. Para o subsecretário da política de assuntos\nestratégicos (SAE) da Presidência da República, Ricardo Paes de Barros, o país não está sabendo\nconstruir barreiras para conter o problema, também enfrentado pelos chineses?. DINIZ, F. País\ndiscute com Brics como conter avanço do envelhecimento. Portal Terra, 10 fev. 2015. Disponível\nem: http://economia.terra.com.br. Acesso em: 05 jun. 2015. O principal objetivo em conter o\nenvelhecimento demográfico em um país é:","options":{"A":"A elevação das taxas de desemprego.","B":"A redução dos gastos previdenciários.","C":"O controle dos índices de pobreza.","D":"O aumento da esperança de vida.","E":"A redução da ?explosão demográfica?."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-315185","number":"315185","sourceNumber":"315185","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Dentre os fatores importantes para explicar as diferenças no estado de saúde de\nindivíduos e grupos estão os fatores de\nrisco individual (como hábitos alimentares, dieta, prática de\natividades físicas, alcoolismo, tabagismo, drogadição, etc...) e os fatores de risco coletivo (má\ndistribuição de renda, acesso a bens e serviços, etc). Sobre a consideração destes diferentes\nfatores na análise do processo saúde- doença, assinale a alternativa CORRETA:","options":{"A":"Diversas pesquisas têm demonstrado que os fatores de risco individual explicam entre 35 e 40%\nda diferença de exposição a riscos entre\ngrupos sociais. Entre 60 a 65% desta diferença são\nexplicadas por fatores de risco coletivo (ou DSSs).","B":"Durante décadas a medicina esteve voltada sobretudo para o estudo da DSSs. Estudos mais\nrecentes têm voltado a atenção sobretudo para a observação e intervenção nos fatores de risco\nindividual. Tal compreensão é pautada nos princípios da humanização e da integralidade em\nsaúde.","C":"As diferenças no nível de saúde entre grupos e países estão mais relacionadas com os fatores\nde risco individual. Os fatores de risco\ncoletivo (DSSs) são importantes para identificar quais\nindivíduos no interior de um grupo estão submetidos a maiores riscos.","D":"Para conhecer os determinantes de saúde no nível da sociedade deve-se recorrer ao estudo dos\ndeterminantes de saúde identificados em estudos com indivíduos.","E":"É largamente reconhecido que, apesar da importância do conhecimento acerca dos\ndeterminantes sociais da saúde, os fatores\nfundamentais para produzir o diagnóstico de um\npaciente e realizar o planejamento de ações de prevenção são os fatores de risco individuais."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-315186","number":"315186","sourceNumber":"315186","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"?Acompanhando uma tendência mundial, o crescimento da população brasileira vem\ndiminuindo nas últimas quatro décadas. [...] Além de estar crescendo menos, a população brasileira\ntambém apresenta outra característica: o envelhecimento? (Coleção Almanaque Abril. nº 4. 2004.\np. 4). Este processo de mudanças no perfil da população brasileira, que é denominado ?transição\ndemográfica?, tem como características: I. O aumento da longevidade e da queda da fecundidade e\nda mortalidade, sobretudo, com o progresso da medicina e das condições sanitárias. II. A\ndiminuição do número de filhos por famílias em razão das transformações econômicas e sociais\nque levaram a mulher ao mercado de trabalho. III. A mudança no desenho da pirâmide etária\nbrasileira que passa a apresentar base mais estreita e topo mais largo. IV. O aumento da\nparticipação dos homens na pirâmide etária, que passaram a viver mais que as mulheres, as quais,\ntornaram-se mais expostas à mortalidade por homicídios e acidentes. Estão CORRETAS apenas as\nproposições:","options":{"A":"I, II e III.","B":"III e IV.","C":"I, III e IV.","D":"II e III.","E":"I, II e IV."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-276010","number":"276010","sourceNumber":"276010","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Coeficiente de Mortalidade Infantil é um indicador de saúde sensível que reflete as\ncondições de desenvolvimento socioeconômico e infraestrutura ambiental, bem como o acesso e a\nqualidade dos recursos disponíveis para a atenção à saúde materna e da população infantil. Em\nrelação a esse tema, assinale a alternativa INCORRETA.","options":{"A":"O Coeficiente de Mortalidade Infantil é definido pela divisão entre o número de óbitos de\nmenores de 1 ano de idade e nascidos vivos, multiplicado por 1000.","B":"O Coeficiente de Mortalidade Neonatal Precoce é definido pela divisão entre o número de óbitos\nde menores de 28 dias de vida e o número de\nnascidos vivos, multiplicado por 1000.","C":"O Coeficiente de Mortalidade Pós ? Neonatal é definido pela divisão entre o número de óbitos de\nmenores de 5 anos de idade e o número de nascidos vivos, multiplicado por 1000.","D":"O Coeficiente de Natimortalidade é definido pela divisão entre o número de nascidos mortos e a\nsoma entre o número de nascidos vivos e o número de nascidos mortos, multiplicado por 1000.","E":"O Coeficiente de Mortalidade Perinatal é definido pela divisão entre a soma do número de\nnascidos mortos e do número de óbitos em menores de sete dias pela soma entre o número de\nnascidos vivos e o número de nascidos mortos, multiplicado por 1000."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-276011","number":"276011","sourceNumber":"276011","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em um determinado local, o Índice de Swaroop-Uemura apresentou um valor de 85%.\nSobre esse local hipotético, assinale a alternativa CORRETA.","options":{"A":"Trata-se, possivelmente, de um local com poucas condições socioeconômicas e estruturais.","B":"Provavelmente, houve uma maior porcentagem de óbitos em pessoas com menos de 50 anos\nem relação ao total de óbitos.","C":"Por apresentar um valor de 85%, o local hipotético está no segundo nível do Índice de\nSwaroop-Uemura.","D":"Provavelmente, houve uma maior porcentagem de óbitos em pessoas com 50 anos ou mais em\nrelação ao total de óbitos.","E":"A expectativa de vida deste local deve ser baixa."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-278137","number":"278137","sourceNumber":"278137","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Embora as taxas de mortalidade e disability-adjusted life year (DALY) padronizadas por\nidade estejam diminuindo no Brasil, possivelmente como resultado de políticas de saúde\n\nbem-sucedidas, o número total destas está aumentando principalmente devido ao envelhecimento\ne adoecimento da população. Assim, podemos indicar\ncomo correto que:","options":{"A":"A doença cardiovascular (DCV) não é a principal causa de morte no Brasil e no mundo,\ndeterminando aumento da morbidade e incapacidade ajustadas pelos anos de vida.","B":"A doença cardiovascular (DCV) é a principal causa de morte no Brasil e no mundo,\ndeterminando redução da morbidade e incapacidade ajustadas pelos anos de vida.","C":"A doença cardiovascular (DCV) é a principal causa de morte no Brasil e no mundo,\ndeterminando aumento da morbidade e incapacidade ajustadas pelos anos de vida.","D":"A doença cardiovascular (DCV) é a principal causa de morte no Brasil e no mundo,\ndeterminando aumento da morbidade e não de\nincapacidade ajustadas pelos anos de vida."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-279091","number":"279091","sourceNumber":"279091","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Embora a taxa de mortalidade materna esteja ainda aquém das metas estimadas para\neste milênio","options":{"A":"nas três últimas décadas o Brasil registrou importante aumento no coeficiente de mortalidade\nmaterna em decorrência de complicações durante o ciclo gravídico-puerperal.","B":"nas três últimas décadas o Brasil registrou importante redução no coeficiente de mortalidade\nmaterna em decorrência de complicações durante o ciclo gravídico-puerperal.","C":"nas três últimas décadas o Brasil registrou importante redução no coeficiente de mortalidade\nmaterna sem nexo com complicações durante o ciclo gravídico-puerperal.","D":"nas três últimas décadas o Brasil registrou nenhuma redução no coeficiente de mortalidade\nmaterna em decorrência de complicações durante o ciclo gravídico-puerperal."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-278145","number":"278145","sourceNumber":"278145","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A incidência traduz o risco médio da população em adquirir a doença, além de servir de\nparâmetro para a avaliação do impacto produzido por medidas de prevenção que o diabetes\nrepresenta para os sistemas de saúde. Assim podemos concordar com o item:","options":{"A":"Tanto a frequência de existentes casos (incidência) como a de casos existentes (prevalência)\nsão informações importantes para o conhecimento da\ncarga que o diabetes representa para os\nsistemas de saúde.","B":"Tanto a frequência de novos casos (incidência) como a de casos existentes (prevalência) não\nsão informações importantes para o conhecimento da\ncarga que o diabetes representa para os\nsistemas de saúde.","C":"Tanto a frequência de novos casos (incidência) como a de casos novos (prevalência) são\ninformações importantes para o conhecimento da carga que o diabetes representa para os\nsistemas de saúde.","D":"Tanto a frequência de novos casos (incidência) como a de casos existentes (prevalência) são\ninformações importantes para o conhecimento da carga que o diabetes representa para os\nsistemas de saúde."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-231385","number":"231385","sourceNumber":"231385","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Para realizar o cálculo da Taxa de Mortalidade Infantil, é necessário coletar dados de\nquais sistemas de informação em saúde?","options":{"A":"SIH e SIM.","B":"SIM e SIAB.","C":"SIH e SINAN.","D":"SIM e SINASC.","E":"SINAN e SINASC."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-231386","number":"231386","sourceNumber":"231386","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual a opção que corresponde a um indicador da categoria fatores de risco e proteção\npara uso no processo decisório na atenção\nbásica na saúde?","options":{"A":"Proporção diária per capita das calorias provenientes de frutas, verduras e legumes no total de\ncalorias da dieta.","B":"Proporção da população feminina que refere nunca ter realizado mamografia.","C":"Proporção da população que refere nunca ter realizado consulta odontológica.","D":"Proporção de famílias com participação em grupos comunitários.","E":"Número de procedimentos diagnósticos por consultas médicas."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-231390","number":"231390","sourceNumber":"231390","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Sistema de Vigilância Alimentar e Nutricional (SISVAN) foi proposto primeiramente\npelo INAN (Instituto Nacional de Alimentação e\nNutrição) em 1976. Somente em 1990, com a\naprovação da Lei no 8080, e a publicação da Portaria no 1.156, o novo Sistema foi estabelecido\nnacionalmente. O SISVAN tem a função de:","options":{"A":"distribuir alimentos não perecíveis às famílias com crianças desnutridas;","B":"acompanhar exclusivamente o estado nutricional de crianças e gestantes;","C":"orientar a formulação de políticas públicas;","D":"fazer o diagnóstico puramente descritivo da situação alimentar e nutricional;","E":"instituir medidas de intervenção sobre os problemas nutricionais identificados."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-252934","number":"252934","sourceNumber":"252934","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, o câncer do colo do útero é o segundo tipo de câncer mais frequente entre\nmulheres, após o câncer de mama, com alta mortalidade e faz, por ano, 4.800 vítimas fatais. Em\n2012, as estimativas foram de 17.540 casos novos, com risco estimado variando de 17 a 21 casos\na cada 100 mil mulheres, com grandes iniquidades regionais, sendo maiores as incidências\nregistradas em estados com menor nível de desenvolvimento socioeconômico. BRASIL, Ministério\nda Saúde. Informe Técnico sobre a Vacina Papiloma Vírus Humano (HPV) na Atenção Básica.\n\nIdentifique a que índice, referente ao câncer de colo de útero, está relacionada a afirmação \"com\nrisco estimado variando de 17 a 21 casos/100\nmil mulheres\" constante no Informe Técnico do MS.","options":{"A":"Incidência.","B":"Prevalência.","C":"Mortalidade.","D":"Letalidade."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-219919","number":"219919","sourceNumber":"219919","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Sistema de Informações de Mortalidade (SIM) foi implantado no Brasil em 1975 com\no objetivo de padronizar as informações\nepidemiológicas em todo o país e gerar estatísticas sobre\nmortalidade. Com relação a esse sistema, é CORRETO afirmar que:","options":{"A":"A fonte de informação desse sistema é a notificação dos hospitais diretamente ao IBGE.","B":"Atualmente, a cobertura do SIM no Brasil é muito baixa, sendo a razão entre óbitos coletados e\nóbitos estimados pelo IBGE inferior a 60%.","C":"Qualquer profissional de saúde que tenha assistido o paciente pode preencher as informações\nda DO sobre as causas da morte.","D":"O responsável pelo preenchimento da causa de morte no caso de mortes por causas externas é\no médico legista do Instituto Médico Legal\n(IML)."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-219876","number":"219876","sourceNumber":"219876","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Índice de Desenvolvimento Humano (IDH) é um dado estatístico criado pelo\nPrograma das Nações Unidas para o\nDesenvolvimento (PNUD) para contrapor os dados puramente\neconômicos utilizados para medir a riqueza dos países e analisar o desenvolvimento a partir da\ninclusão de outros fatores. O cálculo do IDH baseia-se em:","options":{"A":"Expectativa de vida ao nascer; anos de escola; PIB per capita.","B":"Expectativa de vida ao nascer; fecundidade; taxa de desemprego.","C":"Mortalidade após 50 anos; anos de escola; fecundidade.","D":"Mortalidade materna, anos de escola; fecundidade."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-212166","number":"212166","sourceNumber":"212166","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em 2017, houve 1.000 mortes por todas as causas em uma cidade de 100.000\nhabitantes. Se todos os casos de Tuberculose\n(Tb) foram identificados, totalizando 600 casos (400\nhomens e 200 mulheres), com 120 mortes, qual a mortalidade proporcional devido à Tb, nessa\ncidade, no ano referido?","options":{"A":"6%.","B":"12%.","C":"40%.","D":"50%.","E":"60%."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-215543","number":"215543","sourceNumber":"215543","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A prevalência é um indicador da magnitude do impacto global do diabetes mellitus\ndentro da saúde pública, na epidemiologia e\nimpacto global do diabetes mellitus. Podemos, assim,\nCONCORDAR que:","options":{"A":"A prevalência é um indicador da magnitude da carga atual que a doença representa para os\nserviços de saúde e para a sociedade, bem\ncomo um preditor da futura carga que as complicações\ncrônicas do diabetes representarão.","B":"A prevalência é um indicador da magnitude da carga atual que a doença não representa para os\nserviços de saúde e para a sociedade, bem como um preditor da futura carga que as complicações\ncrônicas do diabetes representarão.","C":"A prevalência é um indicador da magnitude da carga atual que a doença representa para os\nserviços de saúde e para a sociedade, bem\ncomo um preditor da futura carga que as complicações\nagudas apenas do diabetes.","D":"A prevalência é um indicador da magnitude da carga atual que a doença representa para os\nserviços de saúde, mas não para a sociedade, bem como um preditor da futura carga que as\ncomplicações crônicas do diabetes representarão."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-216336","number":"216336","sourceNumber":"216336","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Infelizmente, muitos governos, sistemas de saúde pública e profissionais de saúde\nainda não se conscientizaram da atual relevância do diabetes e de suas complicações, sendo\nADEQUADO o seguinte item:","options":{"A":"a Organização Mundial da Saúde (OMS) estima que glicemia elevada é o terceiro fator, em\nimportância, da causa de mortalidade prematura, superada, apenas, por pressão arterial\naumentada e uso de tabaco.","B":"a Organização Mundial da Saúde (OMS) estima que glicemia elevada não é fator de importância,\nda causa de mortalidade prematura, superada,\napenas, por pressão arterial aumentada e uso de\ntabaco.","C":"a Organização Mundial da Saúde (OMS) estima que glicemia elevada é o terceiro fator, em\nimportância, da causa de mortalidade prematura, não superada por pressão arterial aumentada e\nuso de tabaco.","D":"a Organização Mundial da Saúde (OMS) estima que glicemia elevada é o terceiro fator, em\nimportância, da causa de mortalidade prematura, superada, apenas, por pressão arterial\naumentada, mas não pelo uso de tabaco."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-180140","number":"180140","sourceNumber":"180140","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Gestante\napresenta quadro de embolia pulmonar maciça durante o trabalho de parto de gravidez a termo.\nPermaneceu na UTI e teve seu óbito constatado após 30 dias do parto. Qual o tipo de morte?","options":{"A":"Materna obstétrica direta.","B":"Materna não obstétrica.","C":"Pós-materna.","D":"Não materna, pois ocorreu após 20 dias do parto.","E":"Materna obstétrica indireta."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-181394","number":"181394","sourceNumber":"181394","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa correta em relação às condições de saúde da população\nbrasileira.","options":{"A":"Na transição epidemiológica, observa-se o deslocamento do eixo principal de morbimortalidade\nde doenças infecciosas e problemas\nmaterno-infantis para doenças crônico-degenerativas e causas\nexternas.","B":"No Brasil, a fase atual da transição epidemiológica se expressa pela diminuição do coeficiente\nde mortalidade por doenças do aparelho circulatório\ne manutenção das doenças infecciosas e\nparasitárias.","C":"Com a melhoria do acesso da população aos serviços básicos de saúde nas últimas décadas,\nhouve uma redução na incidência de agravos à\nsaúde e na mortalidade.","D":"Todas as internações hospitalares, incluindo as da rede privada, alimentam o Sistema de\nInformações Hospitalares (SIH/SUS).","E":"As estatísticas de serviços de saúde sobre morbidade também levam em consideração a\nmorbidade autorreferida."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-187851","number":"187851","sourceNumber":"187851","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual a PRINCIPAL CAUSA de óbito entre os adolescentes no Brasil?","options":{"A":"Causas externas: violência","B":"Doenças do aparelho respiratório","C":"Doenças infecciosas","D":"Neoplasias"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-187799","number":"187799","sourceNumber":"187799","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considerando os indicadores de saúde baseados na mortalidade, é CORRETO afirmar\nque:","options":{"A":"A principal vantagem da taxa de mortalidade geral é o fato de levar em conta que o risco de\nmorrer varia conforme o sexo, idade, raça e classe social.","B":"As mudanças nas taxas de mortalidade, com o passar do tempo, são, em geral, de pequena\namplitude, o que as torna muito úteis para avaliação de curto prazo.","C":"O coeficiente de mortalidade infantil precoce tende a ser percentualmente maior que o\ncoeficiente de mortalidade infantil tardio em países subdesenvolvidos.","D":"O uso de coeficientes gerais de mortalidade em comparações populacionais reflete mais\nadequadamente a realidade quando não ajustado."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-187801","number":"187801","sourceNumber":"187801","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em Areia Branca, município com uma população de 1.200.000 habitantes, foram\nnotificados 600 casos de febre amarela. 120 mortes foram comprovadamente, causadas pela\ndoença. Qual foi o percentual de letalidade da doença neste caso?","options":{"A":"20%","B":"2%","C":"0,02%","D":"0,5%"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-182734","number":"182734","sourceNumber":"182734","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Paciente opta por parto domiciliar acompanhado somente por Enfermeira de sua\nconfiança. Durante o procedimento ocorre óbito\nmaterno por sangramento vaginal incontrolável. O\nresponsável pela Declaração de Óbito, nesse caso, é:","options":{"A":"a Enfermeira que acompanhou o parto","B":"o Médico Plantonista do hospital para onde será encaminhado o corpo da puérpera","C":"o Diretor Clínico da maternidade que receberá o corpo da puérpera","D":"o IML"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-183046","number":"183046","sourceNumber":"183046","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Aterosclerose é a maior causa de morte e invalidez em diabéticos, especialmente do\ntipo 2, sendo que a Doença Arterial Obstrutiva Periférica (DAOP) caracteriza-se pela obstrução\naterosclerótica progressiva das artérias dos membros inferiores, afetando a qualidade de vida\ndesses pacientes. Sobre isso, assinale a afirmativa considerada INCORRETA:","options":{"A":"A DAOP é um importante marcador da terosclerose sistêmica e do risco de complicações\ncardiovasculares e cerebrovasculares, como o Infarto Agudo Do Miocárdio (IAM) e o Acidente\nVascular Cerebral (AVC), em especial nos pacientes diabéticos.","B":"A aterosclerose é a maior causa de morte e invalidez em diabéticos, especialmente do tipo 2 .","C":"Em fases iniciais a DAOP costuma ser assintomática, embora cerca de 1/3 dos pacientes\ndesenvolva Claudicação Intermitente (CI), o sintoma mais comum da DAOP.","D":"Em estágios avançados, o quadro clínico mais evidente pode ser dor em repouso, mas sem\nrelação com uma ferida que não cicatriza."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-183071","number":"183071","sourceNumber":"183071","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Presumivelmente, os benefícios demonstrados sobre LOA na população geral não\ndeveriam ser diferentes daqueles na\npopulação idosa. Contudo diretrizes internacionais recentes\ntêm preconizado metas pressóricas mais conservadoras para idosos e aqueles com alto risco CV,\nincluindo diabéticos, principalmente pela falta de evidências que suportem recomendações em\ndiferentes perfis de pacientes. Sobre esse tema, assinale a alternativa considerada INADEQUADA:","options":{"A":"O mecanismo mais comum da HA no idoso é o enrijecimento da parede arterial dos grandes\nvasos, levando a aumento predominante da PAS,\ncom manutenção ou queda da PAD.","B":"Em indivíduos maior ou igual 80 anos, realizaram-se estudos com fármacos anti-hipertensivos\nnaqueles com PA maior ou igual 160 mmHg, com\ndemonstração de resultados favoráveis, em\nespecial na prevenção de IC.","C":"Assim, recomenda-se o início da terapia farmacológica anti-hipertensiva em idosos a partir de\nníveis de PAS maior ou igual 180 mmHg, desde que bem tolerado e avaliando-se as condições\ngerais do indivíduo.","D":"Nos muito idosos, ou seja, naqueles com idade maior ou igual 80 anos, o limite para início da\nterapia farmacológica aumenta para uma PAS maior ou igual 160 mmHg."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-158826","number":"158826","sourceNumber":"158826","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma localidade brasileira, com uma população de 8.000.000 de habitantes,\nocorreram 89.000 mortes no ano de 2015, entre as\nquais 4.500 óbitos por cóleta em 86.000\npessoas que tiveram a doença no ano de 2015. A taxa de mortalidade por cólera e a letalidade da\ndoença, nesse ano, foram","options":{"A":"5,62 e 10,75, por 1.000 habitantes.","B":"5,62 e 52,32 por 1.000 habitantes.","C":"10,18 e 10,56, por 1.000 habitantes.","D":"10,75 e 11,12, por 1.000 habitantes.","E":"11,12 e 52,32, por 1.000 habitantes."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-158829","number":"158829","sourceNumber":"158829","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O aumento de 268% do índice de envelhecimento no Brasil, no período de 1970 a\n2010, e a redução da taxa de fecundidade representam:","options":{"A":"Contratransição.","B":"Morte prematura.","C":"Transição demográfica.","D":"Transição epidemiológica.","E":"Razão de mortalidade proporcional."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-158759","number":"158759","sourceNumber":"158759","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Segundo dados do Ministério da Saúde, os principais grupos de causas de morte, no\nBrasil, em 2012, em ordem decrescente da taxa de mortalidade proporcional, foram:","options":{"A":"Doenças do aparelho digestivo, doenças do aparelho circulatório, causas externas.","B":"Doenças do aparelho circulatório, doenças do aparelho respiratório, neoplasias.","C":"Doenças do aparelho respiratório, neoplasias e doenças do aparelho digestivo.","D":"Doenças do aparelho respiratório, causas externas, neoplasias.","E":"Doenças do aparelho circulatório, neoplasias e causas externas."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-140167","number":"140167","sourceNumber":"140167","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, a transição epidemiológica não tem ocorrido de acordo com o modelo\nexperimentado pela maioria dos países industrializados e mesmo por vizinhos latino-americanos\ncomo Chile, Cuba e Costa Rica. Em relação ao processo de transição epidemiológica no Brasil, é\ncorreto afirmar que:","options":{"A":"há superposição entre as etapas nas quais predominam as doenças transmissíveis e doenças\ncrônicas não transmissíveis;","B":"há deslocamento da carga de morbimortalidade dos grupos mais idosos para os grupos mais\njovens;","C":"há transformação de uma situação em que predomina a morbidade para outra na qual a\nmortalidade é dominante;","D":"há substituição das doenças transmissíveis por doenças cardiovasculares e causas externas;","E":"há um movimento de ?contratransição? representado pelo ressurgimento de doenças como a\nmalária, o cólera e a dengue, com grande importância na mortalidade, mas sem grande\ninterferência na morbidade."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134356","number":"134356","sourceNumber":"134356","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de saúde são parâmetros utilizados com a finalidade de avaliar, sob o\nponto de vista sanitário, a higidez de agregados humanos, bem como de fornecer subsídios aos\nplanejamentos de saúde. A respeito desses indicadores, é CORRETO afirmar que:","options":{"A":"O coeficiente de incidência mede o risco da doença e a velocidade com que os casos antigos\nsão agregados.","B":"O coeficiente de mortalidade infantil estima o risco de um nascido vivo morrer durante o seu\nprimeiro ano de vida. Reflete o nível de saúde e as condições de vida da população.","C":"O coeficiente de incidência não é útil no estudo da etiologia das doenças, contudo é um\nindicador importante para analisar o perfil de saúde de uma população.","D":"O coeficiente da prevalência, tal qual a incidência, não só mede o risco da doença,\ncomo também mede a força com que determinados\nagravos ?se acumulam? nas populações."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134080","number":"134080","sourceNumber":"134080","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um dos indicadores utilizados para avaliação da qualidade do pré-natal é o número de\nconsultas realizadas pelas gestantes durante a gravidez. A MELHOR maneira de sistematizar esse\ntipo de dado, isoladamente, para tal avaliação, é:","options":{"A":"calcular o percentual de gestantes que realizaram mais de 6 consultas de pré-natal.","B":"verificar se a média de consultas realizadas pelas gestantes durante o pré-natal é superior ou\ninferior a 6.","C":"verificar o número de gestantes que realizaram mais de 6 consultas de pré-natal.","D":"calcular o percentual de gestantes que realizaram mais de 6 consultas de pré-natal, dentre as\nque ingressaram no 3º trimestre de gestação."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134282","number":"134282","sourceNumber":"134282","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A população do município de Aurora em 2014 era de 150.000 habitantes. Neste ano,\nforam diagnosticados 60 casos de tuberculose. Além destes casos, 30 casos de tuberculose\ndiagnosticados em 2013 continuavam em tratamento em 2014. Durante o ano de 2014, 10 casos\nforam a óbito. Responda: qual foi a incidência de tuberculose em 2014?","options":{"A":"6 casos por 10.000 habitantes.","B":"3,3 casos por 10.000 habitantes.","C":"4 casos por 10.000 habitantes.","D":"5,3 casos por 10.000 habitantes."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134817","number":"134817","sourceNumber":"134817","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre Razões de Mortalidade Materna, é CORRETO afirmar que,","options":{"A":"Os valores elevados de mortalidade materna correlacionam-se com precárias condições\nsocioeconômicas, baixos índices de escolaridade, violência doméstica e precariedade de acesso\naos Serviços de Saúde.","B":"Correspondem à razão mortalidade materna por 10.000 nascidos vivos.","C":"As razões da mortalidade materna correlacionam-se, principalmente, com a qualidade dos\nServiços de Saúde.","D":"Os valores da mortalidade materna diminuíram a partir de 1999 devido à diminuição progressiva\nnas taxas de fecundidade."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134309","number":"134309","sourceNumber":"134309","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Mulher com 18 anos de idade, solteira, primigesta, decidiu interromper sua gravidez\nindesejada, procurando uma clínica clandestina\nde aborto. Após o procedimento, a paciente foi\nliberada para casa com fortes dores pélvicas. Não procurou atendimento imediato com medo de ser\ndiscriminada, ou mesmo presa, por ter feito um aborto ilegal. Após três dias, com febre alta e\nfortes\ndores, procurou a Maternidade, onde foi internada com diagnóstico de abortamento infectado. A\ndespeito do tratamento antimicrobiano, o quadro clínico da paciente deteriorou e ela evoluiu em 48\nhoras para um quadro de abdome agudo. Foi realizada laparotomia exploradora, sendo\nevidenciadas diversas perfurações em alças intestinais, com presença de material fecaloide e\npurulento em cavidade peritoneal, sendo a paciente tratada com sutura intestinal e limpeza\nexaustiva da cavidade. Encaminhada à Unidade de Terapia Intensiva, a paciente não teve\nmelhora, tendo sido submetida a histerectomia abdominal total dois dias após. No\n\npós-operatório, evoluiu com choque séptico, necessitando da introdução de drogas vasoativas.\nPermaneceu mais 50 dias internada, evoluindo com insuficiência renal e falência múltipla de\nórgãos, vindo a falecer 60 dias após a realização do aborto. Ao analisar esse óbito, o médico\nresponsável pelo Comitê de Prevenção e Controle da Mortalidade Materna deve atestar que:","options":{"A":"Trata-se de morte materna de causa evitável decorrente de erro médico, devido a perfurações\nuterinas, que causam peritonite e\n\nsepse.","B":"Não é caso de morte materna, pelo fato de o óbito ter ultrapassado 42 dias após o término da\ngestação.","C":"Trata-se de morte materna de causa obstétrica indireta devido a complicações infecciosas na\ngravidez.","D":"Trata-se de morte materna de causa obstétrica direta devido a complicações do abortamento."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134093","number":"134093","sourceNumber":"134093","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a Transição Epidemiológica, assinale a alternativa INCORRETA.","options":{"A":"Seu conceito se refere às modificações, a longo prazo, dos padrões de morbidade,\ninvalidez e morte que caracterizam uma\n\npopulação específica.","B":"Ocorre de forma lenta, no Brasil, com a superposição de causas agudas e crônicas.","C":"Consiste na transformação de uma situação em que predomina a mortalidade para outra em que\na morbidade (doenças crônicas)\n\né dominante.","D":"É fruto exclusivamente da evolução médico-tecnológica."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-110540","number":"110540","sourceNumber":"110540","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, qual a principal causa de mortalidade materna?","options":{"A":"Infecções.","B":"Hemorragias.","C":"Síndromes hipertensivas.","D":"Diabetes gestacional.","E":"Prenhez ectópica."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-110006","number":"110006","sourceNumber":"110006","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Coeficiente de Mortalidade Geral não deve ser utilizado em sua forma bruta para\ncomparar populações diferentes. A padronização\ndesse Coeficiente é MAIS comumente indicada\nquando, entre as populações a serem comparadas, existem diferenças significativas de","options":{"A":"qualidade dos registros de óbitos.","B":"estrutura da pirâmide etária.","C":"razão de masculinidade muito dispare.","D":"cobertura dos programas de saúde."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-110549","number":"110549","sourceNumber":"110549","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Observe a curva de mortalidade proporcional de um município alagoano e escolha a\nalternativa correta (VER IMAGEM) :","options":{"A":"A curva demonstra um nível de saúde regular, devido à grande proporção de óbitos entre\npessoas com mais de 50 anos.","B":"As grandes proporções de óbitos em menores de 1 ano e entre pessoas em idade produtiva\ncaracterizam um nível de saúde muito baixo.","C":"Apesar da elevada proporção de óbitos em menores de um ano, a proporção de óbitos entre\nindivíduos de 50 anos ou mais é compatível com localidades com bom nível de saúde.","D":"As proporções de óbitos em todas as faixas etárias encontram-se com valores acima do\ndesejável para um bom nível de saúde.","E":"A elevada proporção de óbitos em menores de um ano por si só já justifica a classificação da\nlocalidade como baixo nível de saúde."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-110555","number":"110555","sourceNumber":"110555","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Atualmente no Brasil, a mortalidade infantil tem apresentado forte componente de:","options":{"A":"mortalidade neonatal tardia.","B":"mortalidade neonatal precoce.","C":"mortalidade perinatal.","D":"mortalidade pós neonatal.","E":"antenatal."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-110568","number":"110568","sourceNumber":"110568","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O gráfico abaixo representa a ocorrência de casos de determinada doença.\nConsiderando os conceitos de prevalência e incidência, indique a alternativa correta (VER\nIMAGEM).","options":{"A":"2002 foi o ano de maior incidência da doença.","B":"2001 foi o ano de menor prevalência.","C":"2004 foi o ano de maior prevalência.","D":"2003 foi o ano de maior incidência.","E":"Em 2005, foram registrados quatro novos casos da doença."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-110067","number":"110067","sourceNumber":"110067","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Mais de 90% das mortes maternas são passíveis de prevenção. Porém, em nosso país,\nsuas taxas permanecem elevadas. Aponte a afirmação CORRETA.","options":{"A":"Define-se como mortalidade materna aquela que ocorre durante a gravidez até 6 meses do\nparto.","B":"As hemorragias, pré-eclâmpsia e infecções puerperais são exemplos de mortalidade por causas\nobstétricas indiretas.","C":"As mortes decorrentes de cardiopatias, diabetes e colagenoses são exemplos de morte por\ncausa obstétrica direta.","D":"Cerca de 80% das mortes maternas registradas são decorrentes de mortes de causas\nobstétricas diretas."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-86606","number":"86606","sourceNumber":"86606","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os últimos recenseamentos mostram aumento no número de idosos no Brasil e\ndiminuição na taxa de fecundidade. Esse processo traduz-se por:","options":{"A":"Transição epidemiológica.","B":"Transição demográfica.","C":"Transição epistemológica.","D":"Indicador Swaroop-Uemura.","E":"Envelhecimento saudável."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-86614","number":"86614","sourceNumber":"86614","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de saúde são parâmetros utilizados com a finalidade de avaliar, sob o\nponto de vista sanitário, a higidez de agregados humanos, bem como de fornecer subsídios aos\nplanejamentos de saúde. A respeito desses indicadores, é CORRETO afirmar:","options":{"A":"O coeficiente de incidência mede o risco da doença e a velocidade com que os casos antigos\nsão agregados.","B":"O coeficiente de mortalidade infantil estima o risco de um nascido vivo morrer durante o seu\nprimeiro ano de vida. Reflete o nível de saúde e as condições de vida da população.","C":"O coeficiente de incidência não é útil no estudo da etiologia das doenças, contudo é um\nindicador importante para analisar o perfil de saúde de uma população.","D":"O coeficiente da prevalência, tal qual a incidência, não só mede o risco da doença, como\ntambém mede a força com que determinados agravos ?se acumulam? nas populações.","E":"A razão de mortalidade proporcional ou índice de SWAROOP-UEMURA é a proporção de óbitos\nde indivíduos com 60 anos ou mais em relação ao\ntotal de óbitos."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-86853","number":"86853","sourceNumber":"86853","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Leia o trecho a seguir: A mortalidade infantil em Alagoas caiu em 83% em 22 anos,\nsegundo atesta o Fundo das Nações Unidas para\na Infância (Unicef). O índice foi o maior do país\ndurante o período pesquisado. Segundo o governo, ações da Secretaria de Estado da Saúde\n(Sesau) têm surtido efeito positivo, já que entre 2007 e 2012 o percentual de mortalidade infantil\ncaiu 36,13%, passando de 21,57 mortes para cada mil nascidos vivos, para 15,19 mortes para cada\nmil nascidos vivos. De acordo com o Unicef, a redução da mortalidade infantil detectada em\nAlagoas é superior à nacional, que correspondeu a 77% entre os anos de 1990 e 2012. Uma\nevolução positiva que, segundo o Unicef, ?é uma das mais significativas registradas pelo\nlevantamento, realizado em 196 países?. Ainda de acordo com os dados divulgados nesta\n\nsexta-feira (13), a redução constatada em Alagoas é superior a do Nordeste, que foi de 77,5%, e\nficou à frente do Ceará (82%), Paraíba (81%), Pernambuco (80,9%) e Rio Grande do Norte\n(79,3%).\n\nFonte: site online de notícias de Alagoas.\n\nQuanto à Taxa de Mortalidade Infantil (Coeficiente de Mortalidade Infantil), assinale a CORRETA:","options":{"A":"A taxa de mortalidade neonatal Precoce não tem impacto sobre a taxa de mortalidade infantil.","B":"Seu uso não contribui na avaliação dos níveis de saúde e de desenvolvimento socioeconômico\nda população.","C":"Não há limitações em sua interpretação e em seu cálculo.","D":"Sua redução não faz parte das Metas do Desenvolvimento do Milênio, carta da ONU do qual o\nBrasil é signatário.","E":"Número de óbitos de menores de um ano de\nidade, por mil nascidos vivos na população\n\nresidente em determinado espaço geográfico, no ano considerado."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-86857","number":"86857","sourceNumber":"86857","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A taxa atual ( 15,19/1000 nascidos vivos) é semelhante à dos países desenvolvidos no\nfinal da década de 60, e cerca de três a cinco vezes maior do que a de países como Japão,\nCanadá, Cuba, Chile e Costa Rica, que apresentam taxas entre 3 e 10/1000 nascidos vivos\n(FUNDO DAS NAÇÕES UNIDAS PARA A INFÂNCIA, 2008a). Os níveis atuais ainda são\nconsiderados elevados e incompatíveis com o desenvolvimento do País, quais ações podem\ncontribuir para sua redução?","options":{"A":"Investigação de óbitos fetais.","B":"Ampliar e organizar a assistência neonatal.","C":"Consolidar a atenção perinatal.","D":"Enfrentar as diferenças socioeconômicas\nregionais.","E":"Todas acima."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-13158","number":"13158","sourceNumber":"13158","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Na avaliação de serviços ou de programas de saúde, um dos indicadores é a estimativa\nda efetividade, assim definida:","options":{"A":"Estimativa do prazer em trabalhar dos profissionais de saúde.","B":"Estimativa da qualidade de vida das pessoas participantes.","C":"Quando envolve crianças, afere os cuidados às mesmas.","D":"Quando envolve pessoas idosas, afere os riscos coronarianos.","E":"NDA."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-13163","number":"13163","sourceNumber":"13163","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Coeficiente de letalidade corresponde:","options":{"A":"(Números de óbitos por dada doença / número de casos dessa doença) x 100.","B":"(Número de óbitos por dado sexo / número da população) x 1.000.","C":"(Número de óbitos de dada faixa etária / número da população) x 10.000.","D":"(Número total de óbitos / número da população geral) x 100.","E":"(Número total de óbitos / números da população exposta) x 100."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-252300","number":"252300","sourceNumber":"252300","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Dentro de uma situação de um perfil epidemiológico em que antes prevaleciam doenças\ninfectocontagiosas e agora prevalecem doenças cardiovasculares (crônicas não transmissíveis),\nmuito relacionada a uma maior expectativa de vida, denomina-se:","options":{"A":"Transição epidemiológica.","B":"Transição demográfica.","C":"Transição social.","D":"Transição nutricional."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-176122","number":"176122","sourceNumber":"176122","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Nas últimas décadas, as Doenças e Agravos Não Transmissíveis (DANT) assumiram a\nliderança entre as causas de óbito no Brasil. Referente à vigilância das DANT, podemos afirmar:","options":{"A":"O laboratório de saúde pública tem papel central na detecção precoce das doenças.","B":"Um sistema de vigilância das DANT necessita de vigilância integrada e estruturada dos fatores\nde risco.","C":"Para a vigilância das DANT é importante levar em conta o interesse maior da sociedade para\naquelas doenças com maior virulência; com detecção rápida pela rede de urgência e emergência.","D":"Uma integração maior com os serviços de saúde pública veterinária ajuda a incrementar a\noportunidade de detecção das doenças."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-176120","number":"176120","sourceNumber":"176120","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considerando que os Sistemas de Informação (SI) estão passando por muitas\ntransformações acompanhando a implantação do Sistema\nÚnico de Saúde (SUS) e a ampliação do\nuso da epidemiologia nos serviços de saúde, assinale a alternativa CORRETA:","options":{"A":"Os SI disponíveis no SUS, que são de base hospitalar, são três (03): o Sistema de Informações\nde Agravos Sob Notificação (SINAN), O Sistema de\nInformações de Mortalidade (SIM) e o Sistema\nde Informações sobre Nascidos Vivos (SINASC).","B":"Com as mudanças na política de saúde, os SI passaram a ser gerenciados e utilizados pelos\nserviços geradores dos dados, em especial os Estados e as suas unidades de saúde de média\ncomplexidade.","C":"O Sistema de Cadastramento e Acompanhamento de Hipertensos e Diabéticos (HIPERDIA) e o\nSistema de Informações do Câncer da Mulher (SISCAM) não podem ser considerados SI, pois\nabordam grupos de agravos.","D":"Um dos desafios atuais nos SI é o da disseminação da informação, cabendo destacar os\nrelatórios e boletins realizados pelos serviços de saúde, além do site do Datasus como fonte de\ninformação."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-176084","number":"176084","sourceNumber":"176084","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os Determinantes Sociais da Saúde (DSS) são uma pauta \"de primeira ordem\" quando\nse abordam a relação do sistema de saúde e a\nsociedade. Referente aos DSS, assinale a\nCORRETA:","options":{"A":"Os DSS podem ser entendidos como as condições sociais a que estão submetidas as pessoas\nno viver e trabalhar; aqui estão a maior\nparte dos problemas de saúde.","B":"A atuação sobre os diversos níveis dos DSS é de competência e atribuição exclusiva das\ninstituições de saúde.","C":"Um termo muito utilizado nos DSS é o de iniquidades, aqui tido como ?não lidar igualmente com\nos iguais ? pessoas?.","D":"Há uma correlação constante entre os macroindicadores de riqueza de uma sociedade e outros,\ncomo o produto interno bruto e os\nindicadores de saúde."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-107614","number":"107614","sourceNumber":"107614","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A população idosa se diferencia por possuir uma série de características próprias com\nrelação ao processo de saúde - doença, portanto, marque a alternativa INCORRETA:","options":{"A":"O MFC deve fazer um balanço entre os riscos e benefícios na investigação de anormalidades\nem um teste de rastreamento, pois na população\nidosa as alterações se explicam pela própria\nfisiologia do envelhecimento.","B":"A velhice não é uma enfermidade e sim uma etapa evolutiva da vida.","C":"As 3 trajetórias que a doença crônica no idoso segue são: evidente declínio em curto período de\ntempo, longo período de limitações com exacerbação e morte súbita, prolongada decadência.","D":"Os objetivos da prevenção no cuidado do idoso é direcionado à redução da morbimortalidade."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-107627","number":"107627","sourceNumber":"107627","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à saúde do homem pode-se afirmar:","options":{"A":"Homens morrem entre 10 e 15 anos depois das mulheres.","B":"O esteriótipo de provedor e de homem invulnerável e o medo de descobrir doenças são barreiras\nsócioculturais que dificultam o acesso dos homens ao serviços de atenção primária à saúde.","C":"No Brasil se destacam as neoplasias como principal causa de morte entre os homens.","D":"O horário de funcionamento do posto de saúde facilita o acesso à atenção primária de saúde."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-107635","number":"107635","sourceNumber":"107635","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à Saúde Infantil, qual das seguintes alternativas está incorreta em relação\nàs características que determinam menos ou mais\nagravos?","options":{"A":"Dinâmica familiar.","B":"Baixo peso ao nascer.","C":"Presença paterna no pré-natal.","D":"Deficiências imunológicas."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-81964","number":"81964","sourceNumber":"81964","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à Política Nacional de Atenção Integral à Saúde do Homem podemos\nafirmar que:","options":{"A":"Observa que o ingresso da população masculina nos serviços de saúde ocorre através da\natenção especializada, com menor morbidade e menor custo para o Sistema Único de Saúde.","B":"Avalia a homogeneidade da construção sociocultural e histórica da masculinidade de modo a\npromover uma atenção à saúde com mais equidade.","C":"Aborda a questão relacional da dinâmica de casal de forma a particularizar as questões\nmasculinas e as femininas, tendo uma relação\ndireta com a Política Nacional de Atenção Integral à\nSaúde da Mulher.","D":"Visa garantir ações e serviços de saúde que atuem na prevenção, assistência e recuperação da\nsaúde da população masculina exclusivamente\nna faixa etária de 25 a 69 anos.","E":"Busca mobilizar a população masculina para garantir seu direito social à saúde, tornando-os\nprotagonistas de seus direitos de cidadania."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-82008","number":"82008","sourceNumber":"82008","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A acolhida aos cidadãos usuários e aos cidadãos trabalhadores de saúde nos serviços\nde saúde é um dos desafios do Sistema Único de\nSaúde e a Política Nacional de Humanização da\nAtenção e Gestão preconiza que:","options":{"A":"Os usuários do sistema de saúde devem restabelecer a universalidade de acesso ao sistema de\nsaúde, tendo o acolhimento como forma pontual e restrita a demanda espôntanea.","B":"Os atores exclusivos do acolhimento, que farão as mudanças no cotidiano das práticas dos\nserviços de saúde, são as três esferas de\npoder (municipal, estadual e federal) e a sociedade civil,\npricipalmente através do Controle Social.","C":"O acolhimento deve ser prática nas ações de atenção e gestão nas unidades de saúde de modo\na construir uma relação de confiança e\ncompromisso entre os usuários e as equipes.","D":"Construa-se uma rede de autonomia e compartilhamento entre servidores da saúde e gestores\nfomentando a co-responsabilização entre ambos.","E":"O acolhimento como ação técnico-assistencial possibilite a análise do processo de trabalho em\nsaúde com foco nas ações de saúde."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-82002","number":"82002","sourceNumber":"82002","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a vacinação contra Hepatite B e as diretrizes do Programa Nacional de\nImunizações (PNI) está correto afirmar:","options":{"A":"que a vacinação contra hepatite B está disponível atualmente na rede pública de saúde para\nmenores de 49 anos, de ambos os sexos.","B":"que a vacina é uma forma eficaz de evitar a hepatite B e deve ser feita em grupos mais expostos\nà doença como manicures, bombeiros e\ndomésticas.","C":"até 2012, esta vacina estava disponível gratuitamente apenas para menores de 39 anos e\ngestantes.","D":"esta vacina deve ser feita em três doses com intervalo de dois meses entre cada dose.","E":"a vacina só deve ser feita após o segundo mês de vida da criança."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-82016","number":"82016","sourceNumber":"82016","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Nas últimas décadas, as Doenças e Agravos Não Transmissíveis (DANT) assumiram a\nliderança entre as causas de óbito no país. Referente às DANT, assinale a alternativa que condiz\ncom a política atual de estruturação desta vigilância (doenças crônicas):","options":{"A":"Como resultado desta vigilância, foram planejados o Programa de Controle da Malária.","B":"Uma das estratégias para o fortalecimento desta vigilância é o acesso garantido aos bancos de\ndados de nascidos vivos.","C":"A estruturação desta vigilância teria como um de seus alicerces a sensibilização e demonstração\ndos impactos nos custos diretos e indiretos do\nsurto de DANT.","D":"Há a necessidade real de incorporação (nesta vigilância) da vigilância das doenças\ntransmissíveis e das doenças emergentes e reemergentes.","E":"Uma das linhas de ação desta vigilância é a vigilância dos fatores de risco."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-60859","number":"60859","sourceNumber":"60859","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Das definições a seguir,qual é a CORRETA?","options":{"A":"Morte materna direta é a morte materna causada por quaisquer complicações desde que no\nperíodo da gestação, parto ou puerpério.","B":"Taxa de natalidade é o número de nascidos vivos para cada 100.000 habitantes.","C":"Taxa de fertilidade é o número de nascidos vivos para cada 100.000 mulheres com idade entre\n15 e 44 anos.","D":"Razão de mortalidade materna é o número de mortes maternas resultantes do processo\nreprodutivo para cada 100.000 nascidos vivos.","E":"Aborto é feto ou embrião removido ou expelido do útero antes de 22 semanas de gestação ou\npeso inferior a 500 g."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-61548","number":"61548","sourceNumber":"61548","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"São restrições ao uso dos indicadores de saúde, EXCETO:","options":{"A":"avaliação da situação de saúde por dados de \"não saúde\".","B":"não considerar os fatores socioeconômicos e ambientes em seu cálculo.","C":"são médias aritméticas de dados e registros sujeitos a erro e manipulação.","D":"diagnóstico de saúde de uma comunidade e planejamento de ações.","E":"não caracterizam uma situação de saúde SE considerados isoladamente."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-61483","number":"61483","sourceNumber":"61483","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A incorporação de novos tratamentos para a AIDS, com inibidores da protease, que\ninfelizmente não promovem a cura, podem produzir, no entanto, o seguinte efeito:","options":{"A":"aumento da incidência.","B":"aumento da prevalência.","C":"diminuição da incidência.","D":"diminuição da prevalência.","E":"declínio da prevalência com aumento da incidência."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-61487","number":"61487","sourceNumber":"61487","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Dos indicadores listados abaixo, qual é o mais influenciado por fatores\nsocioeconômicos?","options":{"A":"Natimortalidade.","B":"Mortalidade neonatal.","C":"Mortalidade perinatal.","D":"Mortalidade neonatal tardia.","E":"Mortalidade pós-neonatal."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-61493","number":"61493","sourceNumber":"61493","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A razão de mortalidade proporcional significa, EXCETO:","options":{"A":"Considera variáveis socioeconômicas em seus cálculos para permitir comparações.","B":"Bom indicador de saúde pela facilidade de cálculo e disponibilidade de dados.","C":"Permite a análise das condições de vida.","D":"Índice de Swaroop-Uemura.","E":"Óbitos de maiores de 50 anos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-46732","number":"46732","sourceNumber":"46732","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a mortalidade materna, marque a alternativa INCORRETA:","options":{"A":"No Brasil, dois fatores dificultam o real monitoramento do nível e da tendência da mortalidade\nmaterna: a subinformação, que resulta o preenchimento incorreto das declarações de óbito, e o\nsub-registro, que consiste na omissão do registro do óbito em cartório.","B":"A mortalidade materna é uma das mais graves violações dos direitos humanos das mulheres,\npor ser uma tragédia evitável em 92% dos casos,\ne por ocorrer principalmente nos países em\ndesenvolvimento.","C":"As altas taxas encontradas se configuram como uma violação dos direitos humanos de mulheres\ne crianças e um grave problema de saúde\npública, atingindo igualmente as regiões brasileiras.","D":"Morte Materna (óbito Materno) é a morte de uma mulher durante a gestação ou até 2 meses\napós o término da gestação,\nindependentemente da duração ou da localização da gravidez.","E":"Nas Américas, há disparidade nas taxas de mortalidade materna entre países desenvolvidos e\nem desenvolvimento."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-26519","number":"26519","sourceNumber":"26519","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em meados da década de 1980, com surgimento de casos HIV/AIDS, até então\ndesconhecidos, aumentou o número de casos de tuberculose. Esse aumento é medido e\nobservado pelas agências de Vigilância Epidemiológica, por meio do seguinte indicador:","options":{"A":"letalidade;","B":"prevalência;","C":"mortalidade;","D":"mortalidade proporcional;","E":"incidência;"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-26521","number":"26521","sourceNumber":"26521","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O coeficiente da mortalidade infantil, apesar de ser um indicador muito utilizado em\nsaúde pública, está sujeito a distorções devido,\ndentre outros fatores, a:","options":{"A":"não considerar, em seus cálculos, os óbitos;","B":"erro na contagem do denominador decorrente da não-inclusão dos óbitos de crianças não\nresidentes na localidade;","C":"erro na contagem do denominador decorrente da não-inclusão de nascimentos de crianças não\nresidentes na localidade;","D":"sub-registro de óbitos e de nascimentos;","E":"considerar, em seu denominador, os nascidos vivos;"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-26523","number":"26523","sourceNumber":"26523","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As doenças crônicas são:","options":{"A":"a principal causa de morte nos países desenvolvidos, mas no Brasil, são a segunda causa de\nmorte;","B":"a principal causa de morte em todo mundo, inclusive no Brasil e nos países em\ndesenvolvimento;","C":"a 2ª causa de morte em todo mundo e a 1ª nos países desenvolvidos;","D":"a 2ª causa de morte nos países desenvolvidos e a 1ª no mundo;","E":"sem importância em nível mundial, mas são a principal causa de morte nos países\nnão-desenvolvidos;"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-26530","number":"26530","sourceNumber":"26530","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa correta:","options":{"A":"o surgimento de uma terapêutica que cure uma doença tem capacidade de reduzir sua\nincidência;","B":"tanto a incidência acumulada quanto a taxa de prevalência medem diretamente o risco de\nadoecimento;","C":"somente a incidência mede diretamente o risco de adoecimento;","D":"o surgimento de uma terapêutica que cure uma doença tem capacidade de reduzir sua\nincidência e sua prevalência;","E":"na medida da prevalência pontual, levam-se em conta pessoas que já estiveram doentes e estão\ncuradas no presente;"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-26532","number":"26532","sourceNumber":"26532","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à transição demográfica no Brasil, pode-se dizer que o envelhecimento da\npopulação nos últimos anos:","options":{"A":"processou-se de forma abrupta, muito mais rápida do que nos países europeus.","B":"é pouco relevante para a saúde no que se refere às demandas atuais por atenção médica.","C":"se deve ao processo da distribuição mais eficiente das consultas médicas, que reduziram a taxa\nde mortalidade brasileira.","D":"se deve ao Programa Nacional de Controle da Natalidade, implantado pelo Ministério da Saúde,\ndesde 1977.","E":"não deve ser ainda considerado no conjunto das políticas públicas para saúde."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-26526","number":"26526","sourceNumber":"26526","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Identifique a informação relacionada à nova regulamentação de Vigilância de Óbitos\nMaternos (Portaria GMMS Nº 1.119, de 5 de junho de 2008).","options":{"A":"para computo da razão de mortalidade materna, serão incluídos os casos de óbitos ocorridos\nentre 42 dias e 1 ano após término da\ngestação.","B":"prazo de 120 dias para a equipe de vigilância de óbito materno responsável concluir o\nlevantamento dos dados que compõem a\ninvestigação, enviar o material ao comitê de morte\nmaterna de referência e remeter a ficha-síntese da investigação epidemiológica ao gestor do SIM.","C":"para fins de investigação, são considerados óbitos de mulheres em idade fértil aqueles ocorridos\nem mulheres de 15 a 49 anos.","D":"prazo de 96 horas - contados a partir da ocorrência - para o serviço ou profissional de saúde\ninformar o óbito, com o envio da 1ª via da DO.","E":"os hospitais, os consultórios médicos, as unidades básicas de saúde ou qualquer outro serviço\nassistencial deverão, no prazo de 1 mês da solicitação da equipe de vigilância de óbitos maternos,\nfranquear-lhe o acesso aos prontuários das mulheres falecidas sob seus cuidados."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-324699","number":"324699","sourceNumber":"324699","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A proposição da Política Nacional de Atenção Integral à Saúde do Homem visa\nqualificar a saúde da população masculina na\nperspectiva de linhas de cuidado que resguardem a\nintegralidade da atenção. Com relação à vulnerabilidade para doenças, quanto ao gênero, no\nBrasil, podemos dizer que:","options":{"A":"As mulheres são mais vulneráveis, em geral, do que os homens.","B":"Os homens são mais vulneráveis, em geral, do que as mulheres.","C":"Os homens têm menor mortalidade do que as mulheres para doenças crônicas.","D":"As mulheres têm maior mortalidade do que os homens para doenças agudas."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-294491","number":"294491","sourceNumber":"294491","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Brasil apresenta um perfil epidemiológico complexo, com uma sobreposição de\nproblemas de saúde, muitas vezes, no mesmo território: persistência de alguns agravos\ntransmissíveis e ocorrência de ciclos epidêmicos de outros; peso importante, e crescente, na\nmorbidade e na mortalidade das doenças crônicas não transmissíveis; e alta ocorrência de\nacidentes e violência. Essa múltipla carga se concentra, principalmente, nos grupos mais\nvulneráveis do ponto de vista social e econômico, como resultado das profundas desigualdades\nque ainda persistem. Esse quadro, também condicionado pelos rápidos processos de urbanização\ne de envelhecimento da população, exige que o SUS realize análises e planejamentos capazes de\nencontrar as melhores estratégias para garantir o efetivo acesso da população, ao mesmo tempo\nque lidere agendas multissetoriais que incidam nos determinantes sociais e econômicos. Na\nClassificação Internacional de Doenças - CID 10, as doenças classificadas como de Causas\nExternas têm como característica serem","options":{"A":"relacionadas à ação humana, mesmo não sendo intencionais.","B":"associadas a agentes agressores externos, não infecciosos.","C":"auto ou hétero provocadas, com intenção de dano.","D":"súbitas e agudas, mortais, por mecanismos físicos."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-62877","number":"62877","sourceNumber":"62877","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Da análise do gráfico (VER IMAGEM), que se refere à Evolução da Mortalidade Infantil\nno Estado da Bahia, de 1990 a 2006, pode-se\nidentificar como causas que repercutiram no declínio\nda mortalidade infantil na última década, exceto:","options":{"A":"Aumento da cobertura vacinal.","B":"Uso de reidratação oral.","C":"Aumento de consultas pré-natal.","D":"Ampliação dos serviços de saúde.","E":"Aumento na taxa de fecundidade."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-49374","number":"49374","sourceNumber":"49374","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em epidemiologia, quando o objetivo final é controlar as doenças, as medidas de\nmorbidade constituem-se informações basilares. Corresponde ao coeficiente de morbidade:","options":{"A":"a prevalência.","B":"a mortalidade infantil.","C":"a curva de mortalidade proporcional.","D":"o índice de Swaroop & Uemura.","E":"a razão de mortalidade proporcional."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-49380","number":"49380","sourceNumber":"49380","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O coeficiente de incidência é uma importante medida em saúde coletiva. Em relação a\nesse coeficiente, é correto afirmar, exceto:","options":{"A":"É uma medida de morbidade.","B":"É uma medida de risco.","C":"Expressa a intensidade com que ocorre uma doença em uma população.","D":"Refere-se à força com que subsistem as doenças nas coletividades.","E":"Produz informações fundamentais para o controle das doenças."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-49391","number":"49391","sourceNumber":"49391","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A prevalência é uma medida epidemiológica que expressa o número de casos\nexistentes de uma doença, em um dado momento. Sobre essa medida, pode-se afirmar:","options":{"A":"A prevalência de uma doença é determinada pela sua incidência e duração.","B":"Quanto mais elevada a incidência de uma doença, menor tende a ser a prevalência.","C":"A prevalência é uma medida irrelevante para o planejamento de ações e a administração de\nserviços de saúde, ao contrário da incidência.","D":"A imigração de casos ou a emigração de não doentes leva a uma diminuição da proporção de\nprevalência.","E":"Para medir a prevalência, é necessário que os indivíduos componentes de uma amostra sejam\nobservados várias vezes."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-49351","number":"49351","sourceNumber":"49351","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Numa certa cidade, no ano de 2010, ocorreram 380 óbitos, sendo 20 casos por câncer\nde próstata e 13 casos por doenças\nrespiratórias. De todos os óbitos ocorridos, 10 casos eram\nmenores de 1 ano. Considerando-se que a população da cidade é composta de 870.000 mulheres\ne que existem 75 crianças menores de 5 anos, com os dados fornecidos, o indicador que é possível\ncalcular é o:","options":{"A":"Coeficiente de Mortalidade Geral.","B":"Coeficiente de Mortalidade Infantil.","C":"Coeficiente de Mortalidade por Câncer de Próstata.","D":"Índice de Mortalidade Infantil Proporcional.","E":"Índice de Swaroop-Uemura."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-34920","number":"34920","sourceNumber":"34920","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Termo que expressa a experiência individual de exposição ao risco de adoecimento\nreferida a uma unidade de tempo, como o ano,\no mês ou o dia, é","options":{"A":"caso incidente.","B":"caso prevalente.","C":"pessoa-tempo.","D":"ano-calendário.","E":"caso-índice."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-34929","number":"34929","sourceNumber":"34929","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Existe no Brasil uma tendência de melhoria de alguns indicadores de saúde,\npersistindo, entretanto, algumas diferenças\nregionais que se tornam evidentes quando se analisa a\nmortalidade proporcional por causas, nas diferentes regiões. Segundo dados de 2006 (MS/lNCA),\nhá uma maior participação no grupo de óbitos devido a neoplasias e a doenças do aparelho\ncirculatório nas regiões:","options":{"A":"Norte e Nordeste.","B":"Sul e Sudeste.","C":"Norte e Centro-Oeste.","D":"Nordeste e Centro-Oeste.","E":"Nordeste e Sudeste."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-34935","number":"34935","sourceNumber":"34935","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Indica a importância de uma causa ou grupo de causas de morte em uma determinada\npopulação; possui, em seu denominador, óbitos e é muito útil na definição de prioridades na área\nda saúde. Está se referindo a:","options":{"A":"coeficiente de mortalidade geral.","B":"mortalidade proporcional por causas.","C":"incidência.","D":"prevalência.","E":"índice de Swaroop-Uemura."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-34940","number":"34940","sourceNumber":"34940","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Informe Epidemiológico da Secretaria de Saúde de determinado estado divulgou a\nocorrência de casos novos de dengue hemorrágica no ano de 2007, em duas cidades do seu\nterritório. Até o final do ano, na cidade A, que contava com 750.000 habitantes, ocorreram 27 casos\nda doença e, destes, 7 foram a óbitos; já na cidade B, que possuía 850.000 habitantes, foram\nnotificados 40 casos da doença, sendo que 15 morreram. Com base nesses dados, os coeficientes\nque podem ser calculados são:","options":{"A":"incidência e prevalência.","B":"incidência e letalidade.","C":"prevalência e letalidade.","D":"letalidade e mortalidade proporcional por causas.","E":"incidência e mortalidade proporcional por causas."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-34945","number":"34945","sourceNumber":"34945","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Informe Epidemiológico da Secretaria de Saúde de determinado estado divulgou a\nocorrência de casos novos de dengue hemorrágica no ano de 2007, em duas cidades do seu\nterritório. Até o final do ano, na cidade A, que contava com 750.000 habitantes, ocorreram 27 casos\nda doença e, destes, 7 foram a óbitos; já na cidade B, que possuía 850.000 habitantes, foram\nnotificados 40 casos da doença, sendo que 15 morreram. Os coeficientes de letalidade das cidades\nA e B correspondem, respectivamente, a:","options":{"A":"3,6% e 4,7%.","B":"25,5% e 3,6%.","C":"25,5% e 4,7%.","D":"25,9% e 37,5%.","E":"37,5% e 25%."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-34951","number":"34951","sourceNumber":"34951","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os coeficientes de incidência, prevalência e letalidade expressam, em seu numerador,\nrespectivamente,","options":{"A":"casos novos de uma doença, casos novos e casos antigos de uma doença e óbitos de uma\ndeterminada doença.","B":"casos novos e casos antigos de uma doença, casos novos de uma doença e casos de uma\ndeterminada doença.","C":"casos de uma determinada doença, casos novos e persistentes de uma doença e casos novos\nde uma doença.","D":"casos de uma determinada doença, casos novos e casos antigos de uma doença e casos novos\nde uma doença.","E":"casos novos de uma doença, óbitos de determinada doença e casos novos e casos antigos de\numa doença."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27499","number":"27499","sourceNumber":"27499","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação às mudanças dos padrões de morbidade no Brasil atualmente, é correto\nafirmar:","options":{"A":"As neoplasias, seguidas das causas violentas, passaram a ocupar o primeiro lugar entre as\ncausas de morte.","B":"Houve redução na mortalidade infantil, porém a expectativa de vida permaneceu no mesmo\npatamar, principalmente em razão do aumento das causas violentas.","C":"As doenças infecciosas e parasitárias decresceram, enquanto as doenças cardiovasculares\npassaram a ocupar o primeiro lugar como\nprincipal causa de morte.","D":"As causas violentas constituem-se, hoje, a principal causa de morte, porém as doenças\ninfecciosas e parasitárias continuam trazendo problemas para a saúde pública, apesar dos\ninvestimentos com imunização e medicamentos.","E":"A mortalidade infantil continua elevada em razão das dificuldades enfrentadas por populações\nde determinadas regiões que não têm facilidade de\nacesso aos serviços de saúde e às medidas de\nprevenção e controle das doenças infecciosas e parasitárias."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27515","number":"27515","sourceNumber":"27515","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores epidemiológicos que medem o risco de morrer por determinada doença,\nquando se adoece por essa doença, e o\nrisco de morrer antes de completar vinte e oito dias de vida\nsão, respectivamente, coeficiente de:","options":{"A":"mortalidade geral e coeficiente de mortalidade infantil.","B":"letalidade e coeficiente de mortalidade neonatal.","C":"mortalidade por determinada doença e coeficiente de mortalidade infantil.","D":"mortalidade por determinada doença e coeficiente de mortalidade neonatal.","E":"letalidade e coeficiente de mortalidade perinatal."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27516","number":"27516","sourceNumber":"27516","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Coeficiente de mortalidade cuja maioria dos óbitos é decorrente de causas perinatais,\ncomo problemas decorrentes da gestação, do parto e\nanomalias congênitas que tem no numerador\no número de óbitos de crianças de 7 a 27 dias e no denominador o total de nascidos vivos, é o\ncoeficiente de mortalidade:","options":{"A":"infantil.","B":"neonatal.","C":"perinatal.","D":"neonatal tardia.","E":"materna."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27517","number":"27517","sourceNumber":"27517","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os coeficientes de mortalidade, prevalência e incidência são mais utilizados no campo\nda saúde pública. Em relação ao coeficiente\nde incidência, é correto afirmar:","options":{"A":"Traduz a ideia de intensidade com que acontece a morbidade em uma população e é uma\nmedida de risco de uma doença ou agravo.","B":"Mede a proporção de uma população que a um determinado instante apresenta a doença,\nexpressando a força com que subsistem as doenças nas coletividades.","C":"Avalia a capacidade de o teste afastar a doença quando a ela está ausente.","D":"Representa maior ou menor poder que tem uma doença em provocar a morte das pessoas que\nadoecem por essa doença.","E":"Corresponde à ocorrência de doenças em um grande número de pessoas ao mesmo tempo."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-11171","number":"11171","sourceNumber":"11171","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Enquanto meios para obter e transmitir dados e informações, os Sistemas de\nInformações de Saúde constituem-se importantes ferramentas para a tomada de decisões no\nâmbito da saúde. São alguns desses sistemas:","options":{"A":"SAG, SIM, SINASC, SIA-SUS.","B":"SIM, SINASC, SPT, SIA-SUS.","C":"SINAM, SINASC, MIS, SIM.","D":"SIM, SINAN, SIA-SUS, SAG.","E":"SIM, SINAM, SIA-SUS, SINASC."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-11173","number":"11173","sourceNumber":"11173","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em 2005, foi realizado um estudo em determinado estado com o objetivo de analisar\ndados sobre morbimortalidade por tuberculose. Nesse ano, a população de residentes desse\nestado era de 13.815.260 habitantes, e o total de nascidos vivos correspondeu a 231.065. Foi\nidentificada a ocorrência de 351 óbitos por tuberculose e notificados 4917 casos novos dessa\ndoença. Dentre os óbitos por todas as causas, 30 ocorreram em menores de 1 ano. Com base\nnesse estudo é possível calcular:","options":{"A":"coeficiente de incidência, coeficiente de mortalidade geral, coeficiente de mortalidade\ninfantil.","B":"coeficiente de incidência, coeficiente de mortalidade materna, coeficiente de mortalidade\ninfantil.","C":"coeficiente de mortalidade pós-neonatal, coeficiente de mortalidade por determinada causa,\níndice de mortalidade proporcional.","D":"coeficiente de incidência, coeficiente de mortalidade infantil, coeficiente de mortalidade por\ndeterminada causa.","E":"coeficiente de prevalência, coeficiente de mortalidade infantil, coeficiente de mortalidade por\ndeterminada causa."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-13372","number":"13372","sourceNumber":"13372","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O coeficiente de mortalidade infantil, apesar de ser um indicador muito utilizado em\nsaúde pública, por refletir as condições de\nvida de uma população, está sujeito a distorções devido,\ndentre outros fatores, a:","options":{"A":"não considerar, sem seus cálculos, os óbitos maternos","B":"erro na contagem do denominador decorrente da não inclusão dos óbitos de crianças não\nresidentes na localidade","C":"erro na contagem do denominador decorrente da não inclusão de nascimentos de crianças não\nresidentes na localidade","D":"subregistro de óbitos e de nascimentos","E":"considerar, em seu denominador, os nascidos vivos"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-358773","number":"358773","sourceNumber":"358773","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O indicador de Swaroop-Uemura avalia a Razão de Mortalidade Proporcional (RMP) a\npartir dos 50 anos de idade. Utilizando esse indicador, a gestão do município de Santo Antônio de\nJesus realizou a comparação da área adstrita de duas Unidades de Saúde da Família no ano de\n2022 e obteve os seguintes valores: UFS-1 RMP=51%; e USF-2 RMP=34%. Com base nesses\nresultados, marque a alternativa correta.","options":{"A":"A área da USF-1 apresentou maior razão de mortalidade proporcional, portanto, menor grau de\ndesenvolvimento.","B":"A área da USF-2 apresentou menor razão de mortalidade proporcional, portanto, maior grau de\ndesenvolvimento.","C":"A área da USF-1 apresentou o indicador de Swaroop-Uemura correspondente ao de\npaíses/regiões desenvolvidas.","D":"A área USF 1 apresenta uma população com maior expectativa de vida.","E":"Apenas a área da USF-2 precisa de investimentos (saúde, educação, lazer...) que busquem\nmelhorar a qualidade de vida das pessoas do seu território."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-343377","number":"343377","sourceNumber":"343377","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Parvovírus B19 e o Herpes-vírus-6:","options":{"A":"Têm sido cada vez mais descritos em biópsias cardíacas, havendo uma tendência de redução\nde identificação de enterovírus e adenovírus.","B":"Têm sido cada vez menos descritos em biópsias cardíacas, havendo uma tendência de redução\nde identificação de enterovírus e adenovírus.","C":"Têm sido cada vez mais descritos em biópsias cardíacas, havendo uma tendência de aumento\nde identificação de enterovírus e adenovírus.","D":"Têm sido cada vez mais descritos em biópsias cardíacas, havendo uma tendência de redução\nde identificação de enterovírus e não de\nadenovírus."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-343378","number":"343378","sourceNumber":"343378","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As doses de reforço das Vacinas contra COVID-19 ainda oferecem proteção adicional\ncontra formas graves tanto das variantes Ômicron quando Delta, que, não podemos negligenciar,\nainda circula em nosso meio. Sendo correto que:","options":{"A":"A terceira dose da vacina não confere eficácia em evitar atendimentos de urgência e\nemergência, e 90% em prevenir hospitalizações.","B":"A terceira dose da vacina confere eficácia de 82% em evitar atendimentos de urgência e\nemergência, e não em prevenir hospitalizações.","C":"A terceira dose da vacina confere eficácia de 82% em evitar atendimentos de urgência e\nemergência, e 90% em prevenir hospitalizações.","D":"A terceira dose da vacina confere eficácia de 82% em promover atendimentos de urgência e\nemergência, e 90% em prevenir hospitalizações."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-314277","number":"314277","sourceNumber":"314277","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os Sistemas de Informação em Saúde, sejam assistenciais ou epidemiológícos, se\nconstituem em importantes ferramentas para o diagnóstico da situação de saúde, permitindo\nplanejar intervenções que se aproximem das reais demandas de saúde da população (CUNHA;\nVARGENS, 2017). Em relação aos Sistemas de Informação em Saúde, analise as assertivas e\nidentifique com V as verdadeiras e com F as falsas. ( ) O Sistema de Informações Hospitalares\n(SIH) permite a construção de séries históricas úteis para a realização de estudos epidemiológicos.\n( ) O Sistema de Informação sobre Nascidos Vivos (SINASC) tem o propósito exclusivo de\nquantificar os nascidos vivos e fornecer informações sobre a gravidez. ( ) O Sistema de Vigilância\nAlimentar e Nutricional (SISVAN) disponibiliza informações para o monitoramento do estado\nnutricional de diferentes grupos populacionais. ( ) No Sistema de Informação sobre Mortalidade\n(SIM), o controle e a distribuição dos formulários de Declaração de Óbito para os municípios são\nfeitos diretamente pelo Ministério da Saúde. A alternativa que contém a sequência correta, de cima\npara baixo, é","options":{"A":"F V F V","B":"F F V V","C":"V V F F","D":"V F V F","E":"V F F V"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-314300","number":"314300","sourceNumber":"314300","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de morbidade estão relacionados a incidência e prevalência das\ndoenças. São medidas essenciais para a\ncompreensão adequada da realidade sanitária e para a\nconstrução do diagnóstico situacional de saúde, sendo \"[...] mais sensíveis que as medidas de\nmortalidade para expressar mudanças a curto prazo no cenário epidemiológico\" (PEREIRA, 2013\napud GOMES, 2015, p.41). Em relação aos indicadores de morbidade, é correto afirmar que","options":{"A":"na construção de indicadores de morbidade, um dos maiores desafios diz respeito à obtenção\nde uma fonte de dados confiável.","B":"os \"\"inquéritos epidemiológicos\"\" devem ser priorizados para a construção de indicadores de\nmorbidade devido ao baixo custo operacional.","C":"na construção de indicadores de morbidade, os \"\"registros de rotina\"\" apresentam como\nvantagem o rigor metodológico inerente a esse tipo de coleta.","D":"na construção de indicadores de morbidade, os \"\"registros de rotina\"\" são utilizados quando é\nnecessário realizar a coleta de dados por meio de amostragem.","E":"os \"\"registros de rotina\"\" se constituem na fonte de dados utilizada preferencialmente para gerar\nindicadores de morbidade devido à garantia na qualidade dos dados."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-283862","number":"283862","sourceNumber":"283862","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No setor saúde, as informações são fundamentais para a compreensão de uma\ndeterminada realidade sanitária e servem de\nsubsídio para as ações de planejamento e tomadas de\ndecisão adequadas e oportunas, qualificando os processos de gestão e alocação de recursos.\n\nNesse sentido, o Departamento de Informática do Sistema Único de Saúde (DATASUS) tem um\npapel essencial, realizando a condução dos\nSistemas de Informação em Saúde (BRASIL, 2008).\nEm relação aos Sistemas de Informação em Saúde, analise as assertivas e identifique com V as\nverdadeiras e com F as falsas. ( ) O Sistema de Informação de Agravos de Notificação (SINAN) tem\no objetivo de coletar, transmitir e disseminar dados gerados pela vigilância sanitária em todo o\npaís.\n( ) O Sistema de Informações sobre Mortalidade (SIM) produz estatísticas que permitem realizar\nestudos não apenas do ponto de vista epidemiológico, mas também demográfico. ( ) O Sistema de\nInformações de Nascidos Vivos (SINASC) não dispõe de dados que permitam realizar intervenções\nrelacionadas à saúde da mulher e da criança no âmbito do SUS. ( ) O Sistema de Informações do\nPrograma Nacional de Imunizações (SIPNI) possibilita o controle do estoque de imunobiológicos, a\nfim de programar sua aquisição e distribuição. A alternativa que contém a sequência correta, de\ncima para baixo, é","options":{"A":"F F V V","B":"F V F V","C":"F V V F","D":"V F V F","E":"V F F V"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-249710","number":"249710","sourceNumber":"249710","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os Sistemas de Informação em Saúde são fundamentais tanto para as práticas de\ngestão, como, também, para os profissionais e equipes de saúde, contribuindo para qualificar a\noferta de cuidado à população. O Departamento de Informática do Sistema Único de Saúde\n(DATASUS) é responsável por desenvolver e gerir os sistemas de informação que auxiliam o\nMinistério da Saúde no processo de construção e fortalecimento do SUS (BRASIL, 2019). Em\nrelação aos Sistemas de Informação em Saúde, é correto afirmar que","options":{"A":"O Sistema de Informações Hospitalares do SUS (SIHSUS) é capaz de gerar relatórios para que\nos gestores possam fazer os pagamentos dos\nestabelecimentos de saúde.","B":"o Sistema de Informação da Atenção Básica (SIAB) possui dados sobre as famílias cadastradas,\nmas não gera informações sobre a situação de\nsaúde da população.","C":"o Sistema de Centrais de Regulação (SISREG) permite o controle e a regulação dos recursos da\nAtenção Básica no nível Municipal, Estadual ou Regional.","D":"o Sistema de Informações sobre Orçamento Público em Saúde (SIOPS) é de uso exclusivo dos\nConselhos de Saúde, no exercício do controle social.","E":"o Sistema de Informações Ambulatoriais (SIA) gera informações que são de interesse e uso\nexclusivo das Secretarias Estaduais de Saúde."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-249712","number":"249712","sourceNumber":"249712","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os processos de avaliação são fundamentais para garantir uma gestão qualificada no\nâmbito do Sistema Único de Saúde (SUS). A avaliação tem como principal objetivo dar suporte à\ntomada de decisão, na medida em que se pode verificar a efetividade das ações e programas\nimplementados, revisitar estratégias e melhorar a alocação de recursos. Dentre as estratégias de\navaliação existentes no âmbito do SUS, está o Programa Nacional de Avaliação de Serviços de\nSaúde (PNASS) (OLIVEIRA; REIS, 2016). Em relação ao PNASS, é correto afirmar que","options":{"A":"tem por objetivo avaliar todos os serviços de Atenção Básica, contemplados com aporte e\nincentivos financeiros do Ministério da Saúde.","B":"os estabelecimentos hospitalares considerados como Hospitais de Grande Porte, foram\nexcluídos do processo de avaliação proposto pelo PNASS.","C":"não contempla em seu processo avaliativo aspectos relacionados à satisfação do usuário para\ncom a assistência recebida pelos\nestabelecimentos.","D":"possui um conjunto de três instrumentos avaliativos distintos e contempla aspectos diversos dos\nserviços de saúde, incluindo a satisfação dos usuários.","E":"visa avaliar todos os estabelecimentos de atenção especializada em saúde, ambulatoriais e\nhospitalares, exceto aqueles pertencentes à Rede Cegonha."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-218150","number":"218150","sourceNumber":"218150","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Segundo a Lei n° 8.080, de 19 de setembro de 1990, a execução de ações de vigilância\nepidemiológica está incluída no campo de atuação do Sistema Único de Saúde, constituindo-se\n\"um conjunto de ações que proporcionam o conhecimento, a detecção ou prevenção de qualquer\nmudança nos fatores determinantes e condicionantes de saúde individual ou coletiva, com a\nfinalidade de recomendar e adotar as medidas de prevenção e controle de doenças ou agravos\"\n(BRASIL, 1990, p. 3). Sobre a vigilância epidemiológica, é CORRETO afirmar que:","options":{"A":"Os dados de morbidade permitem a detecção imediata ou precoce de problemas sanitários,\nsendo os dados mais utilizados em vigilância\nepidemiológica.","B":"As competências de cada ente federado abarcam todo o espectro das funções de vigilância\nepidemiológica, cabendo ao nível nacional as ações executivas.","C":"O cumprimento das funções de vigilância epidemiológica independe da disponibilidade de dados\npara subsidiar o processo de produção de\ninformação para a ação.","D":"Os dados de morbidade são de fundamental importância como indicadores da gravidade do\nfenômeno vigiado, sendo obtidos a partir das declarações de óbitos.","E":"As doenças de notificação compulsória são estabelecidas pelo Ministério da Saúde entre as\nconsideradas de maior relevância sanitária para o país, sem participação de estados e municípios."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-218120","number":"218120","sourceNumber":"218120","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Existe um conjunto de Sistemas de Informação em Saúde (SIS) nacionais de interesse\nà saúde, gerenciados pelo Ministério da Saúde\n(MS) e disponibilizados por meio da base de dados\ndo DATASUS (NERI, 2016, p. 23). A respeito dos principais SIS, é CORRETO afirmar que:","options":{"A":"O Sistema de Informação de Morbidade (SIM) utiliza a declaração de internação hospitalar para\na coleta de dados.","B":"O Sistema de Nascidos Vivos (SINASC) é uma importante ferramenta de gestão na área da\nsaúde da mulher e da criança.","C":"O Sistema de Vigilância Alimentar e Nutrição (SISVAN) visa monitorar os estabelecimentos de\nprodução de alimentos.","D":"O Sistema e-SUS AB com PEC é um sistema simplificado, e fornece informações ao SISAB\ndiferentes daquelas com CDS.","E":"O Sistema de Inforrnação de Agravos de Notificação (SINAN) tem objetivos de gerar dados de\nagravos de notificação nacional."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-181204","number":"181204","sourceNumber":"181204","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Pneumonias são doenças inflamatórias agudas de causa infecciosa que acometem os\nespaços aéreos. A PAC (Pneumonia Adquirida na\nComunidade) se refere à doença adquirida fora\ndo ambiente hospitalar ou de unidades especiais de atenção à saúde ou, ainda, que se manifesta\nem até 48h da admissão à unidade assistencial. Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"O coeficiente de mortalidade por pneumonia difere conforme a faixa etária.","B":"Nos últimos anos, a taxa de mortalidade por pneumonia tem aumentado de forma importante nas\nfaixas etárias acima de 70 anos.","C":"O coeficiente de mortalidade por pneumonias e mantem estável em diferentes faixas etárias.","D":"Os menores coeficientes estão nas faixas etárias entre 5 e 49 anos."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-181206","number":"181206","sourceNumber":"181206","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Dentre os dados epidemiológicos listados abaixo que se relacionam a atuais diretrizes,\nsomente não podemos aceitar como correto o seguinte item:","options":{"A":"Nos últimos 40 anos, os dados oficiais de mortalidade no Brasil revelam que a doença\ncerebrovascular é responsável por mais óbitos do que a doença coronária.","B":"A doença cerebrovascular, de fato que diferencia nosso país dos demais no Hemisfério\nOcidental.","C":"Dados do Ministério da Saúde indicam que as doenças cerebrovasculares são a primeira causa\nde morte no país e o AVC é a principal causa\nde incapacidade neurológica temporária ou\npermanente em adultos após os 50 anos.","D":"Os dados apresentados mostram que ocorre uma tendência de aumentar as taxas de\nmortalidade por doença cerebrovascular no país."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-139762","number":"139762","sourceNumber":"139762","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A morbimortalidade em doenças infecciosas, crônico-degenerativas e por causas\nexternas,","options":{"A":"Tem implicação importante para a transição epidemiológica no Brasil.","B":"Encontra-se em ascensão no Brasil.","C":"Tem maiores frequências na faixa etária de 20 a 29 anos.","D":"São frequentes em populações urbanas."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134709","number":"134709","sourceNumber":"134709","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre as doenças crônicas, é INCORRETO afirmar que:","options":{"A":"Resultam de um processo multifatorial, geralmente gradativo e cumulativo.","B":"Podem ser infecciosas.","C":"São consideradas um dos mais importantes problemas de saúde pública da atualidade.","D":"O diagnóstico precoce é o item principal na prevenção primária."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134791","number":"134791","sourceNumber":"134791","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, foi implantado o VIGITEL ? Vigilância de fatores de risco e proteção para\ndoenças crônicas por Inquérito Telefônico ? em\ntodas as capitais dos 26 estados brasileiros e no\nDistrito Federal, desde 2006. O objetivo do VIGITEL é monitorar a frequência e distribuição dos\nprincipais determinantes das Doenças Crônicas Não Transmissíveis (DCNT) por inquérito\ntelefônico. Os procedimentos de amostragem empregados procuraram obter, em cada uma das\ncapitais dos 26 estados brasileiros e no Distrito Federal, amostras probabilísticas da população de\nadultos residentes no ano. A tabela a seguir apresenta alguns dos principais resultados obtidos.\n(VER IMAGEM) Após a análise da situação epidemiológica apresentada pela tabela, é\nINCORRETO afirmar que:","options":{"A":"É preocupante a tendência da elevação do percentual de adultos com excesso de peso na\npopulação brasileira.","B":"Ocorreu discreta redução na frequência de tabagismo.","C":"Não ocorreu tendência de elevação do percentual de adultos com obesidade nos anos\nestudados.","D":"Ações de promoção à saúde, visando à adoção de comportamentos protetores, como a\natividade física, devem ser urgentemente adotadas."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-134722","number":"134722","sourceNumber":"134722","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os coeficientes de mortalidade de 1.000 habitantes por doenças respiratórias em\nidosos na década de 1970-80 e 2000-10 estão apresentados na tabela abaixo (VER IMAGEM).\nAssinale a alternativa CORRETA.","options":{"A":"O coeficiente de mortalidade na população idosa na década de 2000-10 foi maior que 1970-80,\nindicando maior risco de morrer por doenças respiratórias.","B":"O coeficiente de mortalidade total aumentou, porém diminuiu por faixa etária, indicando redução\ndo risco de morte por doenças respiratórias.","C":"Não é possível a comparação precisa, pois a estrutura etária da população é diferente nos dois\nperíodos.","D":"O coeficiente de mortalidade total indicado na tabela foi obtido após a padronização dos\ncoeficientes nas duas décadas."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-111847","number":"111847","sourceNumber":"111847","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre as doenças crônicas é INCORRETO afirmar que:","options":{"A":"resultam de um processo multifatorial, geralmente gradativo e cumulativo.","B":"podem ser infecciosas.","C":"são consideradas um dos mais importantes problemas de saúde pública da atualidade.","D":"progridem com fases assintomáticas entremeadas de exacerbações clínicas."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-111885","number":"111885","sourceNumber":"111885","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O coeficiente de mortalidade materna é importante, pois avalia a cobertura e qualidade\nda assistência às mulheres desse grupo. Qual das\npacientes descritas abaixo pode ser\nADEQUADAMENTE enquadrada nesse grupo?","options":{"A":"33 anos, diabética, após 15 semanas de ausência de fluxo menstrual chega ao Pronto-socorro\ncom dor abdominal e secreção vaginal de odor\nfétido. É feito o diagnóstico de abortamento\ninfectado e a paciente evolui para o óbito.","B":"24 anos, obesa, com gravidez diagnosticada por ultrassonografia, na trigésima semana, evolui\ncom febre intensa, com calafrios e vai ao óbito. Gota espessa isolou Plasmodium falciparum.","C":"29 anos, com histórico de miomatose uterina, na trigésima segunda semana de gravidez, evolui\ncom dor abdominal intensa e dor à descompressão brusca. É realizada laparotomia de urgência,\nmas a paciente evolui para o óbito. O apêndice cecal encontrava-se necrosado e com\nextravasamento de conteúdo para a cavidade abdominal.","D":"22 anos, com aumento do volume abdominal predominante em região pélvica. Evolui com\naumento da pressão arterial, convulsões e\nóbito. Durante a necropsia foi verificado massa tumoral\nde 20 cm de diâmetro em anexo direito."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-111896","number":"111896","sourceNumber":"111896","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considere um estudo sobre segurança no ambiente de trabalho em duas fábricas de\nautomóveis, durante um ano, baseados no registro do sistema de vigilância epidemiológica.\n\nSabe-se que o número de empregados de cada fábrica, inicialmente, era 1.000. Ao final de 12\nmeses, a fábrica A permaneceu com 700\nempregados e a fábrica B com 1.000. O número de casos\nde acidentes foi 40 para a fábrica A e 60 para a fábrica B. O registro permitia o conhecimento de\ntrabalhadores expostos aos 3, 6, 9 e 12 meses. Assinale a medida de frequência MAIS adequada\npara estimar o risco de acidente de trabalho nesse estudo.","options":{"A":"Taxa de incidência. O tempo de exposição foi variável, assim é necessário calcular quantidade\nde pessoas-tempo de exposição.","B":"Incidência acumulada, pois trata-se de uma coorte fixa, na qual não houve perda de seguimento.","C":"Proporção de incidência para uma coorte fixa.","D":"Prevalência pontual. O objetivo do estudo é estimar a proporção de indivíduos que sofreram\nacidente de trabalho."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-111920","number":"111920","sourceNumber":"111920","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considerando que o Brasil, atualmente, está na 3ª fase de transição demográfica, é\nCORRETO afirmar que:","options":{"A":"o coeficiente de mortalidade infantil tende a se elevar.","B":"a taxa de natalidade e de mortalidade tendem a divergir.","C":"a esperança de vida ao nascer tende a diminuir.","D":"a proporção de doenças crônicas tende a aumentar."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-259784","number":"259784","sourceNumber":"259784","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A OMS conceitua morbidade materna grave como uma complicação que ocorra durante\na gravidez, o parto ou nos 42 dias iniciais do\npuerpério, e que coloque em risco a vida da mulher\n(Pattinson et al., 2009). O estudo da mortalidade materna é um dos melhores indicadores da\nqualidade de saúde e atenção à mulher. Com relação à mortalidade materna, é CORRETO afirmar:","options":{"A":"As principais causas obstétricas diretas das mortes maternas são: hemorragia, hipertensão e\ninfecção.","B":"As principais causas obstétricas indiretas são: prematuridade, placenta prévia, diabetes\ngestacional, doença cardiovascular e obesidade.","C":"A taxa de mortalidade materna por causas obstétricas indiretas tem-se mantido estável, fato que\npode ser atribuído às medidas adotadas na\natenção humanizada ao parto.","D":"A taxa de mortalidade materna por causas obstétricas diretas vem diminuindo devido às\nmedidas adotadas para a redução da transmissão vertical do HIV/aids e da sífilis congênita."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-199819","number":"199819","sourceNumber":"199819","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um secretário municipal de saúde recebeu o relatório contendo informações sobre a\nmortalidade infantil do seu município, e percebeu que durante um ano ocorreram 440 óbitos em\nmenores de 1 ano, destes 310 foram em crianças com menos de 28 dias de vida, sendo que 70%\ndas mortes ocorreram até o sexto dia de vida. Os dados provenientes da maternidade indicavam\n\n40.000 nascidos vivos. Considerando as faixas de coeficientes de mortalidade infantil, qual deve\nser a intervenção adotada para reduzir as\nmortes em crianças?","options":{"A":"Ampliação do número de leitos de UTI neonatal e dos bancos de leite humano.","B":"Melhora da assistência pré-natal e investimento em tecnologias de atenção ao parto e ao\nrecém-nascido.","C":"Aumento da cobertura vacinal, saneamento básico, diminuição da ocorrência de diarreias e\ndesnutrição infantil.","D":"Treinamento dos profissionais de assistência ao parto para reduzir infecções perinatais,\nasfixia/hipóxia e afecções respiratórias."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-65707","number":"65707","sourceNumber":"65707","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A tabela abaixo apresenta as principais causas de mortes maternas obstétricas diretas\nno estado do Ceará, no período de 1997 a 2009\n(Fonte: SESA / COPROM / NUVEP - NUIAS).\n\nConsiderando as informações contidas nesta tabela, qual a interpretação correta desses dados?\n(VER IMAGEM)","options":{"A":"A maioria das causas de morte materna obstétrica se deve à baixa qualidade do pré-natal\nrealizado na\n\natenção primária.","B":"A deficiência de anestesistas na sala de parto no interior do estado é um dos fatores de maior\nimpacto\n\nna mortalidade materna.","C":"O aborto, o sangramento pré e pós-parto e a embolia obstétrica não tiveram redução\nsignificativa e\n\nainda se mantêm como causas importantes de mortalidade materna.","D":"O aumento do número de obstetras no estado teria impacto na redução da mortalidade materna,\npela\n\nredução de complicações no desfecho da gestação.","E":"A ampliação da rede hospitalar secundária e de maternidades no interior do estado teria\nimpacto na\n\nmortalidade materna, pela redução dos casos de doença hipertensiva específica da gravidez."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-51150","number":"51150","sourceNumber":"51150","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um médico de família e comunidade (MFC) trabalha em Unidade de Saúde da Família,\nem município no sul do Estado do Ceará. Atua em\nequipe responsável por 2.000 indivíduos, sendo\n\n1.000 acima de 15 anos. O município possui população em torno de 20 mil habitantes, sendo a\ndensidade populacional de 35 hab./km². Trata-se de município de economia rural, e o cultivo do\nalgodão predomina. Baseando-se no clássico estudo de White (1961), qual a estimativa de\nprevalência mensal de indivíduos com problemas de saúde na população acima de 15 anos desse\nmunicípio e de encaminhamentos dados a esses casos?","options":{"A":"200 pessoas apresentarão algum sintoma ao longo de um mês, 50 se consultarão em Unidade\nBásica de Saúde, 10 serão referenciadas a especialista e 10 hospitalizadas.","B":"500 pessoas apresentarão sintomas ao longo de um mês, 100 se consultarão na Unidade\nBásica de Saúde, 5 serão referenciadas ao especialista e 20 hospitalizadas.","C":"550 pessoas apresentarão algum sintoma ao longo de um mês, 150 se consultarão em Unidade\nBásica de Saúde, 25 serão referenciadas a especialista e 19 hospitalizadas.","D":"750 pessoas apresentarão algum sintoma ao longo de um mês, 250 se consultarão em Unidade\nBásica de Saúde, 5 serão referenciadas a especialista e 9 hospitalizadas."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-51147","number":"51147","sourceNumber":"51147","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quais indicadores caracterizam a transição epidemiológica brasileira nos últimos 60\nanos?","options":{"A":"Aumento da natalidade e diminuição da mortalidade geral.","B":"Aumento da idade mediana e diminuição da mortalidade infantil.","C":"Aumento da taxa de crescimento demográfico e diminuição da fecundidade.","D":"Aumento da expectativa de vida e diminuição do ápice da pirâmide populacional."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-45319","number":"45319","sourceNumber":"45319","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"São fenômenos demográficos que podem ser observados em uma pirâmide de\npopulação:","options":{"A":"natalidade, mortalidade e morbidade.","B":"estrutura etária da população e natimortalidade.","C":"esperança de vida, morbidade e mortalidade.","D":"razões de dependência e masculinidade e morbidade.","E":"migração, natalidade e mortalidade."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-45343","number":"45343","sourceNumber":"45343","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A expressão ?óbito hospitalar específico? corresponde ao óbito que:","options":{"A":"se verifica no hospital, após o registro do doente.","B":"se verifica após 48 horas de internação de um doente.","C":"decorreu de uma infecção adquirida no hospital.","D":"decorreu de alguma causa de natureza hospitalar.","E":"ocorrido no hospital e com causa especificada."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-45356","number":"45356","sourceNumber":"45356","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"São possíveis intervenções para reduzir a mortalidade por malformações congênitas no\nBrasil, EXCETO:","options":{"A":"melhorar a ingesta materna de folatos.","B":"tratar a sífilis na gestação.","C":"diminuir o tabagismo entre familiares.","D":"vacinar contra a rubéola.","E":"evitar o álcool durante a gestação."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-30845","number":"30845","sourceNumber":"30845","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual a definição de incidência de um agravo em saúde (doença, sintoma, etc..)?","options":{"A":"É a quantificação do número de casos novos em uma população sob risco durante um\ndeterminado intervalo de tempo.","B":"É a quantificação do número total de casos em uma população sob risco durante um momento\nespecífico no tempo.","C":"Representa a probabilidade de um indivíduo sem o agravo vir a desenvolvê-lo durante sua vida.","D":"Representa a probabilidade de um indivíduo com o agravo vir a deixar de apresentá-lo durante\nsua vida.","E":"É a proporção de indivíduos que apresentam determinado agravo em um determinado período\ndo tempo."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32506","number":"32506","sourceNumber":"32506","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O fenômeno chamado \"baby-boom\" se refletiu na pirâmide populacional de alguns\npaíses sob a forma de:","options":{"A":"\"saídas\" bruscas apenas entre os homens.","B":"\"saídas\" bruscas apenas entre as mulheres.","C":"\"saídas\" bruscas de ambos os lados.","D":"\"entradas\" bruscas apenas entre os homens.","E":"\"entradas\" bruscas de ambos os lados."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-37382","number":"37382","sourceNumber":"37382","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"?Em termos gerais e vistos em conjunto, os indicadores devem refletir a situação\nsanitária de uma população e servir para a vigilância das condições de saúde?. Dentre os\nindicadores abaixo assinale aquele que não é considerado um bom indicador de saúde:","options":{"A":"Mortalidade geral.","B":"Mortalidade infantil.","C":"Mortalidade materna.","D":"Mortalidade pré-escolar.","E":"Esperança de vida ao nascer."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32508","number":"32508","sourceNumber":"32508","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"São fatores que podem influenciar aumentando as taxas de prevalência de uma\ndoença, EXCETO:","options":{"A":"Aumento da sobrevida sem a cura.","B":"Imigração de pessoas sadias.","C":"Imigração de casos.","D":"Imigração de pessoas suscetíveis.","E":"Melhora dos recursos diagnósticos."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-37425","number":"37425","sourceNumber":"37425","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a opção que não correlaciona corretamente os cálculos dos coeficientes e das\ntaxas e sua definição:","options":{"A":"Taxa de prevalência = relação entre o número de casos conhecidos de uma determinada doença\ne a população exposta, multiplicando o\nresultado pela base referencial (geralmente uma potência\nde 10, usualmente 1000, 10.000, 100.000).","B":"Taxa de incidência = relação entre o número de casos novos de uma doença em determinada\ncomunidade em certo período de tempo e a população exposta ao risco de adquirir a doença no\nreferido período, multiplicando o resultado pela base referencial (geralmente uma potência de 10,\nusualmente 1000, 10.000, 100.000).","C":"Taxa de mortalidade por causas = relação entre o número de óbitos por uma doença específica\nem determinada comunidade em certo período de tempo\ne a população não exposta ao risco de\nadquirir a doença no referido período, multiplicando o resultado por 1000.","D":"Taxa de mortalidade geral = relação entre o número de óbitos concernentes a todas as causas,\nem um determinado ano, pela população,\nnaquele ano, circunscritos a uma determinada área e\nmultiplicando-se o resultado por 1000, base referencial para a população exposta.","E":"Taxa de mortalidade infantil = relação entre o número de óbitos de crianças menores de 1 ano\npelos nascidos vivos naquele ano, em uma determinada área, e multiplicando-se o resultado por\n1000."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-30898","number":"30898","sourceNumber":"30898","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual o sistema oficial de informação em saúde no Brasil que tem como objetivo\nprincipal o aspecto\ncontábil-administrativo, mas também fornece dados epidemiológicos indiretos do\nperfil de morbidade de toda a rede de assistência?","options":{"A":"Sistema Nacional sobre Imunizações (SIPNI).","B":"Sistema Nacional de Agravos Notificáveis (SINAN).","C":"Sistema de Informações Hospitalares (SIH).","D":"Sistema de Informações de Mortalidade (SIM).","E":"Sistema de Informação de Nascidos (SINASC)."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27681","number":"27681","sourceNumber":"27681","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"São consideradas possíveis intervenções para reduzir as mortes infantis por infecções\nrespiratórias agudas (IRA) no Brasil, EXCETO:","options":{"A":"melhorar o manejo de casos","B":"prevenir o baixo peso ao nascer","C":"promover o aleitamento materno","D":"reduzir a aglomeração familiar","E":"melhorar a nutrição materna"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-9080","number":"9080","sourceNumber":"9080","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"?A violência é a face mais visível da doença na cidade? Sobre as condições de saúde\nda população brasileira é INCORRETO afirmar que:","options":{"A":"Pode-se observar que a população brasileira envelheceu, nas últimas décadas, com maior\npercentual de pessoas nas faixas de 30 - 49, 50 - 69 e 70 anos.","B":"A taxa média de crescimento anual da população cresceu, passando de 1,9% na década de 80,\npara 2,4% na década de 90 e ultrapassando 3% em 2005.","C":"O padrão de urbanização nas últimas décadas foi alterado, com redução no processo de\nurbanização nas grandes cidades entre as décadas de 80 e 90.","D":"Apesar de avanços importantes nos indicadores básicos de saúde nas últimas décadas, como\nmelhoria do acesso da população aos serviços básicos de saúde, a incidência de agravos à saúde\ne a mortalidade ainda são altas, principalmente, associadas à violência, que acomete, em especial,\naos jovens."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-7269","number":"7269","sourceNumber":"7269","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, em relação à nova agenda da saúde pública (doenças do coração, câncer,\nobesidade, violências e acidentes, doenças do trabalho e a AIDS/SIDA, dentre outros problemas),\nhá sinais de evolução desfavorável da nova agenda, e de cenários futuros inquietantes, dentre os\nquais não se registra:","options":{"A":"o aumento intenso e generalizado da obesidade.","B":"a trajetória ascendente de graves doenças, como o câncer de pulmão e o câncer de mama.","C":"a epidemia de mortes violentas na população jovem das grandes cidades.","D":"a complexidade crescente que engloba as relações entre saúde e trabalho.","E":"a ascensão irresistível das infecções agudas no perfil de mortalidade de todas as regiões."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8771","number":"8771","sourceNumber":"8771","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual é o efeito da redução da fecundidade e do aumento da expectativa de vida no\ntraçado da pirâmide populacional brasileira nas últimas décadas?","options":{"A":"Estreitamento do ápice e ampliação da base.","B":"Estreitamento da base e ampliação do ápice.","C":"Estreitamento da base e do ápice.","D":"Alargamento da base e do ápice.","E":"Ocorrência de ?entradas? nas faixas de fertilidade."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-9026","number":"9026","sourceNumber":"9026","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Dra. Mauricélia, infectologista, analisou diversas afirmações sobre as tendências de\ndeclínio e persistência de doenças transmissíveis no Brasil. A médica observou que apenas uma\ndelas estava CORRETA. Por favor, marque essa opção:","options":{"A":"A varíola foi erradicada em 1973, porém, por segurança, sua vacina é obrigatória até hoje em\nnosso calendário.","B":"A difteria, o coqueluche, o tétano acidental e a poliomielite não sofreram nenhum declínio ao\nlongo dos anos, apesar das campanhas de vacinação.","C":"A implantação da vacina contra hepatite C tem produzido um impacto em nosso país, reduzindo\nsubstancialmente a incidência dessa doença.","D":"Observou-se significativa redução na ocorrência da meningite causada por H. influenzae tipo B."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-13444","number":"13444","sourceNumber":"13444","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a afirmativa FALSA de acordo com seu conhecimento e o gráfico abaixo.","options":{"A":"A desigualdade de renda no Brasil é semelhante à de países africanos.","B":"A desigualdade de renda no Brasil é mais que o dobro dos países do norte europeu.","C":"A desigualdade de renda no Brasil se deve ao fato do Brasil ser um dos países mais pobres do mun\ndo.","D":"Exceto pela Guatemala, a desigualdade de renda no Brasil é a maior da América Latina.","E":"Muitos que se preocupam com a saúde pública no Brasil consideram\nas iniquidades a nossa mais grave doença."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":["question_bank/media/medcurso/medcurso-preventiva-pre-1/13444.png"],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-307128","number":"307128","sourceNumber":"307128","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Para melhor compreensão da situação de saúde de determinada população, é\nrecomendado que sejam analisadas algumas\nmedidas de saúde coletiva, como, por exemplo, os\ncoeficientes de mortalidade neonatal precoce (I), neonatal tardia (II) e pós-neonatal (III). Para\ncálculo desses coeficientes, é preciso considerar os óbitos nos seguintes dias de vida,\nrespectivamente, alternativas:","options":{"A":"I ? 0 a 6 dias completos; II ? entre 7 dias e 27 dias completos; e III ? entre 28 dias e 364 dias\ncompletos.","B":"I ? 0 a 7 dias completos; II ? entre 8 dias e 30 dias completos; e III ? entre 31 dias e 365 dias\ncompletos.","C":"I ? 0 a 14 dias completos; II ? entre 15 dias e 27 dias completos; e III ? entre 28 dias e 364\ndias\ncompletos.","D":"I ? 0 a 1 dia completo; II ? entre 2 dias e 6 dias completos; e III ? entre 7 dias e 27 dias\ncompletos.","E":"I ? 0 a 1 dia completo; II ? entre 2 dias e 30 dias completos; e III ? entre 28 dias e 365 dias\ncompletos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-365595","number":"365595","sourceNumber":"365595","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quanto ao sarampo, o intenso fluxo migratório de países vizinhos, associado às baixas\ncoberturas vacinais em vários municípios, em 2018, permitiu a reintrodução do vírus da doença no\nPaís. O Brasil havia recebido a certificação de País livre da doença em 2016. A respeito desse\nassunto, assinale a alternativa correta.","options":{"A":"A baixa cobertura vacinal gerou aumento da prevalência de sarampo, porém não da incidência.","B":"A imigração de pessoas portadoras do vírus do sarampo gerou redução da incidência dessa\ndoença.","C":"A incidência de sarampo era maior em 2016 do que em 2018.","D":"A incidência de sarampo aumenta com o crescimento do fluxo migratório de países vizinhos e\ncom a redução da cobertura vacinal."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-349776","number":"349776","sourceNumber":"349776","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O seguinte gráfico demonstra a redução da taxa de mortalidade da tuberculose ao\nlongo do tempo, considerando estimativas traçadas desde 1860 até 1960: Considerando esse\ngráfico, é correto afirmar que","options":{"A":"A redução da mortalidade pela tuberculose se deve ao crescimento populacional, que diminuiu o\nnúmero de pessoas expostas à doença.","B":"A redução da mortalidade pela tuberculose evidencia o impacto dos determinantes sociais da\nsaúde - sendo as melhorias nas condições de\nvida fundamentais na redução da mortalidade pela\ntuberculose.","C":"A redução da mortalidade representada nesse gráfico não é confiável, levando-se em conta a\ntemporalidade dos dados, visto que estes são de períodos em que não havia nenhum tipo de\nregistro em saúde.","D":"A redução da mortalidade pela tuberculose se deve ao aumento do número de pessoas\nglobalmente expostas a micobactérias atípicas, o que\ndiminuiu o número de pessoas expostas à\ndoença.","E":"A redução da mortalidade pode ser explicada principalmente pelo surgimento da vacina BCG,\nque é a principal ferramenta para reduzir a mortalidade da tuberculose pulmonar."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-365660","number":"365660","sourceNumber":"365660","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A respeito dos indicadores utilizados para estudar a demografia no Brasil, assinale a\nalternativa correta.","options":{"A":"A taxa de fecundidade total é a relação entre o número de nascidos vivos e as mulheres com\nidade entre 20 e 45 anos.","B":"O índice de envelhecimento é a relação entre o número de pessoas com mais de 65 anos de\nidade e o número de nascidos vivos.","C":"A taxa de fecundidade total é a relação entre o número de nascidos vivos e o total da população.","D":"O índice de envelhecimento é a relação entre o número de pessoas com mais de 60 anos e o\nnúmero de pessoas com menos de 15 anos de idade."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-322223","number":"322223","sourceNumber":"322223","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Gestante, 27 anos, com parto prematuro de 34 semanas gestacionais. Após alta para\ncasa, evolui com infecção uterina, sepse e tem óbito confirmado 60 dias após o parto. Diante do\nexposto, qual é o tipo de morte?","options":{"A":"Morte materna direta.","B":"Morte obstétrica direta.","C":"Morte não materna, pois ocorreu 60 dias após o parto.","D":"Morte materna tardia.","E":"Morte pós-materna."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-305353","number":"305353","sourceNumber":"305353","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"São sistemas nacionais de informação úteis para a prática da vigilância epidemiológica\npor profissionais e equipes de saúde, EXCETO:","options":{"A":"SINAN.","B":"SINASC.","C":"SIM.","D":"SCNES.","E":"SIH."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-305354","number":"305354","sourceNumber":"305354","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Alberto é gestor municipal de saúde e está participando da construção do Plano\nPlurianual (PPA) do seu município. Ao saber\nque precisaria definir indicadores para monitorar os\nefeitos do PPA, para acompanhamento das metas e objetivos almejados, ele resolve estudar mais\nsobre o assunto e descobre que os indicadores em saúde são classificados, segundo a proposta de\nDonabedian, em indicadores de estrutura, processo e resultado. Considerando essa classificação\npara a realidade dos serviços de atenção primária à saúde no Brasil, relacione as colunas e\nassinale a alternativa com a sequência CORRETA. Classificação: 1. Estrutura. 2. Processo. 3.\n\nResultado. Indicador: ( ) Cobertura de Papanicolaou. ( ) Número de médicos por habitante. ( )\nMortalidade por insuficiência cardíaca. ( ) Cobertura por equipes de ESF. ( ) Internações por asma.\n( ) Percentual de parto cesáreo.","options":{"A":"1 ? 2 ? 3 ? 3 ? 2 ? 1.","B":"2 ? 1 ? 3 ? 1 ? 3 ? 2.","C":"1 ? 1 ? 3 ? 2 ? 2 ? 3.","D":"3 ? 2 ? 1 ? 1 ? 2 ? 3.","E":"2 ? 3 ? 2 ? 2 ? 3 ? 1."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-274428","number":"274428","sourceNumber":"274428","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um homem de 41 anos procura a unidade de saúde para atendimento de rotina. Deseja\nrealizar exames médicos ?para saber se está tudo bem?. Ao exame físico, o paciente apresenta:\npeso 90 kg, estatura: 1,80 m, PA: 140 x 90 mmHg nos dois braços. Ausculta cardíaca, pulmonar e\nexame abdominal normais. Pulsos periféricos simétricos e cheios. Sem outros achados. Qual\nalternativa melhor indica os exames necessários no momento e qual é a maior causa de\nmortalidade geral nessa faixa etária, respectivamente?","options":{"A":"Glicemia de jejum e lipidograma. Doenças cardiovasculares.","B":"Hemograma completo, creatinina, potássio, glicemia, lipidograma e PSA. Doenças\ncardiovasculares.","C":"Glicemia de jejum e lipidograma. Causas externas.","D":"Hemograma completo, creatinina, potássio, glicemia, lipidograma e PSA. Causas externas.","E":"Nenhum exame está indicado. Doenças cardiovasculares."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-250159","number":"250159","sourceNumber":"250159","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Foi realizado um estudo de coorte para avaliar a ocorrência de acidente vascular\ncereblar (AVC) em pacientes com diagnóstico\nde hipertensão arterial sistêmica (HAS) e diabetes\nmelito (DM). Ao todo, duzentos pacientes foram incluídos no estudo, sendo 105 pacientes no grupo\nHAS e DM controlados e 95 pacientes no grupo HAS e DM não controlados. No grupo de pacientes\ncom HAS e DM não controlados, noventa pacientes tiveram AVC e, no grupo de pacientes com\nHAS e DM controlados, apenas dez pacientes tiveram AVC. Com base nesse caso hipotético,\njulgue o item a seguir. O risco de ocorrência de AVC nos pacientes com HAS e DM não controlados\né de 65%","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-250172","number":"250172","sourceNumber":"250172","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação aos indicadores para diagnóstico de saúde da população, julgue o item a\nseguir. Os coeficientes de prevalência podem ser utilizados para o planejamento dos serviços de\nsaúde, pois expressam demandas atuais e futuras.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-250173","number":"250173","sourceNumber":"250173","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação aos indicadores para diagnóstico de saúde da população, julgue o item a\nseguir. A medida de incidência é utilizada para avaliar doenças agudas e monitorar a velocidade de\nprogressão de um agravo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-239359","number":"239359","sourceNumber":"239359","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Acerca dos conhecimentos de bioestatística, das políticas de saúde e dos\nconhecimentos médicos correlatos, julgue o item a\nseguir. Programas de mutirão não são\ncusto-efetivos e não causam impacto na morbimortalidade de uma população em longo prazo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-239361","number":"239361","sourceNumber":"239361","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um paciente de 28 anos de idade chega à emergência do pronto-socorro levado por\nambulância após acidente automobilístico a caminho do trabalho em metrópole brasileira, com\natendimento pré-hospitalar pela equipe da SAMU, iniciado oito minutos após o chamado. Na\nchegada à emergência, encontra-se em maca rígida, com colar cervical, com ficha de atendimento\npré-hospitalar indicando pressão arterial = 96 mmHg x 64 mmHg, frequência cardíaca = 102 bpm,\nfrequência respiratória = 20 ipm, saturação de oxigênio = 94%, regular estado geral, mucosas\númidas e hipocoradas, escala de coma de Glasgow 12, pupilas isocóricas e fotorreagentes,\nausculta pulmonar e cardíaca sem particularidades, abdome globoso, sem sinais de peritonismo,\ntempo de enchimento capilar de dois segundos, impressão de nítida fratura de membro inferior\nesquerdo e membro superior direito. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Os acidentes, como o descrito, correspondem à segunda maior\ncausa de morte por causas externas no Brasil.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-196696","number":"196696","sourceNumber":"196696","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Suponha que o secretário de Saúde de uma metrópole brasileira com cerca de 5\nmilhões de habitantes precise gerenciar a\nalocação dos recursos da própria pasta entre as diversas\nnecessidades do sistema de saúde municipal, incluindo os serviços primário, secundário e terciário\nnas respectivas ações de prevenção, tratamento e reabilitação. Acerca de todo o planejamento que\nenvolve a função desse servidor público, julgue o item a seguir. Para os cálculos referentes à\nalocação de verbas da saúde pública, o conhecimento da incidência das doenças\n\ncrônico-degenerativas é mais importante que o da respectiva prevalência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-196619","number":"196619","sourceNumber":"196619","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Suponha que o secretário de Saúde de uma metrópole brasileira com cerca de 5\nmilhões de habitantes precise gerenciar a\nalocação dos recursos da própria pasta entre as diversas\nnecessidades do sistema de saúde municipal, incluindo os serviços primário, secundário e terciário\nnas respectivas ações de prevenção, tratamento e reabilitação. Acerca de todo o planejamento que\nenvolve a função desse servidor público, julgue o item a seguir. O conhecimento relativo à\nprevalência da obesidade na população dessa metrópole afeta diversas questões no orçamento da\nsaúde, visto que essa doença relaciona-se com o aumento da incidência de outras doenças, como\no câncer de mama em mulheres no menacme.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-214439","number":"214439","sourceNumber":"214439","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qualquer sistema de saúde, público ou privado, deve organizar estratégias de\npromoção de saúde e prevenção de doenças,\nvisando a diminuir a morbimortalidade da respectiva\npopulação assistida e reduzir os custos associados a determinadas doenças. Com base no\nexposto, considere que o gestor responsável por determinada Secretaria Estadual de Saúde\nprecise realizar o planejamento de objetivos e custos do próximo ano, incluindo todos os diferentes\nníveis de atenção à saúde, estratégias de promoção à saúde e prevenção de doenças. Acerca\ndesse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. A\nprevenção quaternária visa a proteger os pacientes da intervenção médica desnecessária e a\nprevenir iatrogenias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-214448","number":"214448","sourceNumber":"214448","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qualquer sistema de saúde, público ou privado, deve organizar estratégias de\npromoção de saúde e prevenção de doenças,\nvisando a diminuir a morbimortalidade da respectiva\npopulação assistida e reduzir os custos associados a determinadas doenças. Com base no\nexposto, considere que o gestor responsável por determinada Secretaria Estadual de Saúde\nprecise realizar o planejamento de objetivos e custos do próximo ano, incluindo todos os diferentes\nníveis de atenção à saúde, estratégias de promoção à saúde e prevenção de doenças. Acerca\ndesse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. O\nconhecimento da prevalência das doenças crônicas em dado momento é importante para se definir\no aporte inicial de recursos para o tratamento delas no início do próximo orçamento. Já o\nconhecimento da incidência dessas doenças, por sua vez, é importante para calcular a\nnecessidade de ampliação desse aporte financeiro ao longo dos meses, embora não seja a única\nvariável envolvida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-179167","number":"179167","sourceNumber":"179167","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No que diz respeito à longevidade da população nas Américas, incluindo o Brasil,\nrecente relatório da organização panamericana de saúde aponta que a(s)","options":{"A":"expectativa de vida nessa região tem diminuído em relação à média global devido a surtos de\ndoenças emergentes, como febre amarela, zika,\nchikungunya e dengue.","B":"incidência de doenças crônicas, como a diabetes, está em queda devido à eficiência das\npolíticas de prevenção primárias.","C":"prevalência da obesidade assumiu características epidêmicas na mesma proporção de outras\nregiões e, em especial, no gênero masculino e em crianças.","D":"doenças cardiovasculares continuam sendo a principal causa de morte na região.","E":"taxas de mortalidade por acidentes de trânsito e homicídios na América Latina são pouco mais\nelevadas que nas demais regiões."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-177668","number":"177668","sourceNumber":"177668","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O escopo da abordagem comunitária do médico de família foge do completo isolamento\ndo consultório médico, envolvendo, também, ações\nde modificação do ambiente da comunidade,\nvisando à promoção da qualidade de vida e à prevenção de doenças da população. Considerando\nesse contexto, Rafael, residente do 2º ano de medicina de família e comunidade, procurou auxílio\nda prefeitura para implantar um programa de incentivo à atividade física, na área geográfica de sua\natuação, o qual incluía a revitalização da praça próxima ao posto, a implantação de academia ao ar\nlivre e a pista de caminhada. Três vezes por semana, Rafael investia a 1ª hora de sua manhã\norganizando um grupo de caminhada e orientando a população na prática de exercícios físicos.\n\nConsiderando a situação hipotética apresentada e os conhecimentos médicos correlatos, julgue o\nitem a seguir. O impacto desse programa, na mortalidade, poderá ser observado em curto prazo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-152089","number":"152089","sourceNumber":"152089","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considere hipoteticamente que o médico J. B. S trabalha em uma unidade de saúde de\ndeterminado município e faz plantões em um pronto-socorro da região. Durante o trabalho, ele\npercebe que grande parte dos pacientes da unidade de saúde apresenta condições crônicas, como\nhipertensão arterial sistêmica (HAS) e diabetes mellitus (DM). Enquanto isso, no pronto-socorro,\npercebe agudização das condições crônicas daqueles pacientes que não aderem ao tratamento,\nsomada a condições agudas, e pessoas vítimas de lesões por causas externas (atropelamentos e\nlesões por armas de fogo e por armas brancas). Outro fato que J. B. S. sempre observa é que os\ngestores de saúde da região não fornecem respostas adequadas e coerentes aos problemas. A\nrespeito da situação apresentada, das redes de atenção à saúde e do quadro de saúde da região,\njulgue o item a seguir. As condições de saúde revelam uma importância relativa crescente das\ncondições crônicas do quadro epidemiológico. Os principais fatores determinantes do aumento das\ncondições crônicas são as mudanças demográficas, as mudanças nos padrões de consumo e nos\nestilos de vida, a urbanização acelerada e as estratégias mercadológicas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-152117","number":"152117","sourceNumber":"152117","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considere hipoteticamente que o médico J. B. S trabalha em uma unidade de saúde de\ndeterminado município e faz plantões em um pronto-socorro da região. Durante o trabalho, ele\npercebe que grande parte dos pacientes da unidade de saúde apresenta condições crônicas, como\nhipertensão arterial sistêmica (HAS) e diabetes mellitus (DM). Enquanto isso, no pronto-socorro,\npercebe agudização das condições crônicas daqueles pacientes que não aderem ao tratamento,\nsomada a condições agudas, e pessoas vítimas de lesões por causas externas (atropelamentos e\nlesões por armas de fogo e por armas brancas). Outro fato que J. B. S. sempre observa é que os\ngestores de saúde da região não fornecem respostas adequadas e coerentes aos problemas. A\nrespeito da situação apresentada, das redes de atenção à saúde e do quadro de saúde da região,\njulgue o item a seguir. Na situação apresentada, observa-se um fenômeno que impacta\ncriticamente o Sistema Único de Saúde. Trata-se de uma incoerência entre a situação de saúde\nvivida na região e a resposta do sistema local de saúde, ou seja, há sobrecarga por uma tripla\ncarga de doenças, predominando as condições crônicas, associadas a uma provável reação\nepisódica voltada às condições agudas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-79677","number":"79677","sourceNumber":"79677","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que apresenta o indicador sociossanitário baixo, referente,\nexclusivamente, a condições de saúde.","options":{"A":"Índice de Gini.","B":"Crescimento demográfico.","C":"Mortalidade infantil.","D":"IDH.","E":"Índice de alfabetismo."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-88702","number":"88702","sourceNumber":"88702","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No que se refere às doenças infectocontagiosas e parasitárias, julgue o item\nsubsecutivo. Nos últimos anos, têm aumentado o\nnúmero de infectados pelo HIV e a ocorrência de\ncoinfecção tuberculose/HIV, portanto deve-se investigar a infecção pelo HIV em indivíduos\ndiagnosticados com tuberculose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-64270","number":"64270","sourceNumber":"64270","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Acerca da transição epidemiológica e demográfica e da constituição da população\nbrasileira, julgue o item a seguir. Segundo dados\ndo Instituto Brasileiro de Geografia e Estatística\n(IBGE), Censo 2010, apesar das modificações ocorridas na constituição da população brasileira,\nainda há predomínio de unidades domiciliares nucleares.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-64280","number":"64280","sourceNumber":"64280","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Acerca da transição epidemiológica e demográfica e da constituição da população\nbrasileira, julgue o item a seguir. O conceito\nde dupla carga de doenças decorre da transição\ndemográfica tardia e implica a coexistência de doenças infectocontagiosas e crônico-degenerativas.\nNo Brasil, devido ao contexto social, verifica-se a existência da tripla carga de doenças.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-64634","number":"64634","sourceNumber":"64634","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que apresenta a taxa que mede a possibilidade de adquirir uma\ndoença.","options":{"A":"Prevalência.","B":"Incidência.","C":"Letalidade.","D":"Mortalidade por determinada doença.","E":"Morbidade."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-64642","number":"64642","sourceNumber":"64642","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um gestor de saúde de determinada cidade está planejando a contrução de novos\nleitos hospitalares para tratamento exclusivo de\ncomplicações de pacientes com Diabetes Mellitus.\nSendo assim, assinale a alternativa que apresenta o melhor indicador para usar neste caso.","options":{"A":"Coeficiente de prevalência.","B":"Coeficiente de letalidade.","C":"Coeficiente de incidência.","D":"Taxa de ataque.","E":"Coeficiente de mortalidade."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-45741","number":"45741","sourceNumber":"45741","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que apresenta o tipo de doença rensponsável por maior causa de\nóbitos naturais no Brasil.","options":{"A":"doenças cardiovasculares","B":"neoplasias malignas","C":"doença pulmonar obstrutiva crônica","D":"diabetes melito","E":"doenças do aparelho osteomuscular"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32155","number":"32155","sourceNumber":"32155","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A secretaria de Saúde do Distrito Federal (SES-DF) confirmou nesta quinta-feira (07/10)\na morte de dezoito pessoas infectadas pela\nbactéria Klebsiella pneumoniae Carbapenemase (KPC).\nA SES-DF afirmou ainda que 111 paciente de hospitais públicos e particulares estão entre casos\nconfirmados de infecção pela bactéria em todo o DF. Dos 111 casos registrados entre janeiro e 1º\nde outubro deste ano, 58 foram registrados no Hospital Regional de Santa Maria (HRSM).\n\nConsiderando as informações do texto, bem como o fato de, no período de 1º de janeiro a 1º de\noutubro de 2010, terem sido internadas 120 mil pessoas na rede hospitalar pública e privada do\nDistrito Federal (DF) e, ainda, o esclarecimento de ser a população do DF composta por 2,5\nmilhões de habitantes, assinale a alternativa correta.","options":{"A":"A letalidade da infecção por KPC foi de 9%.","B":"O Hospital de Santa Maria teve uma incidência de 52,2% de casos de infecção por KPC.","C":"A mortalidade por KPC foi de 7,2 mortes por 100 mil habitantes.","D":"A prevalência de KPC foi de 1,5 X 10 mil habitantes.","E":"A taxa de ataque foi de 44,4 X 100 mil habitantes."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32178","number":"32178","sourceNumber":"32178","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Diversas políticas foram implantadas com algum sucesso para a diminuição da\nmortalidade infantil no Brasil. Nas últimas\ntrês décadas, houve uma diminuição de 83% na taxa de\nmortalidade infantil (TMI). Atualmente, a média nacional situa-se em torno de 24,9 óbitos para cada\nnascido vivo. Com relação ao comportamento desse indicador, é correto afirmar que:","options":{"A":"A TMI continuará diminuindo nos próximos anos até chegar a zero.","B":"A partir da década de 80 do século passado, a TMI diminuiu em decorrência da redução do seu\ncomponente pós-neonatal.","C":"O componente neonatal não é importante nas regiões com as menores TMI.","D":"A doença diarreica aguda no Brasil ainda é, na atualidade, a principal causa de óbito no primeiro\nano de vida.","E":"A diminuição da mortalidade infantil, por ser problema já superado, não faz parte dos objetivos\ndo milênio da OMS."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-37978","number":"37978","sourceNumber":"37978","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os Objetivos de Desenvolvimento do Milênio (ODMs) são um compromisso dos\npaíses-membros da Organização das Nações Unidas (ONU), firmado no ano 2000, visando ao\nalcance de metas até o ano de 2015. São oito os ODMs, sendo quatro os mais diretamente\n\nrelacionados à saúde: ODM 1: erradicar a fome e a pobreza extrema; ODM 4: reduzir a mortalidade\nna infância; ODM 5: melhorar a saúde materna; e\nODM 6: combater o vírus HIV e outras doenças.\nA respeito dos indicadores de saúde que fazem parte dos ODMs, julgue o item. O coeficiente de\nmortalidade infantil estima o risco de morte dos nascidos vivos durante o seu primeiro ano de vida.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32145","number":"32145","sourceNumber":"32145","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considerando que os indicadores demográficos são relevantes para a identificação das\nrecentes tendências populacionais, uma vez que dimensionam a população alvo das ações e\nserviços de saúde e orientam os processos de planejamento, gestão e avaliação de suas políticas\npara a população, assinale a alternativa que caracteriza a transição demográfica no Brasil.","options":{"A":"Diminuição das doenças infecciosas, com diminuição da expectativa de vida.","B":"Queda da mortalidade, com aumento da taxa de natalidade.","C":"Queda da mortalidade, com aumento da taxa de fecundidade.","D":"Aumento de envelhecimento populacional, com queda da fecundidade.","E":"Aumento da fecundidade, com aumento da expectativa de vida."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32146","number":"32146","sourceNumber":"32146","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"De acordo com a situação epidemiológica das doenças de notificação compulsória\ntransmissíveis no Brasil, assinale a alternativa que corresponde a doenças com tendência\nemergente e reemergente.","options":{"A":"Difteria, doença de Chagas e poliomielite.","B":"Dengue, hantavirose e AIDS.","C":"Rubéola, sarampo e coqueluche.","D":"Malária, tuberculose e hepatite viral.","E":"Meningite, malária e leishmaniose."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32159","number":"32159","sourceNumber":"32159","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de mortalidade por idade são medidas síntese que contêm informações\nrelevantes a respeito de determinados atributos e dimensões do estado de saúde. O desempenho\ndo sistema de saúde deve refletir a situação sanitária da população brasileira e servir para a\nvigilância das condições de saúde. Acerca desse assunto, assinale a alternativa que apresenta a\nação que permite reduzir a taxa de mortalidade neonatal precoce no Brasil.","options":{"A":"Implementação dos programas nutricionais para crianças de baixa renda.","B":"Ampliação do programa de imunização.","C":"Ampliação e melhoria do programa de saneamento básico.","D":"Diagnóstico precoce das malformações congênitas.","E":"Adequada assistência ao pré-natal e ao parto."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-29735","number":"29735","sourceNumber":"29735","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A hantavirose, uma doença emergente, apresenta duas formas clínicas principais: a\nfebre hemorrágica com síndrome renal (FHSR) e a\nsíndrome cardiopulmonar (SCPH). Os primeiros\ncasos de hantavirose no Distrito Federal (DF) foram registrados em 2004. De 2004 a 2008, foram\nregistrados 82 casos no DF. No ano de 2008, foram registrados três casos confirmados de\nhantavirose, com um óbito, no DF. No mesmo ano, foram registrados em Goiás, 10 casos\nconfirmados, com 3 óbitos. A respeito da hantavirose, julgue o item a seguir. Em 2008, o coeficiente\nde letalidade por hantavirose, no DF, foi inferior àquele registrado em Goiás.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-29738","number":"29738","sourceNumber":"29738","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Sistema de Informações sobre Mortalidade (SIM) foi criado em 1975. Esse sistema\niniciou sua fase de descentralização em\n1991, dispondo de dados informatizados a partir de 1979.\nSeu instrumento padronizado de coleta de dados é a Declaração de Óbito (DO), impressa em três\nvias coloridas, cuja emissão e distribuição para os estados, em séries pré-numeradas, é de\ncompetência exclusiva do Ministério da Saúde. Para os municípios, a distribuição fica a cargo das\nsecretarias estaduais de saúde, devendo as secretarias municipais se responsabilizarem por seu\ncontrole e distribuição entre os profissionais médicos e instituições que a utilizem, bem como pelo\nrecolhimento das primeiras vias em hospitais e cartórios. Com relação ao SIM, julgue o item\nseguinte. A análise dos dados do SIM permite a construção de importantes indicadores para o\ndelineamento do perfil de saúde de uma região. A partir das informações contidas nesse sistema,\npode-se obter a mortalidade proporcional por causas, faixa etária e sexo; a letalidade de agravos; a\nincidência de agravos de notificação compulsória; bem como as taxas de mortalidade geral, infantil\ne materna.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8575","number":"8575","sourceNumber":"8575","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à transição demográfica no Brasil, pode-se dizer que o envelhecimento da\npopulação nos últimos anos:","options":{"A":"processou-se de forma abrupta, muito mais rápida do que nos países europeus.","B":"é pouco relevante para a saúde no que se refere às demandas atuais por atenção médica.","C":"se deve ao processo de distribuição mais eficiente das consultas médicas, que reduziram a taxa\nde mortalidade brasileira.","D":"se deve ao Programa Nacional de Controle da Natalidade, implantado pelo Ministério da Saúde,\ndesde 1977.","E":"não deve ainda ser considerado no conjunto das políticas públicas para a saúde."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8578","number":"8578","sourceNumber":"8578","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em meados da década de 80, com o surgimento de casos de HIV/AIDS, até então\ndesconhecidos, aumentou o número de casos de tuberculose. Este aumento é medido e observado\npelas agências de Vigilância Epidemiológica, por meio do seguinte indicador:","options":{"A":"Letalidade.","B":"Prevalência.","C":"Mortalidade.","D":"Mortalidade proporcional.","E":"Incidência."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-13874","number":"13874","sourceNumber":"13874","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A mortalidade infantil no Brasil encontra-se em declínio. Há vários fatores que têm\ncontribuído para isso, entre eles a extensão de cobertura da atenção básica. Com referência à\nmortalidade infantil, assinale a opção correta.","options":{"A":"A taxa de mortalidade infantil é a soma das taxas de mortalidade neonatal precoce, neonatal\ntardia, pós-neonatal e mortalidade perinatal.","B":"A mortalidade neonatal precoce refere-se aos óbitos de crianças de 0 a 27 dias de vida\ncompletos.","C":"No Brasil, atualmente, o valor da taxa de mortalidade neonatal é menor do que o valor da taxa\nde mortalidade pós-neonatal.","D":"A mortalidade neonatal tardia refere-se aos óbitos de crianças de 7 a 27 dias de vida completos.","E":"A taxa de mortalidade infantil relaciona o número de óbitos de menores de 1 ano de idade com o\nnúmero de óbitos em determinado lugar e período."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-13882","number":"13882","sourceNumber":"13882","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Constata-se que a população brasileira está envelhecendo com aumento da esperança\nde vida e maior proporção de óbitos por\ndoenças cardiovasculares e neoplasias malignas. Com\nreferência a esse tema, assinale a opção correta.","options":{"A":"O indicador de Swaroop-Uemura está em franco declínio no Brasil.","B":"A mortalidade proporcional, segundo o gênero, é maior entre as mulheres em todos os grupos\netários.","C":"A relação entre o número de pessoas com 60 anos ou mais e o número daquelas com menos de\n15 anos tem apresentado valores decrescentes\nem todas as grandes regiões geográficas do Brasil.","D":"Dois indicadores revelam o envelhecimento da população brasileira: o aumento da proporção de\nidosos, 60 anos ou mais, e o aumento da proporção dos menores de 5 anos.","E":"A razão de dependência é um indicador demográfico que relaciona os indivíduos menores de 15\nanos, mais os de 60 anos ou mais, com indivíduos de idade entre 15 e 59 anos."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-14076","number":"14076","sourceNumber":"14076","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Baseado nos seguintes dados: população geral, população de menores de um ano,\nnúmero de óbitos de menores de um ano,\nnúmero total de óbitos, número de óbitos por doença\ntransmissíveis, número de óbitos por câncer de pele e número de óbitos de pessoas de 50 anos ou\nmais, podemos calcular as seguintes taxas, exceto:","options":{"A":"Índice de Swarrop & Uemura.","B":"Mortalidade geral.","C":"Mortalidade infantil.","D":"Mortalidade por câncer de pele.","E":"Mortalidade por doenças sexualmente transmissíveis."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-352341","number":"352341","sourceNumber":"352341","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Clara, uma adolescente de 16 anos, comparece à unidade básica de saúde (UBS) em\nbusca de atendimento médico. Na recepção,\no atendente responsável pelo acolhimento verifica o\nendereço de Clara, confirma que ela reside na área de abrangência da UBS e a encaminha para a\nsala da equipe de saúde da família de sua área. Lá, ela é atendida por uma enfermeira da equipe,\nque, após coletar informações sobre a queixa e sua duração, bem como aferir os sinais vitais,\nreconhece sinais de gravidade. Diante disso, a enfermeira aloca a paciente em uma maca na sala\nde medicação e chama imediatamente o médico da equipe, que a atende prontamente. Clara relata\nque está sentindo dor na região hipogástrica e disúria há cerca de três dias, com uma piora\ngradual. Ela teve calafrios durante a última noite, mas não percebeu que poderia estar com febre. A\npaciente está mais preocupada com as dores e com um atraso menstrual. Ela não consegue\nfornecer a data da última menstruação, mas acredita que tenha ocorrido antes do nascimento de\nseu irmão, que hoje tem três meses. Ao realizar o exame físico, a equipe de saúde observa que\nClara está sonolenta, febril, eupneica, sudoreica, com livedo e mal perfundida. Os pulsos estão\nsimétricos, as bulhas cardíacas são normofonéticas, mas a paciente apresenta taquicardia e um\nsopro sistólico. O exame abdominal revela dor à palpação na região hipogástrica. Além disso, foram\nidentificadas equimoses em diferentes estágios de evolução em seu tórax e abdome. Quando\nquestionada sobre as lesões equimóticas, Clara começa a chorar e pede para não abordar mais o\nassunto. Tendo como base o caso acima, a política nacional de humanização, os atributos e\nfunções da atenção primária e conhecimentos correlatos, julgue o item a seguir. Em relação à\ntransição epidemiológica brasileira, o caso de Clara evidencia um dos componentes da chamada\n\"tripla carga\" de doenças, que são as doenças infecciosas. Os outros dois componentes são as\ncausas externas e as doenças neoplásicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-366189","number":"366189","sourceNumber":"366189","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Acerca da Medicina de Família e Comunidade (MFC) e da Atenção Primária a Saúde\n(APS) no Brasil e no mundo e suas\ntecnologias, julgue o item seguinte. A referência é uma\nferramenta essencial para a coordenação do cuidado, contudo, não deve ser usada\nindiscriminadamente, sendo aceitável uma taxa de 25% em relação ao número de atendimentos\nrealizados, sendo um indicador de resolubilidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-366188","number":"366188","sourceNumber":"366188","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Acerca da Medicina de Família e Comunidade (MFC) e da Atenção Primária a Saúde\n(APS) no Brasil e no mundo e suas\ntecnologias, julgue o item seguinte. A taxa de contrarreferência\né uma forma importante de avaliar o funcionamento do sistema, uma vez que demonstra o\nadequado comprometimento das equipes de maior complexidade na continuidade do cuidado do\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-334910","number":"334910","sourceNumber":"334910","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os sistemas de informação do Sistema Único de Saúde são importantes ferramentas\npara se conhecer, avaliar e planejar a saúde\npública no Brasil. Assinale a alternativa que\nrepresenta a fonte que alimenta o SINAN.","options":{"A":"Declaração de nascido vivo","B":"Declaração de óbito","C":"Autorização de internação hospitalar.","D":"Notificação compulsória.","E":"Prontuário eletrônico do cidadão."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-334912","number":"334912","sourceNumber":"334912","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Para Eugênio Vilaça Mendes (2010), em As redes de atenção à saúde, ?a crise\ncontemporânea dos sistemas de atenção à\nsaúde que se manifesta, em maior ou menor grau, em\ntodos os países do mundo, decorre de uma incoerência entre uma situação de saúde de transição\ndemográfica e de transição epidemiológica completa nos países desenvolvidos e [...] tripla carga de\ndoenças nos países em desenvolvimento e o modo como se estruturam as respostas sociais\ndeliberadas às necessidades das populações?. No Brasil, a tripla carga de doenças de relaciona\ncom:","options":{"A":"Doenças crônicas; transtornos mentais e comportamentais e neoplasias.","B":"Causas externas; neoplasias; e doenças endócrinas, metabólicas e nutricionais.","C":"Doenças infecciosas, parasitárias e problemas de saúde reprodutiva; neoplasias e transtornos\nmentais e comportamentais.","D":"Doenças endócrinas; metabólicas e nutricionais; transtornos mentais e comportamentais e\ndoenças infecciosas e parasitárias.","E":"Doenças infecciosas, parasitárias e problemas de saúde reprodutiva; causas externas e doenças\ncrônicas."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-334913","number":"334913","sourceNumber":"334913","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A declaração de nascido vivo tem importância clínico-assistencial, social e\nepidemiológica. Quando se realiza um parto\nhospitalar, seu preenchimento em três deve seguir a\ncorreta destinação para que sua missão seja alcançada. Acerca desse tema, assinale a alternativa\nque corresponde ao correto encaminhamento de via.","options":{"A":"A primeira via é branca e permanece no hospital até ser coletada pela Secretaria de Saúde para\nfins epidemiológicos.","B":"A primeira via é amarela e deve ser entregue à família a fim de ser levada ao cartório e para\nrealização do registro civil.","C":"A segunda via é rosa e deve ficar arquivada no hospital, junto ao prontuário médico do\nrecém-nascido.","D":"A segunda via é branca e deve ser entregue à família a fim de ser levada ao cartório e para\nrealização do registro civil.","E":"A terceira via é rosa e permanece no hospital até ser coletada pela Secretaria de Saúde para\nfins epidemiológicos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-307129","number":"307129","sourceNumber":"307129","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Observe, na tabela a seguir, alguns dados hipotéticos a respeito de mortalidade\nproporcional por faixa etária em duas cidades.\nConsiderando os dados apresentados, é correto\nafirmar que o índice de Swaroop & Uemura (ou razão de mortalidade proporcional) é Alternativas:","options":{"A":"de 4% para a cidade X e 6,4% para a cidade Y.","B":"de 56% para a cidade Y.","C":"de 20% para a cidade Y.","D":"maior na cidade X que na cidade Y.","E":"igual em ambas as cidades."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-301338","number":"301338","sourceNumber":"301338","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à saúde dos homens, julgue os itens de 93 à 96. O homem é mais\nvulnerável à violência, seja como autor,\nseja como vítima, e os homens adolescentes e jovens são\nos que mais sofrem lesões e traumas por agressões, que são mais graves e demandam maior\ntempo de internação, em relação às sofridas pelas mulheres.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-301339","number":"301339","sourceNumber":"301339","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à saúde dos homens, julgue os itens de 93 à 96. No contexto geral das 10\nneoplasias malignas que mais frequentemente causaram a morte, logo após o câncer de pulmão,\ntraqueia e brônquios, aparece o câncer de próstata, que geralmente é uma neoplasia de rápida\nevolução, devendo ser diagnosticada e tratada com precocidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-274604","number":"274604","sourceNumber":"274604","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quanto à qualidade de vida, a Organização Mundial da Saúde (OMS), utilizando-se de\num método transcultural (WHOQOL), afirma que\n?embora não haja definição consensual de\nqualidade de vida, há concordância considerável entre os pesquisadores acerca de algumas\ncaracterísticas do constructo qualidade de vida?. A alternativa que apresenta CORRETAMENTE as\ncaracterísticas desse constructo é:","options":{"A":"Subjetividade, multidimensionalidade e bipolaridade, esta última consubstanciada em dimensões\npositivas e negativas.","B":"Multidimensionalidade, sociabilidade e subjetividade, sendo esta última pura e não total.","C":"Multidimensionalidade, sociabilidade e subjetividade, esta última pura e total.","D":"Bipolaridade, sociabilidade e multidimensionalidade, incluindo três dimensões: a física, a\npsicológica e a social."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-291499","number":"291499","sourceNumber":"291499","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A figura a seguir apresenta a mortalidade proporcional por alguns grupos de causa no\nsexo masculino e em grupos etários selecionados.\nCom base nos dados demonstrados nos\ngráficos, conclui-se que","options":{"A":"as agressões e as causas externas de intenção indeterminada são responsáveis por pelo menos\n50% dos óbitos ocorridos na faixa etária de\n15 a 29 anos.","B":"na faixa etária dos 60 anos e mais, a mortalidade proporcional por doença isquêmica do coração\né menor do que a faixa etária de 30 a 59 anos.","C":"as doenças respiratórias, na faixa etária de 60 anos e mais, causam mais óbitos do que as\ndoenças do aparelho circulatório.","D":"atividades educativas visando reduzir o consumo excessivo de bebidas alcoólicas teria menor\nimpacto nos indicadores de mortalidade relativos às faixas etárias de 15 a 59 anos que na faixa\netária de 60 anos ou mais."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-263385","number":"263385","sourceNumber":"263385","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O quadro a seguir apresenta os dados sobre a mortalidade nas capitais brasileiras por\nCOVID-19 e a população que vive com menos de US$ 5,5 por dia, faixa que define a linha da\npobreza, segundo o Banco Mundial. Com base nas informações do quadro apresentado, assinale a\nalternativa correta.","options":{"A":"As capitais com as maiores taxas de mortalidade por COVID-19 possuem maior população\nestimada, indicando maior concentração demográfica e, portanto, maior risco de contágio.","B":"Não há associação entre a mortalidade por COVID-19 e a taxa de população mais pobre, pois a\nocorrência de morte pela doença se relaciona à idade e à presença de comorbidades.","C":"Há grande diferença na mortalidade por COVID-19, sendo mais elevada onde é maior a\nproporção de pessoas mais pobres, o que reforça a determinação social da saúde.","D":"As capitais com maiores taxas de mortalidade por COVID-19 apresentam menores proporções\nde pessoas com rendimento familiar abaixo da linha\nda pobreza."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-291506","number":"291506","sourceNumber":"291506","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Segundo a Política Nacional da Atenção Básica (2017), como atribuição comum a todos\nos membros das equipes que atuam na Atenção\nPrimária em Saúde, inclusive ao médico, consta:\n\"Realizar busca ativa de internações e atendimentos de urgência/emergência por causas sensíveis\nà Atenção Básica, a fim de estabelecer estratégias que ampliem a resolutividade e a\nlongitudinalidade pelas equipes que atuam na Atenção Básica\". Considerando as causas sensíveis\ne o perfil de mortalidade por causa da população brasileira, aquelas estratégias com maior impacto\npara a redução dessas causas de morte na população de 50 anos e mais são ações de","options":{"A":"controle da hipertensão arterial e do diabetes mellitus.","B":"educação no trânsito e de denúncia e prevenção de violência.","C":"orientação aos trabalhadores, visando reduzir acidentes de trabalho e doenças ocupacionais.","D":"rastreamento de câncer de mama e câncer de próstata."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-274674","number":"274674","sourceNumber":"274674","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O significado de doença e as formas de abordá-la têm sofrido variações com o passar\ndo tempo. Nesse contexto, é importante\ndistinguir os conceitos de doença aguda, crônica e\ncrônico-degenerativa. Quanto às situações crônico-degenerativas, é CORRETO afirmar:","options":{"A":"São situações de evolução lenta e gradual, geralmente assintomáticas, e não têm causa e/ou\ntratamento definidos.","B":"Infarto agudo do miocárdio, acidentes vasculares cerebrais e insuficiência cardíaca congestiva\nsão reconhecidas como condições crônicas.","C":"Instalam-se abruptamente, produzindo sinais e sintomas logo após a exposição à causa, em um\nperíodo determinado para sua recuperação.","D":"São problemas de longo prazo, devido a distúrbio, acúmulo de distúrbios irreversíveis ou estado\npatológico latente."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-274678","number":"274678","sourceNumber":"274678","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação aos padrões de morbidade e suas diferenciações para homens e\nmulheres, é amplamente reconhecido que as mulheres apresentam as taxas mais altas de\nadoecimento registrado. Considerando o contexto, a alternativa que apresenta, de forma\nCORRETA, fatores que explicam tais diferenças é:","options":{"A":"As desigualdades de valor e iniquidades sociais, em geral, entre homens e mulheres.","B":"Os homens terem maiores dificuldades econômicas, sobretudo na velhice.","C":"As mulheres serem mais suscetíveis ao estresse no ambiente do trabalho e os homens no\nambiente doméstico/familiar.","D":"As diferentes percepções e valorização do adoecimento ou dos primeiros sinais de adoecimento\nem razão da identificação simbólica de adoecer\ncom fraqueza e fragilidade, referenciais que\ndefiniriam o masculino, mas não o feminino."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-244503","number":"244503","sourceNumber":"244503","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Entre 500 crianças cadastradas na Estratégia Saúde da Família e acompanhadas\ndurante um ano, foram diagnosticados, nesse\nperíodo, 25 novos casos de anemia. Com base\nnisso, assinale a alternativa que corresponde à incidência desses casos.","options":{"A":"0.06","B":"0.05","C":"0.04","D":"0.03","E":"0.02"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-244505","number":"244505","sourceNumber":"244505","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, o maior causador de anos potenciais de vida perdidos são os seguintes\nagravos:","options":{"A":"Neoplasias.","B":"Doenças do aparelho circulatório.","C":"Causas externas.","D":"Doenças do aparelho respiratório.","E":"Doenças maternas."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-230632","number":"230632","sourceNumber":"230632","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Ocorreu queda da mortalidade nas idades avançadas, sendo que a vida média da\npopulação brasileira aumentou quase 12 anos no período, sendo diversos os fatores responsáveis\npor esse movimento, indique a alternativa ERRADA:","options":{"A":"Como consequência, cresce a população em idade mais avançada, que também envelhece e se\ntorna mais homogênea.","B":"Esta heterogeneidade se dá, entre outros fatores, pela sua composição por sexo, por idade e\nperfil epidemiológico diferenciados.","C":"Salienta-se ainda que não só a continuação do processo de envelhecimento é esperada, mas\npode-se esperar, também, o envelhecimento da própria população idosa.","D":"A população que mais cresce é a de 80 anos ou mais, dada a redução da mortalidade nestas\nidades."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-227459","number":"227459","sourceNumber":"227459","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação às competências do médico da família e comunidade, ao trabalho na APS\ne às políticas de saúde, julgue o item\nsubsequente. O enfrentamento ao sofrimento mental deve ser\numa prioridade para a Política Nacional de Saúde Integral da População Negra, porque o suicídio é\numa das principais causas de morte por causas externas de jovens negros no Brasil.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-212073","number":"212073","sourceNumber":"212073","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à conjuntura das condições crônicas no Brasil, julgue o item a seguir. As\nnovas tecnologias utilizadas para diagnósticos\ne tratamentos terapêuticos vêm promovendo a\nredução contínua da mortalidade proporcional por doenças cardiovasculares no Brasil, fato que tem\nsido observado desde meados do século XX.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-212118","number":"212118","sourceNumber":"212118","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação a morbidade e mortalidade por causas externas no Brasil, julgue o item\nsubsequente. O Brasil vivencia uma situação complexa, marcada por uma tripla carga de doença;\ncumprimento incompleto da agenda de combate a doenças infecciosas, aumento das doenças\ncrônicas e forte crescimento da morbidade e da mortalidade por causas externas, que acomete\njovens em plena capacidade produtiva, resultando em alto custo para a sociedade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-212100","number":"212100","sourceNumber":"212100","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação a morbidade e mortalidade por causas externas no Brasil, julgue o item\nsubsequente. O crescimento da taxa de mortalidade por homicídio no Brasil vem atingindo\nproporções alarmantes nos últimos anos, especialmente por acometer predominantemente jovens\nentre os quinze anos de idade e os vinte e nove anos de idade, do sexo feminino, moradoras das\ngrandes metrópoles brasileiras.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-168478","number":"168478","sourceNumber":"168478","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O gestor de saúde de um município de 200.000 habitantes no Brasil desenvolveu um\nestudo para estimar a prevalência de\nhipertensão arterial sistêmica para o planejamento da atenção\nà saúde dessa população, especialmente a dispensação de medicamentos anti-hipertensivos. Em\numa amostra de 2.500 pessoas pesquisadas, 20% ( IC 95% = 18,5 - 21,5) apresentavam\ndiagnóstico de hipertensão e já tinham indicação de tratamento medicamentoso. No mesmo ano em\nque foi desenvolvida a pesquisa, 19% da população utilizou as farmácias municipais e privadas\npara tratamento da hipertensão. Considerando essas informações, assinale a alternativa correta\nacerca dessa situação epidemiológica.","options":{"A":"A adesão ao tratamento da hipertensão está adequada, uma vez que a proporção de pacientes\nque utilizaram as farmácias para esse tratamento\npode ser igual a prevalência estimada da\nhipertensão.","B":"A adesão ao tratamento da hipertensão não pode ser avaliada, uma vez que a proporção de\npacientes que utilizaram as farmácias para esse tratamento está abaixo da prevalência estimada de\nhipertensão.","C":"São necessárias campanhas de orientação para prevenção secundária da hipertensão arterial,\npois a prevalência estimada do município é\nmuito maior do que a prevalência atual no país.","D":"A estimativa da prevalência de hipertensão arterial no município varia de ,18,5% a no município\nvaria de 21,5,% o que dificulta a\nimplementação de políticas estratégicas de adesão ao tratamento\nnesse município em particular."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-168438","number":"168438","sourceNumber":"168438","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Equipe de Saúde da Família de determinada Unidade Básica de Saúde (UBS) na\nregião Norte do país iniciou, em 2017, o planejamento e o desenvolvimento de algumas atividades\nestratégicas que incluiam ações voltadas para: 1. busca ativa e diagnóstico da hanseníase; 2.\nbusca ativa de sintomáticos respiratórios; 3. condução de grupo de orientação alimentar para\npessoas com diabetes melito e hipertensão arterial sistêmica; 4. implementação de campanha de\nincentivo à realização de testes rápidos para a detecção de hepatites virais B e C. Espera-se, com\nessas medidas, que os indicadores de saúde, na área de abrangência dessa UBS, tenham a\nseguinte evolução:","options":{"A":"aumento da taxa de detecção de casos novos de hanseníase; aumento da taxa de incidência de\ntuberculose; diminuição da taxa de internação por infarto agudo do miocárdio e por acidente\nvascular cerebral e aumento de taxas de prevalência das hepatites virais B e C.","B":"diminuição da taxa de prevalência da hanseníase; diminuição da taxa de mortalidade por\ntuberculose; diminuição das taxas de letalidade por infarto agudo do miocárdio e por acidente\nvascular cerebral e diminuição das taxas de prevalência das hepatites virais B e C.","C":"aumento da taxa de prevalência da hanseníase; diminuição da taxa de mortalidade proporcional\npor tuberculose; diminuição dos coeficientes de\nprevalência de diabetes melito e hipertensão\narterial; e diminuição das taxas de mortalidade por hepatites virais B e C.","D":"aumento da taxa de detecção de casos novos de hanseníase em crianças; aumento da taxa de\ncura da tuberculose; diminuição das taxas\nde mortalidade por diabetes melito e hipertensão arterial;\ne diminuição das taxas de letalidade por hepatites virais B e C."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-158046","number":"158046","sourceNumber":"158046","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quanto aos testes diagnósticos para investigação de doenças, assinale a alternativa\nCORRETA.","options":{"A":"A realização de testes em paralelo diminui a sensibilidade do processo investigativo, mas\naumenta a respectiva especificidade.","B":"A prevalência da doença em determinada população não afeta a sensibilidade e a especificidade\ndo teste.","C":"Enquanto os testes de triagem devem apresentar alta especificidade, os teste para confirmação\ndiagnóstica devem apresentar alta sensibilidade.","D":"Em testes quantitativos, modificar o ponto de corte para aumentar a especificidade não costuma\nalterar a sensibilidade.","E":"A acurácia de um teste é a sua capacidade de ser positivo dos pacientes doentes."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-158049","number":"158049","sourceNumber":"158049","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A incidência e prevalência das doenças crônicas sofrem variações ao longo do tempo e\nconforme modificam-se as abordagens a elas relacionadas. No que se refere à prevalência da\ncardiomiopatia chagásica, assinale a alternativa CORRETA quanto a um fator que poderia causar\naumento dessa prevalência.","options":{"A":"Diminuição da presença de artrópodes da subfamília Triatominae.","B":"Aumento da presença de mosquitos do gênero Culex.","C":"Surgimento de um novo tratamento que diminua a letalidade da doença.","D":"Surgimento de um tratamento curativo.","E":"Aumento da letalidade da doença."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-159604","number":"159604","sourceNumber":"159604","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Nas estatísticas vitais de determinado ano para uma cidade A, localizada na região\nnorte do Brasil, foi observado que o índice\nde mortalidade neonatal atingiu 30/1000, com 80% dos\nóbitos ocorrendo por hipóxia perinatal; ao mesmo tempo, para uma cidade B, localizada na região\nsul do Brasil, a taxa de prematuridade foi de 10% e a de baixo peso ao nascer foi de 12,5%. Para\nesse mesmo período, o indice de mortalidade neonatal para o Brasil foi de 14/1000, com 50% dos\nóbitos ocorrendo por prematuridade; a taxa de prematuridade foi de 15% e a de baixo peso ao\nnascer de 25%. A partir desses dados, julgue o item seguinte. A taxa de mortalidade neonatal da\ncidade A está bem acima da aceita por organismos nacionais de saúde. Medidas de atenção ao\nparto e ao recém-nascido deveriam ser prioritariamente ampliadas nas políticas públicas de saúde\nda cidade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-159606","number":"159606","sourceNumber":"159606","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Nas estatísticas vitais de determinado ano para uma cidade A, localizada na região\nnorte do Brasil, foi observado que o índice\nde mortalidade neonatal atingiu 30/1000, com 80% dos\nóbitos ocorrendo por hipóxia perinatal; ao mesmo tempo, para uma cidade B, localizada na região\nsul do Brasil, a taxa de prematuridade foi de 10% e a de baixo peso ao nascer foi de 12,5%. Para\nesse mesmo período, o indice de mortalidade neonatal para o Brasil foi de 14/1000, com 50% dos\nóbitos ocorrendo por prematuridade; a taxa de prematuridade foi de 15% e a de baixo peso ao\nnascer de 25%. A partir desses dados, julgue o item seguinte. Medidas de atenção ao pré-natal de\nalto risco deveriam ser prioritárias e intensivamente ampliadas nas políticas públicas de saúde da\ncidade B.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-168437","number":"168437","sourceNumber":"168437","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Na tabela a seguir, são apresentadas as distribuições, por regiões do Brasil, dos óbitos\nde crianças com até um ano de vida, segundo\nfaixa etária, para o ano de 2013. (Conforme imagem\nno caderno de questões) Considerando os dados apresentados nessa tabela, assinale a alternativa\nque apresenta a faixa etária com maior taxa de mortalidade no Brasil, em 2013, e as principais\ncausas de óbito a ela associadas.","options":{"A":"Entre 0 e 6 dias, por anomalias congênitas e afecções perinatais.","B":"Entre 7 e 27 dias, por doenças infecciosas e de origem nutricional.","C":"Entre 0 e 6 dias, por doenças infecciosas e fatores socioambientais.","D":"Entre 28 e 364 dias, por causas relacionadas à assistência direta ao parto."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-159578","number":"159578","sourceNumber":"159578","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Julgue o item subsecutivo acerca de causas de óbitos mais comuns. No quadro geral\nde causas de óbitos, atualmente a mortalidade por causas externas ocupam, no DF, o terceiro\nlugar, ficando atrás apenas de doenças cardiovasculares e neoplasias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-133967","number":"133967","sourceNumber":"133967","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A identificação do padrão de ocorrência de doenças nas populações humanas e os\nfatores que influenciam e condicionam são\ndefinidos como objetos de estudo da epidemiologia. Na\ninvestigação epidemiológica, a definição e identificação da doença tem uma natureza ditada:","options":{"A":"Pela individualidade de cada paciente.","B":"Pela tendência a não padronização e comparabilidade.","C":"Pelo objeto clínico essencialmente qualitativo.","D":"Por resultados não submetidos à comparação.","E":"Pela definição quantitativa e pelas relações numéricas entre eventos."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-133973","number":"133973","sourceNumber":"133973","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Taxa de prevalência (TP) em doenças indica a qualidade do que prevalece e implica\nacontecer e permanecer existindo em momento considerado. Essa taxa é mais utilizada para\ndoenças","options":{"A":"que foram descobertas ou diagnosticadas (casos novos, hipertensão, diabetes).","B":"crônicas de longa duração (hanseníase, tuberculose, Aids e diabetes).","C":"que estão sendo tratados (casos antigos) mais as que foram descobertas ou diagnosticadas\n(casos novos).","D":"neoplásticas que evoluíram para cura.","E":"motoras traumáticas em determinada região."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-104781","number":"104781","sourceNumber":"104781","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"De acordo com a publicação do Ministério da saúde - Estimativa 2014: Incidência de\nCâncer no Brasil, excluindo-se os tumores de pele não melanoma, assinale a alternativa que\napresenta a estimativa correta de novos casos para o ano de 2014.","options":{"A":"Os cânceres de traqueia, brônquio e pulmões deverão ser menos frequentes em homens que\nem mulheres.","B":"O câncer de mama deverá ser o segundo mais frequente em mulheres.","C":"O câncer colorretal deverá ser o tumor do aparelho digestório mais frequente, tanto em homens\nquanto em mulheres.","D":"O câncer de colo de útero deverá ser o mais frequente em mulheres.","E":"O câncer de próstata deverá ser o segundo mais frequente em homens."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-104771","number":"104771","sourceNumber":"104771","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que apresenta o período em que se concentram as mortes\ninfantis no País.","options":{"A":"Período neonatal precoce, ou seja, primeira semana.","B":"Período neonatal tardio, ou seja, entre a segunda semana e um mês de vida.","C":"Na primeira infância, a partir de um mês de vida.","D":"Na segunda infância.","E":"Na adolescência."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-104753","number":"104753","sourceNumber":"104753","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"De acordo com o Guia para os Profissionais de Saúde, Atenção à Saúde do\n\nRecém-Nascido e Cuidados Gerais do Ministério da Saúde - 2011, o sistema de informação sobre\nnascidos vivos (Sinasc) possibilita traçar o perfil dos nascimentos em cada hospital, município e\nestado para caracterizar a população, auxiliar no planejamento e calcular taxas de mortalidade, por\nexemplo, hospitalares, tendo como documento básico a Declaração de Nascido Vivo (DNV). Com\nbase nessas informações, assinale a alternativa que apresenta a evolução do perfil reprodutivo da\npopulação brasileira.","options":{"A":"Nas últimas três décadas, houve aumento da taxa de fecundidade (número médio de filhos\nnascidos vivos por mulher) no País.","B":"A proporção de mães adolescentes vem diminuindo no País.","C":"Observa-se uma diminuição da proporção de gestações em mulheres com mais de 35 anos de\nidade.","D":"Vem sendo resgistrado aumento da incidência da prematuridade e do baixo peso ao nascer\napesar da queda das cesarianas programadas\ncom interrupção indevida da gravidez, sem\njustificativa médica.","E":"A proporção de gestantes que fazem consultas pré-natais aumentou, apesar de importantes\ndiferenças regionais."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-97837","number":"97837","sourceNumber":"97837","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A prevalência de hanseníase registrada pela Organização Mundial da Saúde (OMS) no\nprimeiro trimestre de 2012 foi de 181.941 casos, com 219.075 casos novos diagnosticados em 105\npaíses em 2011, dos quais 94% foram notificados em 18 países, incluindo o Brasil. No Brasil, em\n2011, o coeficiente de incidência da doença foi de 17,65 casos para cada 100.000 habitantes.\n\nLevando em conta o mecanismo de transmissão da hanseníase e a variação na sua notificação,\npodemos afirmar que","options":{"A":"por se tratar de uma doença aguda, transmitida de pessoa a pessoa, com contato íntimo e\nduradouro e com período de incubação de cerca de 10 a 15 dias, o descritor de eleição para\nmonitorar e controlar a doença é a taxa de ataque e o coeficiente de ataque secundário.","B":"embora fatores biológicos desempenhem papel importante na transmissão da doença, por se\ntratar de uma doença negligenciada, a alta concentração de casos notificados em poucos países\nestá relacionada ao baixo nível socioeconômico e de instrução, falta de serviços de saúde e\nmoradia inadequada.","C":"a doença é transmitida, predominantemente, pela mucosa oral e mucosa do trato respiratório,\natravés de aerossóis e secreções orais e\nnasais e o M. leprae caracteriza-se por baixa infectividade\ne alta patogenicidade, o que significa que poucos se infectam e muitos adoecem.","D":"para o cálculo do coeficiente de incidência, no Brasil, em 2011, foi utilizada a somatória do\nnúmero de casos novos ou iniciados no\nperíodo acrescida do número de casos antigos existentes\nno período em estudo."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-75492","number":"75492","sourceNumber":"75492","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Mulher com 18 anos de idade, solteira, primigesta, decidiu interromper sua gravidez\nindesejada, procurando uma clínica clandestina\nde aborto. Após o procedimento, a paciente foi\nliberada para casa com fortes dores pélvicas. Não procurou atendimento imediato com medo de ser\ndiscriminada, ou mesmo presa, por ter feito um aborto ilegal. Após três dias, com febre alta e\nfortes\ndores, procurou a Maternidade, onde foi internada com diagnóstico de abortamento infectado. A\ndespeito do tratamento antimicrobiano, o quadro clínico da paciente deteriorou e ela evoluiu em 48\nhoras para um quadro de abdome agudo. Foi realizada laparotomia exploradora, sendo\nevidenciadas diversas perfurações em alças intestinais, com presença de material fecaloide e\npurulento em cavidade peritoneal, sendo a paciente tratada com sutura intestinal e limpeza\nexaustiva da cavidade. Encaminhada à Unidade de Terapia Intensiva, a paciente não teve melhora,\ntendo sido submetida à histerectomia abdominal total dois dias após. No pós-operatório, evoluiu\ncom choque séptico, necessitando da introdução de drogas vasoativas. Permaneceu mais 50 dias\ninternada, evoluindo com insuficiência renal e falência múltipla de órgãos, vindo a falecer 60 dias\napós a realização do aborto. Ao analisar esse óbito, o médico responsável pelo Comitê de\nPrevenção e Controle da Mortalidade Materna deve atestar que:","options":{"A":"se trata de morte materna de causa evitável\ndecorrente de erro médico, devido a perfurações\nuterinas, que causam peritonite e sepse.","B":"não é caso de morte materna, pelo fato de o óbito ter ultrapassado 42 dias após o término da\ngestação.","C":"se trata de morte materna de causa obstétrica indireta devido a complicações infecciosas na\ngravidez.","D":"se trata de morte materna de causa obstétrica direta devido a complicações do abortamento.","E":"se trata de morte materna de causa inevitável devido a quadro séptico generalizado."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-75481","number":"75481","sourceNumber":"75481","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Tuberculose (TB) é um problema de Saúde Pública no Brasil. A identificação precoce\nde pessoas com TB é imprescindível para a\nquebra da cadeia de transmissão da doença. No Brasil,\nem 2008, a TB foi a quarta causa de morte por doenças infecciosas e a primeira causa de morte em\npacientes com AIDS. Com o aumento do número de casos de pacientes com AIDS na população\nprisional, eleva-se a quantidade de pacientes com TB. Neste cenário, o indicador que expressa o\nnúmero de casos novos da doença nesta população no período de 1 ano é:","options":{"A":"Letalidade.","B":"Incidência.","C":"Morbidade.","D":"Prevalência.","E":"Mortalidade."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-30990","number":"30990","sourceNumber":"30990","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Transição demográfica é o processo de mudança da estrutura etária de uma população\nno sentido do seu envelhecimento, e a transição\nepidemiológica é a mudança observada no perfil\nde adoecimento e morte de uma população, no sentido ou como consequência do seu\nenvelhecimento. Acerca desses dois fenômenos, julgue o seguinte item. Segundo dados oficiais do\nMinistério da Saúde, no Brasil, alguns indicadores de saúde têm piorado progressivamente, como é\no caso do número bruto de óbitos por agressão por armas de fogo, sendo vítimas, na maioria dos\ncasos, do sexo masculino.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-31011","number":"31011","sourceNumber":"31011","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As doenças crônicas não transmissíveis (DCNT) constituem sério problema de saúde\npública, tanto nos países ricos quanto nos de média e baixa renda. Estimativas da Organização\nMundial de Saúde apontam que as DCNT são responsáveis por 58,5% de todas as mortes\nocorridas no mundo e por 45,9% da carga global de doença. A respeito das DCNT e dos seus\nfatores de risco e proteção, julgue o item subsequente. A obesidade e o sobrepeso são importantes\nfatores de risco para DCNT, em especial para diabetes e doenças cardiovasculares; é fundamental,\nportanto, o investimento em saúde voltado à prevenção primária das DCNT.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-138720","number":"138720","sourceNumber":"138720","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considere que, em uma cidade de dois milhões de habitantes, houve 400 casos de\ngripe pelo vírus H1N1, no ano de 2009. Oito pessoas faleceram. O cálculo do coeficiente de\nletalidade das infecções pelo vírus H1N1 nessa cidade resulta em que valor?","options":{"A":"0,000004","B":"0,0002","C":"0,02","D":"0,04","E":"0,2"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8708","number":"8708","sourceNumber":"8708","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de saúde, paradoxalmente, medem, em geral, a quantidade de agravos\ne óbitos que ocorrem em uma população. Acerca\ndesses indicadores, julgue o item que se segue.\nA relação entre o número de casos novos de determinado agravo que ocorrem em determinado\nlugar e período de tempo e o número de pessoas expostas ao risco de adquiri-lo é conhecida como\ncoeficiente ou taxa de incidência de tal agravo, no local e período avaliados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8709","number":"8709","sourceNumber":"8709","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de saúde, paradoxalmente, medem, em geral, a quantidade de agravos\ne óbitos que ocorrem em uma população. Acerca\ndesses indicadores, julgue o item que se segue.\nO valor do indicador de Swaroop-Uemura é tanto maior quanto maior for o percentual de pessoas\nidosas na população estudada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-354111","number":"354111","sourceNumber":"354111","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A maioria dos indicadores de nível da saúde baseia-se em dados de mortalidade e foi\nproposto em 1957, ao compararem dois grupos de países que classificavam como \"desenvolvidos\"\ne \"subdesenvolvidos\", calculando, pela técnica da função discriminante linear, os valores da\ndistância quadrática generalizada de Mahalanobis, referentes às percentagens de óbitos contadas\na partir de cada um dos limites dos grupos etários usuais. Trata-se da percentagem de óbitos em\ngrupo de 50 anos ou mais. Marque a alternativa cujo indicador expressa essa Razão de\nMortalidade Proporcional (RMP) na faixa etária especificada acima.","options":{"A":"Coeficiente de Ataque Secundário.","B":"Índice de Mortalidade Geral.","C":"Índice de Swaroop & Uemura.","D":"Índice de Mortalidade por causa específica.","E":"Quantificação de Guedes."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-373590","number":"373590","sourceNumber":"373590","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No geral, o Plano de Ações Estratégicas para o Enfrentamento das Doenças Crônicas\nNão Transmissíveis (DCNT) no Brasil, no período de\n2010 a 2019, apresentou avanços e já\nconseguiu atingir metade das metas parciais antes mesmo do término de sua vigência, que\nacontecerá em 2022. Sobre isso pode-se afirmar que:","options":{"A":"A atenção se volta para aquelas com previsão de que não serão atingidas até 2022, sem a\nnecessidade de serem tomadas medidas que impactem na reversão do cenário de não alcance e\nque garantam as mudanças necessárias ao sucesso delas na vigência do novo Plano.","B":"A atenção se volta para aquelas com previsão de que não serão atingidas até 2022, com a\nnecessidade de serem tomadas medidas que impactem na reversão do cenário de não alcance e\nque não garantam as mudanças necessárias ao sucesso delas na vigência do novo Plano.","C":"A atenção se volta para aquelas com previsão de que não serão atingidas até 2022, com a\nnecessidade de serem tomadas medidas que não impactem na reversão do cenário de não alcance\ne que garantam as mudanças necessárias ao sucesso delas na vigência do novo Plano.","D":"A atenção se volta para aquelas com previsão de que não serão atingidas até 2022, com a\nnecessidade de serem tomadas medidas que impactem na reversão do cenário de não alcance e\nque garantam as mudanças necessárias ao sucesso delas na vigência do novo Plano."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-373588","number":"373588","sourceNumber":"373588","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A prevalência de consumo recomendado de frutas e de hortaliças demonstrou\nestabilidade de 2010 a 2019.","options":{"A":"Considerando apenas o período de 2010 a 2015, ocorreu aumento médio de 1,00 ponto\npercentual ao ano. No entanto, ao se analisar\nos últimos cinco anos monitorados, observa-se que\nhouve queda nesse período, com redução média de 0,59 ponto percentual ao ano.","B":"Considerando apenas o período de 2010 a 2015, ocorreu aumento médio de 1,00 ponto\npercentual ao mês. No entanto, ao se analisar\nos últimos cinco anos monitorados, observa-se que\nhouve queda nesse período, com redução média de 0,59 ponto percentual ao ano.","C":"Considerando apenas o período de 2010 a 2015, ocorreu aumento médio de 1,00 ponto\npercentual ao ano. No entanto, ao se analisar\nos últimos cinco anos monitorados, observa-se que\nhouve aumento nesse período, com redução média de 0,59 ponto percentual ao ano.","D":"Considerando apenas o período de 2010 a 2015, ocorreu aumento médio de 1,00 ponto\npercentual ao ano. No entanto, ao se analisar\nos últimos cinco anos monitorados, observa-se que\nhouve queda nesse período, com redução média de 0,59 ponto percentual ao semestre."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-373587","number":"373587","sourceNumber":"373587","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A prevalência de obesidade entre adultos apresentou aumento no período analisado.","options":{"A":"No entanto, observa-se que, nos últimos cinco anos (2015 a 2019), a velocidade de evolução\naumentou, com aumento médio de 0,37 ponto\npercentual, reduziu, com aumento médio de 0,37\nponto percentual, em comparação aos primeiros anos de implantação do plano de enfrentamento\ndas Doenças Crônicas e Agravos Não Transmissíveis - DCNT (2010 a 2015), quando foi observado\num crescimento médio de 0,71 ponto percentual.","B":"No entanto, observa-se que, nos últimos cinco anos (2015 a 2019), a velocidade de evolução\nreduziu, com aumento médio de 0,37 ponto\npercentual, reduziu, com aumento médio de 0,37 ponto\npercentual, em comparação aos primeiros anos de implantação do plano de enfrentamento das\nDoenças Crônicas e Agravos Não Transmissíveis - DCNT (2010 a 2015), quando foi observado um\ndecréscimo médio de 0,71 ponto percentual.","C":"No entanto, observa-se que, nos últimos cinco anos (2015 a 2019), a velocidade de evolução\nreduziu, com aumento médio de 0,37 ponto\npercentual, reduziu, com aumento médio de 0,37 ponto\npercentual, em comparação aos primeiros anos de implantação do plano de enfrentamento das\nDoenças Crônicas e Agravos Não Transmissíveis - DCNT (2010 a 2015), quando foi observado um\ncrescimento médio de 0,71 ponto percentual.","D":"No entanto, observa-se que, nos últimos cinco anos (2015 a 2019), a velocidade de evolução\nnão reduziu, com aumento médio de 0,37 ponto\npercentual, reduziu, com aumento médio de 0,37\nponto percentual, em comparação aos primeiros anos de implantação do plano de enfrentamento\ndas Doenças Crônicas e Agravos Não Transmissíveis - DCNT (2010 a 2015), quando foi observado\num crescimento médio de 0,71 ponto percentual."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-334746","number":"334746","sourceNumber":"334746","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Define-se a Taxa de Mortalidade Pós-neonatal em determinado espaço geográfico e\nano, como o:","options":{"A":"Número de óbitos até 27 dias de vida completos, por mil nascidos vivos.","B":"Número de óbitos entre 0 e 6 dias de vida completos, por mil nascidos vivos.","C":"Número de óbitos entre 7 e 27 dias de vida completos, por mil nascidos vivos.","D":"Número de óbitos entre 28 e 364 dias de vida completos, por mil nascidos vivos."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-335102","number":"335102","sourceNumber":"335102","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Secretaria de Saúde está preocupada com o impacto da epidemia de dengue. Para\nverificar o risco de contrair dengue no ano de 2022, qual indicador deve ser acompanhado?","options":{"A":"Prevalência mensal de dengue em 2022.","B":"Incidência mensal de dengue em 2022.","C":"Letalidade da dengue em 2021.","D":"Mortalidade por dengue acumulada em 2022."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-291605","number":"291605","sourceNumber":"291605","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em um município, no último dia do ano de 2019 existiam 235 casos de diabetes, no ano\nseguinte, 30 novos casos foram diagnosticados. Neste mesmo ano, 4 pessoas que já possuíam\ndiabetes mudaram-se para esse município, sendo que do total de casos desse município, 3 foram a\nóbito. População do município 31/12/2019 ? 150.000 habitantes; 01/07/2020 ? 153.000 habitantes;\n31/12/2020 ? 156.000 habitantes. Qual a prevalência dessa doença por mil habitantes em\n31/12/2020?","options":{"A":"1,5","B":"1,53","C":"1,67","D":"1,7","E":"1,73"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-291608","number":"291608","sourceNumber":"291608","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Para o cálculo do coeficiente de mortalidade infantil pós-neonatal, em um determinado\nano e localidade é necessário saber o número\nde óbitos em...","options":{"A":"maiores de 7 dias até os menores de 28 dias; total de crianças menores de um ano.","B":"maiores de 7 dias até os menores de 28 dias; total de nascidos vivos.","C":"menores de 8 dias; total de nascidos vivos.","D":"maiores de 28 dias até os menores de um ano; total de crianças menores de um ano.","E":"maiores de 28 dias até os menores de um ano; total de nascidos vivos."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-291609","number":"291609","sourceNumber":"291609","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em um município a população de menores de um ano é de 1.932 crianças para o ano\nde 2020. Foram registrados 815 nascidos\nvivos. Nesse período ocorreram 7 óbitos fetais, 2 óbitos\nem lactentes com idade entre 3 meses e 11 meses de vida, 10 óbitos em recém-nascidos com\nmenos de sete dias de vida, e 1 óbito em recém- nascido com idade variando entre 7 e 27 dias de\nvida. Calcule o Coeficiente de Mortalidade Infantil para esse ano:","options":{"A":"15,95/1000 nascidos vivos.","B":"24,53/1000 crianças menores de um ano.","C":"14,72/1000 nascidos vivos.","D":"2,45/1000 crianças menores de um ano.","E":"12,26/1000 nascidos vivos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-304881","number":"304881","sourceNumber":"304881","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No dia 01/09/2021, o Brasil apresentava aproximadamente 20.800.000 de casos\nconfirmados e 580.000 óbitos por COVID-19.\nConsiderando uma população total de 210 milhões de\npessoas, qual era a taxa de letalidade aproximada pela doença à época?","options":{"A":"0,2%.","B":"2,8%.","C":"9,9%.","D":"35,8%."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-260667","number":"260667","sourceNumber":"260667","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Taxa de Mortalidade Específica, por causas selecionadas, é o resultado encontrado\npela divisão do número de óbitos pela causa\nespecífica em um determinado ano e período pelo(a),","options":{"A":"população total de indivíduos acometidos pela mesma causa, no mesmo local e período, dividido\npor uma base referencial para a população\nexposta.","B":"total de óbitos por todas as causas, no mesmo local e período, multiplicado por uma base\nreferencial para a população exposta.","C":"população total calculada para o meio do ano, no mesmo local e período, dividido por uma base\nreferencial para a população exposta.","D":"total de óbitos calculados no meio do ano, no mesmo local e período, multiplicado por uma base\nreferencial para a população exposta.","E":"população total do mesmo local e período, multiplicado por uma base referencial para a\npopulação exposta."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-260671","number":"260671","sourceNumber":"260671","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"É considerado um indicador que avalia mortalidade proporcional:","options":{"A":"Incidência por causas específicas.","B":"Coeficiente de Mortalidade Infantil.","C":"Índice de Swaroop-Uemura.","D":"Coeficiente de Prevalência.","E":"Taxa de Mortalidade Geral."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-287363","number":"287363","sourceNumber":"287363","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A razão entre o número de mortes por determinada doença, em uma área e período\ndefinidos, e o número de pessoas diagnosticadas por esta mesma doença, na mesma área e\nperíodo, multiplicado por 100, define o conceito de taxa de:","options":{"A":"Mortalidade.","B":"Letalidade.","C":"Mortalidade proporcional.","D":"Ataque."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-283938","number":"283938","sourceNumber":"283938","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As mudanças no modelo de desenvolvimento, no estilo de vida e no comportamento\nassumem importância para a Saúde Pública, estando\nos pobres, em desvantagem em relação aos\nricos quanto ao risco concomitante do perfil de morbimortalidade do atraso (doenças infecciosas) e\nda modernidade (doenças cardiovasculares e neoplasias). No Brasil, a particularidade traz ao\nconceito, para consideração, importantes componentes socioeconômicos, culturais, demográficos e\nambientais. A qual conceito essa afirmativa acima de refere?","options":{"A":"Transição demográfica.","B":"Transição tecnológica.","C":"Transição epidemiológica.","D":"Modelos de atenção à saúde.","E":"Programa de Saúde da Família."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-283939","number":"283939","sourceNumber":"283939","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Segundo a Organização Mundial da Saúde, ao se considerar a epidemiologia do\nenvelhecimento, deve-se analisar a saúde dos idosos considerando alguns aspectos. Sendo assim,\nassinale V, se verdadeiras, ou F, se falsas para as assertivas a seguir. ( ) O gênero. ( ) A\ncultura. ( )\nOs determinantes da saúde. ( ) O ambiente físico. A ordem correta de preenchimento dos\nparênteses, de cima para baixo, é:","options":{"A":"V - V - V - F.","B":"V - F - F - F.","C":"F - F - V - V.","D":"V - V - V - V.","E":"F - V - F - V."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-283940","number":"283940","sourceNumber":"283940","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a qualidade de um indicador de saúde, analise as assertivas abaixo sobre as\npropriedades dos seus componentes: I. São utilizados em sua formulação (frequência de casos,\ntamanho da população em risco). II. Dependem da precisão dos sistemas de informação\nempregados (registro, coleta, transmissão dos dados). III. O grau de excelência de um indicador\ndeve ser definido por sua validade (capacidade de medir o que se pretende). IV. O grau de\nexcelência de um indicador deve ser definido por sua confiabilidade (reproduzir os mesmos\nresultados quando aplicado em condições diferentes). Quais estão corretas?","options":{"A":"Apenas I e III.","B":"Apenas II e IV.","C":"Apenas III e IV.","D":"Apenas I, II e III.","E":"I, II, III e IV."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-232107","number":"232107","sourceNumber":"232107","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Para se determinar a incidência de determinada doença em determinado local, em um\ndeterminado ano, é necessário saber:","options":{"A":"Número de casos novos em determinado período e número total de pessoas doentes em\ndeterminado período.","B":"Número de casos novos em determinado período e número total de casos em determinado\nperíodo.","C":"Número total de casos da doença em determinado período e número de pessoas expostas ao\nrisco em determinado período.","D":"Número de casos novos em determinado período e número de pessoas expostas ao risco em\ndeterminado período.","E":"Número total de casos da doença em determinado período e número total de pessoas doentes\nem determinado período."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-232109","number":"232109","sourceNumber":"232109","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A percentagem de pessoas que morreram com 50 anos ou mais em relação ao total de\nóbitos ocorridos em uma determinada população é medida por qual dos indicadores abaixo?","options":{"A":"Índice de Mortalidade Geral.","B":"Coeficiente de Ataque Secundário.","C":"Índice de Swaroop & Uemura.","D":"Índice de Mortalidade por causa específica.","E":"Quantificação de Guedes."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-242993","number":"242993","sourceNumber":"242993","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O sistema de informação em saúde que permite obter informações sobre produção e\ncomposição das equipes de saúde e as condições de moradia dos pacientes é o:","options":{"A":"Sistema de Monitoramento de Indicadores da Estratégia Saúde da Família (MONITOR ESF).","B":"Departamento de Informática do Sistema Único de Saúde (DATASUS).","C":"Sistema de Informação dos Agentes Comunitários de Saúde (SIPACS).","D":"Sistema de Informação da Atenção Básica (SIAB).","E":"Sistema de Informação Urgência e Emergência (SIUE)."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-246735","number":"246735","sourceNumber":"246735","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um novo tratamento para uma determinada doença foi desenvolvido. Este tratamento\nevita a morte do paciente, mas não cura\ndefinitivamente a doença. Portanto, espera-se que a:","options":{"A":"prevalência da doença diminuirá.","B":"prevalência da doença aumentará.","C":"incidência da doença aumentará.","D":"incidência da doença diminuirá.","E":"incidência e a prevalência da doença diminuirão."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-255648","number":"255648","sourceNumber":"255648","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Lind & Singer (1986) estudaram a qualidade da tomografia computadorizada para o\ndiagnóstico de metástase de carcinoma de fígado. Um total de 150 pacientes foram submetidos a\ndois exames: a tomografia computadorizada e a laparotomia. A laparotomia é o padrão ouro\n(classifica o paciente sem erro) para este caso. A tabela a seguir resume os resultados obtidos pelo\nestudo. José está cuidando de um senhor que tem chances de estar com metástase hepática e\nqueria saber a respeito das razões de probabilidades (likelihood ratio) desse estudo em particular.\nPara iniciar essa avaliação, necessitava do valor da probabilidade pré-teste, ou seja, da\nprevalência\nda anemia ferropriva na população estudada nesse estudo. Esse valor é? MARQUE A CORRETA.","options":{"A":"44%","B":"34%","C":"55%","D":"10 %"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-227277","number":"227277","sourceNumber":"227277","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma determinada região com uma população de 105.000 pessoas, ocorria uma\ndoença incurável e não fatal. Em uma amostra\nconstituída por 1% da população, foram detectadas\n50 pessoas com a doença. Esta amostra foi acompanhada durante cinco anos, tendo a doença sido\ndesenvolvida por mais 50 pessoas neste período. Assinale a alternativa que indica corretamente a\nprevalência e a incidência da doença nesta amostra populacional:","options":{"A":"4,7% e 50 por 1.000 em cinco anos.","B":"5% e 95 por 1.000 em cinco anos.","C":"4,7% e 95 por 1.000 em cinco anos.","D":"5% e 50 por 1.000 em cinco anos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-227279","number":"227279","sourceNumber":"227279","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A compreensão do comportamento das doenças na população é fundamental para a\ndeterminação das medidas de controle. Uma doença é dita endêmica quando, no decorrer de um\nlargo período histórico, acomete sistematicamente grupos humanos distribuídos em espaços\ndelimitados e caracterizados. Se, entretanto, ela apresenta uma elevação progressivamente\ncrescente com tendência a acometer um grande número de pessoas ao mesmo tempo, é\ndenominada epidemia. Algumas doenças endêmicas podem tornar-se epidêmicas. A observação\nde seu comportamento ao longo do tempo é a essência da ação de vigilância em saúde. A respeito\nda avaliação do comportamento da doença em um determinado ano, é CORRETO afirmar que\ndeve ser verificada:","options":{"A":"A incidência mensal média, que representa a média da incidência em todos os meses do ano\nanterior.","B":"A frequência máxima esperada, que representa a máxima incidência mensal no ano anterior.","C":"O limite superior da incidência normal, que é a média das incidências anuais máximas nos cinco\nanos anteriores.","D":"A distribuição da incidência mensal média, que representa a média da incidência para cada mês\ndo ano nos dez anos anteriores."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-255654","number":"255654","sourceNumber":"255654","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Érica é pediatra do Hospital Regional e é convidada pela Secretaria Municipal de Saúde\na participar do Comitê de Mortalidade Materno\nInfantil de seu município, ajudando na quantificação\ndos indicadores básicos de saúde e elaborando estratégias para melhoria desses indicadores. Em\nrelação à mortalidade materna, MARQUE A CORRETA:","options":{"A":"Está sujeita a distorções, como a subnotificação das causas do óbito e o sub-registro das\ndeclarações de óbitos.","B":"A morte materna é definida como a morte de uma mulher durante a gestação ou até 30 dias\napós o término da gestação.","C":"No cálculo de razão de mortalidade materna, o numerador é constituído pelo número de óbitos\nmaternos relacionados com a gestação, parto e puerpério em um ano, dividido pelo total de óbitos\nde mulheres do mesmo ano e multiplicado por 100.000.","D":"As mortes maternas indiretas, resultantes de doenças que existiam antes da gestação ou que se\ndesenvolveram durante a gravidez, não são incluídas no cálculo da razão da mortalidade materna."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-227281","number":"227281","sourceNumber":"227281","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A epidemiologia das doenças crônicas não transmissíveis parece particularmente\nsensível ao modelo denominado por Laframboise\n(1973) como Campo da Saúde, que reconhece a\n\"multicausalidade\" na determinação da saúde ou da doença. Entre as abaixo, assinale a alternativa\nque define corretamente um elemento deste modelo:","options":{"A":"A biologia humana envolve o sistema imune em seus componentes inatos e adaptativos.","B":"O ambiente envolve as relações dos indivíduos com o sistema de saúde e as condições de\nassistência.","C":"O estilo de vida envolve a interação social que está inteiramente sujeita ao controle do\nindivíduo.","D":"A organização da atenção à saúde envolve disponibilidade, quantidade e qualidade dos recursos\ndestinados aos cuidados."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-234444","number":"234444","sourceNumber":"234444","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os indicadores de mortalidade infantil e seus desdobramentos permitem a avaliação da\nqualidade do pré-natal, da assistência ao parto e também do ambiente em que a criança está\ncrescendo. Assinale a alternativa que apresenta o indicador que MELHOR avalia as condições do\nambiente em que a criança está crescendo.","options":{"A":"Mortalidade fetal.","B":"Mortalidade perinatal.","C":"Mortalidade pós neonatal.","D":"Mortalidade infantil."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-246392","number":"246392","sourceNumber":"246392","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O município X apresentou 50 novos casos de tuberculose no ano de 2018. Com base\nnesses dados é possível afirmar que:","options":{"A":"Houve um surto epidêmico de tuberculose no município X","B":"A tuberculose apresenta características de doença emergente no município X","C":"A prevalência de casos de tuberculose no município é igual a 100","D":"Houve uma incidência de 100 casos de tuberculose"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-227118","number":"227118","sourceNumber":"227118","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considere uma população de 100.000 pessoas, das quais 40 tem fibrose cística, e após\n01 ano, 30 das 40 pessoas morrem da doença.\nAssinale a alternativa que apresenta\nCORRETAMENTE a taxa de letalidade da fibrose cística nessa população.","options":{"A":"75%.","B":"0,03%.","C":"3%.","D":"0,0075%."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-227309","number":"227309","sourceNumber":"227309","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O câncer na criança difere daquele que ocorre no indivíduo adulto em decorrência do\ntipo de célula progenitora envolvido e dos mecanismos de transformação maligna. No câncer\ninfantil é correto afirmar:","options":{"A":"A idade é um fator importante para nortear a linha de raciocínio diagnóstico. Tumores ou massas\nque são detectados no período neonatal são\nquase sempre de natureza maligna.","B":"Os cânceres pediátricos mais frequentes são os tumores de Wilms, neuroblastoma e em terceiro\nlugar as leucemias.","C":"A presença de dor nos membros, associada a mais de um parâmetro alterado no hemograma,\nsugere neoplasia maligna, e não doença\nreumatoide, mesmo na ausência de blastos no sangue\nperiférico.","D":"A síndrome da veia cava superior (SVCS) representa um conjunto de sinais e sintomas\ndecorrentes de compressão, obstrução ou\ntrombose da veia cava superior. Na faixa etária\npediátrica a causa primária mais comum da SVCS é o câncer, sendo o sarcoma, o câncer de\ntireoide e o neuroblastoma os mais frequentes."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-215104","number":"215104","sourceNumber":"215104","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que completa a frase corretamente: ?No caso de dúvida sobre\ndeterminada tendência clínica de uma comunidade, podemos elaborar um diagnóstico situacional\ncom a equipe multidisciplinar, que colherá dos prontuários e sites informativos\n\ne através de entrevistas com moradores daquele local. Podemos usar a\n\npara selecionar informantes chaves. Ao concluirmos o diagnóstico deve-se\nfazer .?","options":{"A":"Dados primários ? dados secundários ? bola de neve ? uma ação comunitária.","B":"Dados secundários ? dados primários ? seleção espontânea ? planejamento ascendente.","C":"Dados secundários ? dados primários ? bola de neve ? uma ação comunitária.","D":"Dados secundários ? dados primários ? bola de neve ? planejamento ascendente.","E":"Dados primários ? dados primários ? seleção espontânea ? um planejamento ascendente."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-215180","number":"215180","sourceNumber":"215180","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Num município do interior do Estado do Espírito Santo, foi efetuada a avaliação da\nmortalidade proporcional, nas diferentes faixas etárias. Aplicando-se os resultados, utilizou-se o\nregistro através da curva de Nelson Moraes, conforme apresentado a seguir: Procedendo-se a\navaliação do gráfico, conclui-se que as condições de vida da população estudada são:","options":{"A":"Muito baixas.","B":"Baixas","C":"Regulares.","D":"Elevadas.","E":"Muito elevadas."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-199532","number":"199532","sourceNumber":"199532","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"?A mortalidade infantil em 2016 interrompeu décadas de queda de mortes de bebês no\nBrasil, mostram dados do Ministério da Saúde. Pela 1ª vez desde 1990, o país apresentou alta na\ntaxa: foram 14 mortes a cada mil nascidos em 2016; um aumento de 4,8% em relação a 2015,\nquando 13,3 mortes (a cada mil) foram registradas.\" Disponível em:\nhttps://g1.globo.com/bemestar/noticia/brasil-registraalta-de-mortalidade-infantil-apos-decadas-de-qu\neda.ghtml. Acesso em 16 julho 2018. Uma grande proporção desses óbitos ocorre no período\nprecoce (mortalidade neonatal precoce). Sobre a taxa de mortalidade infantil precoce, assinale a\nalternativa INCORRETA:","options":{"A":"A taxa se apresenta pelo número de óbitos de 0 a 6 dias de vida completos, por mil nascidos\nvivos, na população residente em determinado\nespaço geográfico, no ano considerado.","B":"A taxa reflete, de maneira geral, as condições socioeconômicas e de saúde da mãe, bem como\na adequação da assistência pré-natal, ao parto e\nao recém-nascido","C":"A taxa é muito precisa, pois necessita de análise da declaração de óbito, que é sempre\npreenchida após criteriosa avaliação técnica","D":"Os Comitês de Prevenção a Óbitos Infantil e Fetal realizam a investigação dos óbitos, sendo a\nentrevista domiciliar uma etapa da vigilância desses óbitos."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-174377","number":"174377","sourceNumber":"174377","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual o indicador que trata da relação entre o número de casos novos e antigos de uma\ndeterminada doença em relação à população com risco de adoecer?","options":{"A":"Esperança de vida.","B":"Letalidade.","C":"Mortalidade.","D":"Morbidade.","E":"Incidência."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-174357","number":"174357","sourceNumber":"174357","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma comunidade, o total de óbitos em menores de um ano foi de 30 indivíduos para\num total de 600 nascidos vivos, entre mães\nresidentes, em determinado local e período, e estão\nassim distribuídos por faixa etária: de 0 (zero) a 3 dias ? 1; menores de 7 dias ? 2; menores de 14\ndias ? 4; com 7 a 27 dias ? 8; com 28 dias ou mais ? 20. A partir dessas informações, qual a taxa\nde mortalidade infantil neonatal?","options":{"A":"1,66.","B":"16,66.","C":"3,33.","D":"13,33.","E":"33,33."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-174352","number":"174352","sourceNumber":"174352","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em um município no interior do Estado detectou-se que houve queda na prevalência de\num determinado agravo, no entanto, a incidência\nmanteve-se constante, sem alterações. Esse fato\nsignifica que houve","options":{"A":"Cronicidade das doenças ao longo do tempo.","B":"Diminuição no número de óbitos da população observada.","C":"Incremento no sistema de prevenção primária da doença.","D":"Melhora no processo de cura do agravo junto a população.","E":"Busca ativa de casos novos na população adscrita."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-188012","number":"188012","sourceNumber":"188012","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação aos Indicadores de Saúde é correto afirmar:","options":{"A":"O coeficiente de mortalidade infantil é a probabilidade entre 100 crianças nascidas vivas não\nconcluírem o primeiro ano de vida.","B":"A incidência das doenças é medida a partir da identificação dos casos novos e antigos em um\ndeterminado tempo e espaço.","C":"As Curvas de Mortalidade Proporcional de Nelson de Moraes medem a severidade da doença.","D":"Quanto mais elevado for o Índice de Swaroop & Uemura do país, melhores serão suas\ncondições sociais, econômicas e de saúde.","E":"Os anos potenciais de vida perdidos expressa o número médio de anos que ainda resta para ser\nvivido."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-172839","number":"172839","sourceNumber":"172839","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à saúde da criança, um indicador de grande importância é a mortalidade\ninfantil. Este indicador tem apresentado muitas\nmudanças ao longo do tempo, entre as quais é\ncorreto afirmar:","options":{"A":"A queda nas taxas de mortalidade infantil, principalmente do componente pós-neonatal, é\natribuída ao aumento da fecundidade da população.","B":"No período compreendido entre 1990 e 2000, a queda nas taxas de mortalidade infantil\nacompanhou o contexto econômico favorável.","C":"A implantação do Programa de Saúde da Família em 1994 interrompeu a queda da mortalidade\ninfantil, porque resultou em má assistência à\nsaúde.","D":"A queda da mortalidade infantil está associada ao momento da escolaridade materna."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-172841","number":"172841","sourceNumber":"172841","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Brasil tem sofrido transformações em seu perfil de mortalidade e morbidade nas\núltimas décadas, com ênfase no predomínio das\ndoenças crônicas não transmissíveis. Em relação\nao impacto demográfico e social destas doenças, assinale a alternativa correta:","options":{"A":"A epidemia de doenças crônicas não transmissíveis tem afetado mais as pessoas de baixa\nrenda, que são mais expostas ao risco e têm menos acesso aos serviços de saúde.","B":"Grupos étnicos e raciais menos privilegiados, como a população indígena, têm tido menor\nparticipação na carga de doenças crônicas não transmissíveis.","C":"O tratamento para diabetes, câncer, doenças do aparelho circulatório e doença respiratória\ncrônica é de mais baixo custo, o que facilita o\nequilíbrio econômico das parcelas de baixa renda.","D":"A existência do Sistema Único de Saúde no Brasil permite desonerar a população em relação ao\ncusto da abordagem das doenças crônicas não transmissíveis."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-172835","number":"172835","sourceNumber":"172835","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O aumento no número de indivíduos idosos faz com que haja necessidade de\nimplementação de políticas que asssegurem o envelhecimento com qualidade de vida. Para tanto,\ndiversos indicadores são utilizados para estabelecer os parâmetros destas políticas. Sobre estes\nindicadores, assinale a alternativa correta:","options":{"A":"O número de pessoas idosas é um indicador que reflete o estágio de desenvolvimento de uma\nsociedade.","B":"O indicador constituído pela expectativa de vida aos 60 anos ou mais de idade, no Brasil, traz\nvantagem para os homens em relação às mulheres.","C":"O índice de envelhecimento é o número de pessoas com menos de 15 anos de idade para cada\n100 pessoas com 65 ou mais anos de idade.","D":"A razão de dependência é a relação entre o segmento etário potencialmente produtivo, no\ndenominador, e aquele dependente, no denominador."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-155471","number":"155471","sourceNumber":"155471","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma cidade na África, a taxa de letalidade por sarampo foi de 10% no ano de 1979.\nDurante esse ano ocorreram 50 óbitos da doença. Qual o número de casos de sarampo nessa\ncomunidade, em 1979?","options":{"A":"450.","B":"100.","C":"500.","D":"55.","E":"50."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-162542","number":"162542","sourceNumber":"162542","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa correta referente ao coeficiente de mortalidade infantil.","options":{"A":"Trata-se de um indicador atualmente pouco valorizado.","B":"Mede o risco de morte para crianças menores de um ano.","C":"É um coeficiente totalmente confiável em qualquer população.","D":"É um indicador inadequado às desigualdades regionais.","E":"É um indicador independente das condições socioeconômicas."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-162546","number":"162546","sourceNumber":"162546","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A busca de alternativas para a gerência de estabelecimentos de saúde tem como\nobjetivo(s):","options":{"A":"Uma opção para incorporar valores da iniciativa privada.","B":"Autonomia, flexibilidade e eficiência.","C":"Exclusivamente a diminuição de custos.","D":"Exclusivamente a democratização das decisões.","E":"A criação de fórum para a participação popular."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-148557","number":"148557","sourceNumber":"148557","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a epidemiologia da saúde da criança no Brasil, assinale a alternativa correta:","options":{"A":"Desde de 1990, a região com indicadores sociais mais desfavoráveis do Brasil - o Nordeste -\napresentou a maior redução anual de mortalidade infantil.","B":"Os maiores decréscimos na mortalidade infantil por causa específica, no Brasil, foram\nobservados para parasitoses e intoxicações exógenas.","C":"A mortalidade neonatal, ao contrário, apresentou aumento acentuado nos últimos dez anos,\ntraduzindo más condições de atenção pré-natal.","D":"A redução da mortalidade infantil foi favorecida pelo predomínio das abordagens de ordem\ncurativa em relação aquelas preventivas.","E":"A prematuridade está dissociada da mortalidade infantil no Brasil, ambas variando de forma\nindependente."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-148573","number":"148573","sourceNumber":"148573","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre o envelhecimento populacional, assinale a alternativa correta:","options":{"A":"Entre 1970 e 2010, a proporção de pessoas com 60 anos ou mais no Brasil duplicou.","B":"Por volta de 2030, a tendência deve inverte-se, traduzida pela superação da proporção de\ncrianças e adolescentes em relação aos idosos.","C":"A maior parte da população idosa do país se encontra na faixa etária de 75 anos ou mais.","D":"A população idosa brasileira é constituída em sua maioria por homens em virtude do seu ritmo\nde envelhecimento mais lento.","E":"A maior parte das mulheres idosas vive com companheiro, tem experiência de trabalho no\nmercado formal e é escolarizada."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-137830","number":"137830","sourceNumber":"137830","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A taxa que expressa a frequência de casos novos de uma determinada doença ou\nproblema de saúde, durante um período definido, em uma população sob o risco de desenvolver a\ndoença, chama-se:","options":{"A":"Epidemia.","B":"Surto.","C":"Endemia.","D":"Prevalência.","E":"Coeficiente."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-137841","number":"137841","sourceNumber":"137841","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A infecção congênita que o ministério da saúde considera como um evento sentinela é:","options":{"A":"Varicela.","B":"Citomegalovirose.","C":"Toxoplasmose.","D":"Adenovirose.","E":"Sífilis."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-102770","number":"102770","sourceNumber":"102770","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Entre os fatores que podem aumentar a prevalência de uma doença, estão, EXCETO:","options":{"A":"Maior duração.","B":"Maior letalidade.","C":"Maior incidência.","D":"Imigração de casos."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-102739","number":"102739","sourceNumber":"102739","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação aos indicadores de saúde, assinale a alternativa CORRETA.","options":{"A":"Anos de Vida Perdidos (AVP) - calcula-se a partir do número de mortes de cada idade\nmultiplicado pela expectativa de vida global padronizada por idade em que a morte ocorreu.","B":"Anos Perdidos por Incapacidade (API) - calcula-se diminuindo a idade de início da doença da\nidade de expectativa de vida global daquela população.","C":"Mortalidade proporcional - total de óbitos por faixa etária dividido pelo total de óbitos no\nmesmo\nperíodo.","D":"Taxa de mortalidade materna - total de óbitos de gestantes ou puérperas dividido pelo total de\nóbitos de mulheres em idade fértil no mesmo período."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-111573","number":"111573","sourceNumber":"111573","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A queda da fecundidade ocorrida no Brasil nas últimas décadas é bem mais acelerada\ndo que a\n\nobservada nos países desenvolvidos. Esse indicador (coeficiente de fecundidade), para uma\ndeterminada área e período, tem como denominador","options":{"A":"o número de nascidos vivos.","B":"o número total de nascidos.","C":"a população feminina total.","D":"a população feminina de 15 a 49 anos de idade.","E":"a população total."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-111601","number":"111601","sourceNumber":"111601","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em estudo realizado no município, verificou-se que o Índice de Swaroop & Uemura era\nigual a\n\n35%. Isto sugere que devem ser priorizadas medidas para:","options":{"A":"combater doenças relacionadas ao uso de tabaco.","B":"educar a população quanto aos riscos da automedicação.","C":"diminuir a incidência de doenças ocupacionais.","D":"diminuir a mortalidade infantil.","E":"diminuir a poluição ambiental."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-106388","number":"106388","sourceNumber":"106388","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual dos seguintes itens é a medida padrão para determinar o impacto de uma\ncondição de saúde em uma população?","options":{"A":"Anos de vida ajustados por incapacidade.","B":"Mortalidade infantil.","C":"Expectativa de vida.","D":"Razão de mortalidade padronizada.","E":"Anos de vida perdidos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-101012","number":"101012","sourceNumber":"101012","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à Taxa de Mortalidade Infantil (TMI), marque a alternativa correta.","options":{"A":"O declínio da TMI nas últimas décadas foi expressivo, reduzindo a níveis insignificantes as\ndiferenças entre as regiões do país, visto a\nmelhoria universal das condições socioeconômicas e de\nacesso a serviços de saúde.","B":"É geralmente classificada em alta (50 ou mais por 1.000 nascidos vivos), média (20-49 por 1.000\nnascidos vivos) e baixa (menos de 20 por 1.000 nascidos vivos), em função da proximidade ou\ndistância de valores já alcançados em sociedades mais desenvolvidas, sendo que atualmente o\nBrasil apresenta uma TMI baixa.","C":"Taxas de mortalidade infantil reduzidas indicam boas condições de vida da população de uma\nmaneira global e homogênea entre grupos sociais.","D":"O cálculo direto da taxa exige correções da subenumeração de óbitos infantis e de nascidos\nvivos, especialmente nas regiões Sudeste e Sul,\ndevido terem os dados de mais baixa qualidade do\npaís.","E":"A mortalidade infantil compreende o total da soma dos óbitos ocorridos do período neonatal\nprecoce até os dois anos de idade."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-101007","number":"101007","sourceNumber":"101007","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre os processos de transição epidemiológica, incluindo as particularidades\nbrasileiras, considere as seguintes afirmações:\nI. O processo de transição epidemiológica consiste\nna substituição das doenças transmissíveis por doenças não-transmissíveis e causas externas; no\ndeslocamento da carga de morbimortalidade dos grupos mais jovens para os mais idosos e na\ntransfomação de uma situação em que predomina a mortalidade para outra na qual a morbidade é\ndominante;II. O conceito de transição epidemiológica, apesar de sua evidente utilidade, tem\nmerecido críticas pelo fato de a transformação dos padrões de saúde não obedecer aos mesmos\nparâmetros na sequência, intensidade e velocidade, em diferentes regiões, bem como enfatizar a\ntecnologia médica como principal alternativa interveniente no curso da transição, desconsiderando\no papel que as variáveis econômicas e sociais desempenham neste processo;III. No Brasil, a\ntransição epidemiológica ocorre de acordo com o modelo experimentado pela maioria dos países\nindustrializados e por alguns países latino-americanos mais desenvolvidos, caracterizada por uma\nevolução rápida, com etapas muito bem definidas e sequenciais, onde há evidente substituição das\ndoenças transmissíveis pelas crônicas, sendo homogênea em todo o país, Quais afirmações estão\ncorretas?","options":{"A":"Apenas I.","B":"Apenas I e II.","C":"Apenas II e III.","D":"Apenas I e III,","E":"I, II e III."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-101044","number":"101044","sourceNumber":"101044","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A saúde coletiva se utiliza das medidas de saúde para planejar intervenções estruturais\npara promoção da vida. A respeito dessas medidas, é\ncorreto afirmar:","options":{"A":"Coeficientes são medidas primárias que serão usadas para composição das taxas, que são\nmedidas secundárias.","B":"Índice é o termo genérico mais abrangente e apropiado para referir-se a todos os descritores da\nvida e da saúde.","C":"Indicadores são medidas meramente matemáticas e desvinculadas de qualquer conotação de\nmodificação da realidade.","D":"Por sua natureza objetiva, os índices não dependem da natureza da observação.","E":"Cada medida tem uma função aplicável em uma situação específica, configurando sua\nsingularidade."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-88923","number":"88923","sourceNumber":"88923","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à mortalidade, analise as afirmações abaixo e, em seguida, assinale o item\ncorreto.I) O Ministério da Saúde adotou uma Declaração de óbito padronizada para todo o Brasil. II)\nA causa básica do óbito deve ser escrita em primeiro lugar, na parte I da Declaração de Óbito. III)\nA\ninformação recolhida por Censos e Pesquisas Nacionais pode ser utilizada para estimar indicadores\nde mortalidade. IV) Quanto mais elevado o índice de Swaroop & Uemura tanto piores serão as\ncondições de saúde e de vida de uma população.Assinale a alternativa correta:","options":{"A":"II","B":"I e II","C":"I e III","D":"II e IV","E":"I, II e IV"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-77497","number":"77497","sourceNumber":"77497","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Brasil encontra-se em um processo acelerado de queda nas taxas de fecundidade,\nde modo que a população cresce cada vez mais\nlentamente. Este dado significa que no País:","options":{"A":"Haverá problemas de carência de população no ano 2020.","B":"Haverá condições para uma melhor distribuição da renda.","C":"Acabará a necessidade de melhoria dos serviços de assistência ao parto.","D":"Haverá mudança nos padrões de morbidade, com aumento das doenças crônicas.","E":"Nenhuma das anteriores."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-77561","number":"77561","sourceNumber":"77561","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os coeficientes de incidência são geralmente confundidos com os coeficientes de\nprevalência. Eles são semelhantes, mas a diferença é importante. Qual das afirmativas a seguir\nestá incorreta?","options":{"A":"Ambos são tipos de coeficientes de morbidade.","B":"O numerador do coeficiente de prevalência inclui todas as pessoas doentes de uma causa\nespecífica durante um intervalo de tempo específico ou num determinado momento.","C":"O coeficiente de prevalência não inclui doenças que começaram anteriormente ao intervalo de\ntempo específico ou momento estudado.","D":"Um coeficiente de incidência é uma medida de frequência de ocorrência de casos novos de uma\ndoença em uma população definida durante um\nintervalo de tempo específico.","E":"O denominador do coeficiente de incidência é a população exposta ao risco durante um intervalo\nde tempo, em uma área específica."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59027","number":"59027","sourceNumber":"59027","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação ao controle de doenças no Brasil, é incorreto afirmar:","options":{"A":"As doenças crônicas não transmissíveis são as principais fontes da carga de doença no Brasil, e\npolíticas importantes para sua prevenção e controle têm sido implementadas.","B":"Nos últimos anos, a maioria das mortes no Brasil foram atribuídas às doenças crônicas não\ntransmissíveis (doenças cardiovasculares, doenças respiratórias crônicas, diabetes, câncer e\noutras, inclusive doenças renais).","C":"Crescimento da renda, industrialização e mecanização da produção, urbanização, maior acesso\na alimentos em geral, incluindo os processados, e\nglobalização de hábitos não saudáveis\nproduziram rápida transição nutricional, expondo a população cada vez mais ao risco de doenças\ncrônicas.","D":"O controle de doenças como a cólera, doença de Chagas e aquelas que podem ser prevenidas\npela vacinação têm obtido êxito por meio de\npolíticas públicas eficientes e de esforços\nconcentrados dos diferentes níveis de governo e da sociedade civil.","E":"As doenças que tiveram sucesso no controle (tal como a dengue e a leishmaniose visceral) são\ntransmitidas por vetores com perfis epidemiológicos variados e que não encontram dificuldades de\ntratamento."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59043","number":"59043","sourceNumber":"59043","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação as políticas públicas para controle das doenças infecciosas é incorreto\nafirmar:","options":{"A":"O Brasil está passando por um rápido e, por vezes, desorganizado processo de urbanização.\n\nNesse contexto, programas de transferência de renda para as populações mais pobres, o Sistema\nÚnico de Saúde (SUS) e outras melhorias\nsociais e ambientais (como saneamento e educação) são\ne continuarão a ser cruciais para os esforços de controle de doenças infecciosas.","B":"Iniciativas de saúde pública, que incluem acesso universal e gratuito à vacinação, acesso ao\ntratamento e cuidados primários de saúde, que tiveram sucesso total ou parcial no controle das\ndoenças preveníveis por vacinação, na diarreia, nas infecções respiratórias, no HIV/AIDS e na\ntuberculose - políticas equitativas -, devem ser apoiadas e reforçadas, em face de desafios\nexistentes e renovados, tais como a menor do que ideal adesão aos tratamentos, à emergência e à\ntransmissão de patógenos resistentes aos medicamentos.","C":"A distribuição das causas de morte por doenças infecciosas permanece em um padrão mais\npróximo do observado em países subdesenvolvidos, especialmente no que se refere à\npredominância de pneumonia em crianças e adolescentes.","D":"O controle de vetores de doenças em áreas de rápida urbanização e de habitações de baixa\nqualidade não pode ser alcançado somente com ações de saúde. Esses esforços devem ser\nplenamente integrados a políticas amplas que incorporem a mobilização da sociedade, educação\nambiental e da saúde, melhorias em habitação e saneamento e esforços para evitar mais\ndesmatamento.","E":"A pesquisa científica no Brasil tem crescido intensamente nos últimos dez anos, com um avanço\ncélere e sustentado da investigação biomédica, clínica e epidemiológica, em questões que\nenvolvem prevenção e tratamento de doenças infecciosas. Tais realizações acadêmicas devem ser\ntraduzidas em produtos e políticas de modo que possam traduzir-se em benefícios para toda a\npopulação brasileira."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59053","number":"59053","sourceNumber":"59053","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Você vai trabalhar em uma comunidade e necessita conhecer os principais problemas\nde saúde dessa população. Quais indicadores de\nmorbidade você utilizará para as doenças de\ncurta duração (como sarampo, difteria, meningite) e para as de longa duração (como diabetes\nmellitus, hipertensão arterial, hanseníase), respectivamente?","options":{"A":"Incidência, prevalência.","B":"Incidência, mortalidade.","C":"Prevalência, incidência.","D":"Prevalência, letalidade.","E":"Letalidade, sobrevida."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59059","number":"59059","sourceNumber":"59059","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um exame de detecção em massa (rastreamento) de 1.000 mulheres de 45-54 anos\nidentificou 20 casos de carcinoma de mama. Durante o período de 10 anos de seguimento outras\n60 mulheres tiveram diagnóstico de carcinoma de mama. Dessas informações podem ser obtidas\nas seguintes medidas de frequência, respectivamente:","options":{"A":"Taxa de incidência e taxa de prevalência.","B":"Taxa de prevalência e taxa de incidência.","C":"Taxa de prevalência e taxa de letalidade.","D":"Taxa de letalidade e taxa de incidência.","E":"Taxa de incidência e taxa de sobrevida."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59075","number":"59075","sourceNumber":"59075","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual dos indicadores de mortalidade abaixo listados tem como objetivo avaliar o nível\nde saúde em grupos populacionais, de acordo com a forma da curva apresentada, que relaciona\nmortalidade com os seguintes estratos de faixa etária: < 1 ano, 1 a 4 anos, 5 a 19 anos, 20 a 49\nanos e ? a 50 anos?","options":{"A":"Coeficiente de mortalidade geral.","B":"Índice de Nelson Moraes.","C":"Índice de Swaroop-Uemura.","D":"Coeficiente de Mortalidade por causa.","E":"Coeficiente de mortalidade padronizado."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59077","number":"59077","sourceNumber":"59077","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A incidência-densidade é uma medida de frequência expressa pelo número de casos:","options":{"A":"Casos antigos, dividido pelo número total de pessoas-ano em risco.","B":"Casos novos, dividido pela densidade demográfica da área estudada.","C":"Casos novos, dividido pelo número total de pessoas-ano em risco.","D":"Casos novos e antigos, dividido pela população no meio do período em estudo.","E":"Casos novos, dividido pela população no meio do período em estudo."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-59036","number":"59036","sourceNumber":"59036","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a taxa de mortalidade infantil, é CORRETO afirmar:","options":{"A":"É uma estimativa do risco de morte a que está exposta uma população de nascidos vivos em\numa determinada área e período desde o seu\nprimeiro até o seu sétimo aniversário.","B":"É uma medida do tipo proporção que estabelece uma prevalência de morte entre nascidos vivos\nantes de completar seu primeiro ano de vida em determinada área e período.","C":"Na prática de saúde pública, os óbitos contidos no numerador se referem a coortes de dois anos\ncalendários sucessivos, permitindo que a taxa seja uma aproximação da medida do risco de morte.","D":"O risco de morte é constante ao longo do primeiro ano de vida, o que leva à constituição de uma\ntaxa única homogênea, caracterizando diretamente tal risco.","E":"As diversas falhas relacionadas a sua aplicação como indicador de saúde tornaram-na pouco\nvalorizada, sob a crítica de que não teria sensibilidade suficiente para figurar como indicador."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-43968","number":"43968","sourceNumber":"43968","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quantificar ou medir a frequência com que os problemas de saúde ocorrem em\npopulações humanas é um dos objetivos da Epidemiologia. A esse respeito, é correto afirmar:","options":{"A":"Incidência é definida como a frequência de casos existentes de uma determinada doença, em\numa determinada população e em um dado momento.","B":"Taxa de incidência é a expressão da frequência com que surgem novos casos de uma doença\npor unidade de tempo e com relação ao tamanho\nda população.","C":"Prevalência é a frequência de casos novos de uma determinada doença ou problema de saúde\nnum determinado período de tempo em uma dada\npopulação.","D":"A incidência acumulada é calculada como a razão entre o número de casos novos de uma\ndeterminada doença e o total de pessoa-tempo gerado a partir da população.","E":"A prevalência pontual expressa a proporção de pessoas que apresentam uma determinada\ndoença em algum momento desde o nascimento."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-44020","number":"44020","sourceNumber":"44020","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação às mortes por causas externas no Brasil, assinale a alternativa incorreta:","options":{"A":"As causas externas ganharam destaque nos estudos de mortalidade nas últimas décadas em\ndecorrência da intensificação das mortes por homicídios a partir dos anos 80.","B":"Entre as causas externas, os óbitos relacionados aos acidentes de transporte são os mais\ncomuns. Deve-se considerar, todavia, que existe um crescimento das mortes violentas.","C":"O crescimento do número de casos de morte violenta é o reflexo dos problemas urbanos\ncontemporâneos com importância crescente no cenário nacional e internacional.","D":"O aumento de mortes por causa externa em regiões metropolitanas não exerce nenhuma\ninfluência na pirâmide populacional.","E":"Entre idosos, as quedas e demais causas externas de lesões acidentais representam a mais\ncomum das causas externas de óbitos, seguindo-se dos acidentes de transporte."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-43963","number":"43963","sourceNumber":"43963","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Índice de Swaroop-Uemura, expresso pela razão de mortalidade proporcional é muito\nempregado para avaliar o nível de saúde de diversas populações, porque compara os seguintes\ndados de cada país ou região:","options":{"A":"O grau de envelhecimento da população.","B":"Dados de óbitos, que dispensam dados de população.","C":"O peso da mortalidade infantil no conjunto de óbitos.","D":"As curvas de óbitos por faixa etária que refletem a pirâmide populacional.","E":"O coeficiente geral de mortalidade da população."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-43981","number":"43981","sourceNumber":"43981","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Vários estudos epidemiológicos têm mostrado que, aproximadamente, 85% dos casos\nde câncer de pulmão são devidos ao hábito de\nfumar. Essa medida é um exemplo de:","options":{"A":"Risco relativo.","B":"Risco atribuível.","C":"Coeficiente de incidência.","D":"Razão de proporção de mortalidade.","E":"Prevalência."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32426","number":"32426","sourceNumber":"32426","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A próxima questão é baseada na tabela abaixo. Segundo os dados disponíveis no\nDATASUS, Vitória (ES) tem uma população estimada de 320.822 habitantes e teve em um ano\n\n4.433 nascidos vivos. Ocorreram 1.888 óbitos assim distribuídos por faixa etária: Qual o coeficiente\nde mortalidade geral no Município de Vitória? (VER\nIMAGEM).","options":{"A":"7,05 por 1.000 habitantes.","B":"5,88 por 1.000 habitantes.","C":"5,88 por 10.000 habitantes.","D":"7,05 por 10.000 habitantes.","E":"32.58 por 1.000 habitantes."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":["question_bank/media/medcurso/medcurso-preventiva-pre-1/32426.png"],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32430","number":"32430","sourceNumber":"32430","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A próxima questão é baseada na tabela abaixo. Segundo os dados disponíveis no\nDATASUS, Vitória (ES) tem uma população estimada de 320.822 habitantes e teve em um ano\n\n4.433 nascidos vivos. Ocorreram 1.888 óbitos assim distribuídos por faixa etária: Com os dados da\nTabela 1, calcule o indicador de Swaroop e Uemura para o Município de Vitória. (VER IMAGEM).","options":{"A":"70.65%","B":"7,05%","C":"53,19%","D":"23,25%","E":"4,15%"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32408","number":"32408","sourceNumber":"32408","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à transição demográfica, qual é a característica da fase intermediária\n\"convergência dos coeficientes\"?","options":{"A":"Há coexistência de altas taxas de natalidade e mortalidade.","B":"O ritmo de crescimento populacional aumenta.","C":"A natalidade passa a diminuir em ritmo mais acelerado que a mortalidade.","D":"Baixa natalidade e baixa mortalidade.","E":"O coeficiente de mortalidade se reduz de uma forma importante, mas o coeficiente de natalidade\ncontinua elevado, gerando um desequilíbrio traduzido pelo grande aumento da população."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32410","number":"32410","sourceNumber":"32410","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Uma doença como a hanseníase de longa duração e baixo grau de infectividade\ncostuma apresentar taxas de acordo com os índices\nde:","options":{"A":"Alta prevalência, alta incidência e baixa letalidade.","B":"Baixa prevalência, alta incidência e alta letalidade.","C":"Baixa prevalência, baixa incidência e alta letalidade.","D":"Alta prevalência, baixa incidência, baixa letalidade.","E":"Alta prevalência, baixa incidência e alta letalidade."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32415","number":"32415","sourceNumber":"32415","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O coeficiente ou taxa de mortalidade infantil neonatal é o número de óbitos ocorridos:","options":{"A":"Menores de 7 dias de vida por 1.000 nascidos vivos.","B":"Menores de 28 dias por 1.000 nascidos vivos.","C":"Menores de 7 dias por 1.000 habitantes.","D":"Menores de 28 dias por 1.000 habitantes.","E":"Menores de um ano por 1.000 habitantes."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32429","number":"32429","sourceNumber":"32429","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os coeficientes de incidência são geralmente confundidos com os coeficientes de\nprevalência. Eles são semelhantes, mas a diferença é importante. Qual das afirmativas a seguir\nestá incorreta?","options":{"A":"Ambos são tipos de coeficientes de morbidade.","B":"O numerador do coeficiente de prevalência inclui todas as pessoas doentes de uma causa\nespecífica durante um intervalo de tempo específico ou num determinado momento.","C":"O coeficiente de prevalência não inclui doenças que começaram anteriormente ao intervalo de\ntempo específico ou momento estudado.","D":"Um coeficiente de incidência é uma medida de frequência de ocorrência de casos novos de uma\ndoença em uma população definida durante um\nintervalo de tempo específico.","E":"O denominador do coeficiente de incidência e a população exposta ao risco durante um intervalo\nde tempo, em uma área específica."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32406","number":"32406","sourceNumber":"32406","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"\"A desidratação é uma doença que ocorre com maior frequência em crianças de raça\nbranca, independente do sexo, que moram em região de clima tropical e nos meses de verão?.\n\nEsta descrição da desidratação é feita com as seguintes variáveis da epidemiologia descritiva, na\nordem como aparecem no texto.","options":{"A":"Pessoa, espaço e tempo.","B":"Pessoa, tempo e tempo.","C":"Tempo, pessoa, espaço e sazonalidade.","D":"Idade, pessoa e tempo.","E":"Pessoa, espaço e espaço."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-32435","number":"32435","sourceNumber":"32435","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A teoria da transição demográfica surgiu no início do século XX, tomando como\nreferência, em sua formulação, as modificações observadas nos países europeus nos séculos\nanteriores. Qual das afirmativas abaixo é parte conceitual da teoria da transição demográfica?","options":{"A":"A fase pré-industrial seria caracterizada por um crescimento populacional intenso.","B":"A fase de industrialização teria uma tendência populacional estável ou regressiva.","C":"A fase de consolidação da sociedade industrial teria crescimento populacional lento.","D":"O número elevado de filhos em uma sociedade de base rural constitui-se em garantia de\nmão-de-obra adequada.","E":"A industrialização e a urbanização concorrem para o aumento da fecundidade em virtude da\nmaior estabilidade social."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-23141","number":"23141","sourceNumber":"23141","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma comunidade com 1000 adultos, um exame clinico inicial revela que 250 adultos\napresentam hipertensão arterial. Todos os adultos são acompanhados por 05 anos. Neste período,\n50 adultos desenvolvem a doença. A incidência acumulada (nos 05 anos) de hipertensão arterial é\nde:","options":{"A":"50/1000","B":"50/750","C":"250/1000","D":"300/1000","E":"300/750"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-23147","number":"23147","sourceNumber":"23147","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Você vai trabalhar em comunidade e necessita conhecer os principais problemas de\nsaúde dessa população. Que indicadores de\nmorbidade você utilizará para doenças de curta\nduração (como sarampo, difteria, meningite) e para as doenças de longa duração (como diabetes\nmellitus, hipertensão arterial, hanseníase), respectivamente:","options":{"A":"incidência, prevalência","B":"incidência, mortalidade","C":"prevalência, incidência","D":"prevalência, letalidade","E":"mortalidade, letalidade"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-23152","number":"23152","sourceNumber":"23152","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Embora a expectativa de vida da população brasileira venha aumentando nas últimas\ndécadas, preocupam as autoridades sanitárias os níveis elevados de mortalidade da população\njovem, especialmente na faixa etária entre 15 e 29 anos, nos grandes e médios centros urbanos.\nAs ações de maior impacto potencial para a diminuição da mortalidade da população adulta jovem\nbrasileira devem estar centradas em:","options":{"A":"prevenção da AIDS","B":"prevenção das mortes violentas e por acidentes","C":"melhoria das condições sanitárias","D":"elevação da renda per capita da população","E":"combate a fome"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-23154","number":"23154","sourceNumber":"23154","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Brasil encontra-se em um processo acelerado de queda nas taxas de fecundidade,\nde modo que a população cresce cada vez mais\nlentamente. Este dado significa que no país:","options":{"A":"haverá problemas de carência de população no ano 2010","B":"haverá condições para uma melhor distribuição da renda","C":"acabará a necessidade de melhoria dos serviços de assistência ao parto","D":"ocorrerá uma mudança nos padrões de morbidade, com aumento acelerado das doenças\ncrônicas","E":"A situação ficará estável e não teremos problemas populacionais"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-23157","number":"23157","sourceNumber":"23157","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual é a afirmativa incorreta em relação as mudanças dos parâmetros demográficos do\nBrasil?","options":{"A":"A mortalidade começa a declinar a partir de 1940. Início do controle e tratamento das doenças\ninfecto-contagiosas, programa de vacinação e melhoria das condições sanitárias","B":"O rápido declínio dos níveis de mortalidade aliado á manutenção dos altos níveis de fecundidade\ncausou aumento populacional","C":"A fecundidade permanece constante e em níveis elevados até os anos 60","D":"A queda da fecundidade começa a ocorrer no final da década de 80","E":"Aumento da expectativa de vida nos últimos anos"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27416","number":"27416","sourceNumber":"27416","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quanto às medidas de morbidade utilizadas em epidemiologia é INCORRETO afirmar:","options":{"A":"A prevalência é muito útil em planejamento e administração de serviços e de programas.","B":"As afecções agudas são, em geral, indicadas através da incidência.","C":"A incorporação de um novo tratamento, que evita a morte, mas não logra a cura dos casos de\numa doença, produz queda de prevalência.","D":"Incidência e prevalência medem diferentes aspectos da morbidade e, em geral, são bem\nexpressas através da relação entre casos e população.","E":"A incidência é um dos fatores determinantes do nível de prevalência."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27418","number":"27418","sourceNumber":"27418","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Alguns indicadores utilizados em Epidemiologia traduzem o risco de acontecimento de\neventos relacionados à saúde, em uma população. Entre as alternativas a seguir, assinale um\nindicador desse tipo:","options":{"A":"Indicador de Swaroup e Uemura","B":"Coeficiente de Incidência de Dengue","C":"Índice de massa corpórea","D":"Escala de atitudes em relação à AIDS","E":"Razão consultas oferecidas e habitantes"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-27419","number":"27419","sourceNumber":"27419","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considerando o perfil epidemiológico do Brasil, observa-se nas últimas duas décadas:","options":{"A":"Redução da mortalidade por câncer e da mortalidade por tétano.","B":"Aumento da mortalidade infantil e da mortalidade por doenças crônicas não transmissíveis.","C":"Aumento da mortalidade por causas externas e da mortalidade por gastroenterite.","D":"Aumento da mortalidade entre os mais idosos e diminuição da mortalidade infantil.","E":"Aumento da mortalidade por doenças imunopreveníveis."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8131","number":"8131","sourceNumber":"8131","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A comparação entre áreas urbanas e rurais no país é dificultada por alguns fatores\nentre os quais pode ser citado:","options":{"A":"As taxas de urbanização são bastante diferenciadas, sendo maior a proporção de coletividades\nurbanas nas regiões Sudeste, Sul e\nCentro-Oeste.","B":"Ao contrário dos níveis secundário e terciário, a atenção primária para as populações rurais é\nbastante superior àquela à disposição das populações urbanas.","C":"A semelhança entre as duas estruturas populacionais permite comparar diretamente os\ncoeficientes de mortalidade geral, mas não os específicos.","D":"Os fatores que reduzem as condições de saúde são simetricamente distribuídos entre as duas\npopulações, mas não são os fatores promotores da doença.","E":"As populações rurais e urbanas têm diferentes prevalências de desnutrição, a qual é um\nfenômeno mais comum no meio urbano do que no rural."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8086","number":"8086","sourceNumber":"8086","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Brasil tem experimentado, nas últimas décadas, importantes transformações no seu\npadrão de morbidade e de mortalidade, as\nquais estão relacionadas a diversas condições. Entre as\nabaixo, apenas uma das condições em questão está corretamente enunciada. Assinale:","options":{"A":"Houve aumento da mortalidade precoce, especialmente aquela ligada a doenças infecciosas e\nparasitárias.","B":"Houve redução da expectativa de vida ao nascer, com a consequente redução da população\nidosa.","C":"Houve um processo acelerado de urbanização e de mudanças socioculturais, com aumento dos\nacidentes e da violência.","D":"Houve um aumento da fecundidade que, em conjunto com a redução da expectativa de vida,\nlevou à ampliação da base da pirâmide populacional.","E":"Houve um aumento da desigualdade em saúde, a qual, ao contrário de outros critérios de\ndesigualdade, é homogênea em todo o território nacional."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8092","number":"8092","sourceNumber":"8092","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Houve queda da mortalidade infantil no Brasil nas últimas décadas, refletindo ganhos\nconsistentes na qualidade de saúde da população. O novo perfil de mortes na faixa etária pediátrica\npode ser caracterizada como:","options":{"A":"Constituído por redução na mortalidade perinatal em detrimento das mortes pós-neonatais.","B":"Possuindo maiores frequências de óbito causado por infecções respiratórias.","C":"Sendo predominantemente relacionados às malformações congênitas, para as quais não há\nalternativas de prevenção.","D":"Possuindo percentuais de queda homogêneos em todo território nacional.","E":"Constituído pelo predomínio da mortalidade perinatal, a qual vem sofrendo incremento relativo\nao longo dos anos."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8096","number":"8096","sourceNumber":"8096","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O envelhecimento está associado a mudanças biológicas que aumentam o risco de\nmorbidade, incapacidade e morte. Existem vários possíveis indicadores de saúde no idoso. A esse\nrespeito, assinale a alternativa que apresenta uma afirmativa correta:","options":{"A":"A percepção da própria saúde é um indicador precário do estado de saúde do idoso em\ndecorrência de seu aspecto subjetivo.","B":"Indicadores como ter estado acamado, ter deixado de realizar atividades rotineiras ou número de\ndias em que esteve incapacitado são desprovidos de especificidade.","C":"A capacidade funcional não representa medida abrangente de saúde dos idosos, sendo\nconsiderada um indicador de padrão inferior.","D":"As necessidades de saúde podem ser representadas por uma reta ascendente segundo a idade,\numa vez que aumentam à medida que os indivíduos envelhecem.","E":"A idade cronológica é o mais robusto preditor da morbidade e mortalidade."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-8138","number":"8138","sourceNumber":"8138","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O planejamento em saúde deve considerar as mudanças que se desenrolam no plano\npopulacional, as quais repercutem sobre a economia da saúde. É uma afirmação verdadeira sobre\nessas mudanças:","options":{"A":"O mundo atual retrocede a um padrão epidemiológico semelhante àquele observado ao longo da\ndécada de 1940.","B":"A manutenção do quadro de saúde observada em populações experimentando a transição\ndemográfica é primariamente uma função do aumento na mortalidade.","C":"A transição demográfica pode ser conceituada como a associação entre a urbanização e suas\nconsequências, o declínio na mortalidade por doenças infecciosas e o declínio da fertilidade.","D":"A transição epidemiológica é caracterizada pelo rejuvenescimento da população, declínio das\ndoenças crônicas, crescimento econômico e\ndeclínio na incidência de doenças infecciosas.","E":"A transformação na estrutura etária da mortalidade, associada à transição epidemiológica, leva à\ntransição em sua estrutura de causas, que tem sido denominada ?transição demográfica?."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-9452","number":"9452","sourceNumber":"9452","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação às mortes por causas externas no Brasil, assinale a alternativa CORRETA:","options":{"A":"As mortes por causas externas constituem hoje a primeira causa de morte nas regiões\nmetropolitanas brasileiras.","B":"Os coeficientes de mortalidade específica por causas externas são maiores entre jovens de\nambos os sexos.","C":"As colisões com veículos constituem o maior componente das mortes por causas externas.","D":"As mortes por homicídio nas capitais do sudeste, vêm alterando a pirâmide populacional,\ncausando diminuição da população de 20 a 29 anos.","E":"Os homicídios representam o maior componente das causas externas em todas as regiões\nmetropolitanas do país."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-339851","number":"339851","sourceNumber":"339851","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"De acordo com o Plano de Ações Estratégicas para o Enfrentamento das Doenças\nCrônicas e Agravos Não Transmissíveis no Brasil, 2021?2030, do Ministério da Saúde, a:","options":{"A":"Região Norte do Brasil apresentou, entre 2000 e 2019, as maiores taxas de mortalidade por\nsuicídio em todo o período analisado.","B":"Maior mortalidade proporcional pelo suicídio no Brasil, entre 2000 e 2019, ocorreu na faixa\netária\nde 40 a 59 anos.","C":"Redução das taxas de suicídio no Brasil, entre 2000 e 2019, foi da ordem de 42,6%.","D":"Mortalidade por suicídio, no Brasil, foi maior para o sexo masculino entre 2000 e 2019."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-321614","number":"321614","sourceNumber":"321614","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Near Miss Materno (NMM) é um indicador de:","options":{"A":"Mortalidade.","B":"Morbidade.","C":"Letalidade.","D":"Contaminação."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-334857","number":"334857","sourceNumber":"334857","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Durante a avaliação da consolidação da Rede de Atenção Materno Infantil em um\nestado brasileiro pela equipe certificadora do\nMinistério da Saúde observou-se diferentes taxas de\nmortalidade neonatal precoce em duas maternidades: uma delas situada em hospital universitário\n(13 por 1.000 nascidos vivos) e outra em uma pequena cidade do interior (7 por 1.000 nascidos\nvivos). Em relação às conclusões quanto à qualidade dos serviços sabe-se que:","options":{"A":"A maternidade do hospital universitário apresenta maior risco de morte entre os nascidos vivos\nna referida região de saúde.","B":"Deve-se comparar as referidas taxas somente após a sua padronização segundo complexidade\ndo atendimento e papel da maternidade da rede de\natenção à saúde.","C":"A taxa de mortalidade neonatal precoce não se relaciona diretamente com a qualidade do\nserviços hospitalares, e sim a mortalidade infantil pós-neonatal.","D":"A taxa de mortalidade neonatal precoce é a razão entre as mortes nos primeiros 28 dias a cada\n\n1.000 nascidos vivos."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342691","number":"342691","sourceNumber":"342691","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Na população brasileira masculina, considerando a faixa etária de 25 a 59 anos, as\nprincipais causas de morte são:","options":{"A":"Doenças cardiocirculatórias.","B":"Diabetes tipo 2.","C":"Causas externas.","D":"Doenças infecciosas."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342693","number":"342693","sourceNumber":"342693","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual é o risco de morrer por determinada doença em um município com os seguintes\ndados: população = 100.000; óbitos totais = 500;\nóbitos pela doença = 10; casos novos da doença\n\n= 2?","options":{"A":"0,01/1.000.","B":"5/1.000.","C":"0,1/1.000.","D":"0,02/1.000."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-363967","number":"363967","sourceNumber":"363967","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Mudanças na fecundidade, mortalidade e nos padrões de causas de morbidade e\nmortalidade distinguem quatro principais estágios da transição epidemiológica. Qual é o estágio que\nse relaciona ao período de desaparecimento das pandemias, mortalidade em declínio,\nacompanhada por queda da fecundidade, com variações no espaço e tempo?","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-363966","number":"363966","sourceNumber":"363966","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Uma mulher que quase morreu, mas sobreviveu a uma complicação grave, ocorrida\ndurante a gravidez, parto ou até em 42 dias após término da gravidez, define um caso de","options":{"A":"near miss materno.","B":"razão de morte materna.","C":"ano de vida perdido ajustado por incapacidade.","D":"mortalidade materna aguda grave."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-363911","number":"363911","sourceNumber":"363911","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Ao se dividir o número de nascidos mortos pelo número de nascidos vivos mais o\nnúmero de nascidos mortos e depois multiplicar o resultado por 1000, obtém-se o coeficiente de","options":{"A":"mortalidade perinatal.","B":"natimortalidade.","C":"mortalidade neonatal precoce.","D":"mortalidade neonatal tardia."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-363906","number":"363906","sourceNumber":"363906","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O indicador de Swaroop e Uemura é expresso por meio de","options":{"A":"uma taxa.","B":"um coeficiente.","C":"uma proporção.","D":"uma subtração."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-362640","number":"362640","sourceNumber":"362640","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O cidadão poderá conhecer melhor sua situação vacinal e adotar iniciativas para\nregularizar as vacinas do calendário, de acordo com cada ciclo de vida. Sendo correto que:","options":{"A":"As informações sobre situação vacinal nunca são disponibilizadas de várias formas, com\nabrangência em todas as instâncias operacionais e decisórias do SUS.","B":"As informações sobre situação vacinal são disponibilizadas de várias formas, com abrangência\nem todas as instâncias operacionais e decisórias\ndo SUS.","C":"As informações sobre situação vacinal são disponibilizadas de várias formas, com abrangência\nem todas as instâncias operacionais e não\ndecisórias do SUS.","D":"As informações sobre situação vacinal são disponibilizadas de várias formas, com abrangência\nem todas as instâncias não operacionais e sim\ndecisórias do SUS."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-362638","number":"362638","sourceNumber":"362638","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Embora o aumento da obesidade dentro das Doenças Crônicas e Agravos Não\nTransmissíveis (DCNT), entre adultos não tenha sido tão marcante nos últimos anos monitorados,\npode-se afirmar que:","options":{"A":"A previsão é de que a prevalência não continue crescendo, chegando ao final do plano de\nenfrentamento das DCNT sem êxito no atingimento dessa meta.","B":"A previsão é de que a prevalência continue crescendo, chegando ao final do plano de\nenfrentamento das DCNT sem êxito no atingimento dessa meta.","C":"A previsão é de que a prevalência continue crescendo, chegando ao final do plano de\nenfrentamento das DCNT com êxito no atingimento dessa meta.","D":"A previsão é de que a prevalência continue reduzindo, chegando ao final do plano de\nenfrentamento das DCNT sem êxito no atingimento dessa meta."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-362637","number":"362637","sourceNumber":"362637","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Antes de iniciar o registro de doses aplicadas de imunobiológicos no sistema de\ninformação, alguns preparativos devem ser observados:","options":{"A":"Avaliar a existência de equipamentos de informática para o registro; analisar a disponibilidade\nou\na ausência de rede de internet ou rede local,\npara optar pela forma de registro que esteja de\ndesacordo com as condições da unidade de saúde; conhecer os fluxos de informação sobre\nvacinação dentro e fora da unidade; verificar o cadastro do estabelecimento de saúde e a\nrespectiva habilitação como sala de vacina no Cnes, o cadastro do vacinador no CNS, o cadastro\ndo operador do sistema de informação no Sistema de Cadastro de Permissão de Acesso (SCPA) e\na vinculação ao estabelecimento de saúde do lote da vacina aplicada.","B":"Avaliar a existência de equipamentos de informática para o registro; analisar a disponibilidade\nou\na ausência de rede de internet ou rede local,\npara optar pela forma de registro que esteja de acordo\ncom as condições da unidade de saúde; conhecer os fluxos de informação sobre vacinação dentro\ne fora da unidade; verificar o cadastro do estabelecimento de saúde e a respectiva habilitação\ncomo sala de vacina no Cnes, o cadastro do vacinador no CNS, o cadastro do operador do sistema\nde informação no Sistema de Cadastro de Permissão de Acesso (SCPA) e nunca a vinculação ao\nestabelecimento de saúde do lote da vacina aplicada.","C":"Avaliar a existência de equipamentos de informática para o registro; vetado analisar a\ndisponibilidade ou a ausência de rede de\ninternet ou rede local, para optar pela forma de registro\nque esteja de acordo com as condições da unidade de saúde; conhecer os fluxos de informação\nsobre vacinação dentro e fora da unidade; verificar o cadastro do estabelecimento de saúde e a\nrespectiva habilitação como sala de vacina no Cnes, o cadastro do vacinador no CNS, o cadastro\ndo operador do sistema de informação no Sistema de Cadastro de Permissão de Acesso (SCPA) e\na vinculação ao estabelecimento de saúde do lote da vacina aplicada.","D":"Avaliar a existência de equipamentos de informática para o registro; analisar a disponibilidade\nou\na ausência de rede de internet ou rede local,\npara optar pela forma de registro que esteja de acordo\ncom as condições da unidade de saúde; conhecer os fluxos de informação sobre vacinação dentro\n\ne fora da unidade; verificar o cadastro do estabelecimento de saúde e a respectiva habilitação\ncomo sala de vacina no Cnes, o cadastro do\nvacinador no CNS, o cadastro do operador do sistema\nde informação no Sistema de Cadastro de Permissão de Acesso (SCPA) e a vinculação ao\nestabelecimento de saúde do lote da vacina aplicada."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-362635","number":"362635","sourceNumber":"362635","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sabe-se que o perfil das causas de morte no Brasil tem mudado de forma importante\nnas últimas décadas.","options":{"A":"As transições epidemiológicas e não a demográfica ocorrem de forma acelerada.","B":"As transições epidemiológica e demográfica ocorrem de forma lenta.","C":"As transições epidemiológica e demográfica ocorrem de forma acelerada.","D":"As transições epidemiológica e demográfica não ocorrem."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-362634","number":"362634","sourceNumber":"362634","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Embora as taxas de mortalidade padronizadas por idade fossem maiores nos homens\nem todo o período, podemos indicar como\ncorreto que:","options":{"A":"A redução porcentual não foi similar para ambos os sexos, 48% para homens e 52% para\nmulheres. A mortalidade proporcional por\nDoenças Cardiovasculares (DCV) foi maior nas mulheres\ndurante todo o período de 1990 a 2019.","B":"A redução porcentual foi similar para ambos os sexos, 48% para homens e 52% para mulheres.\n\nA mortalidade proporcional por Doenças Cardiovasculares (DCV) foi maior nas mulheres durante\ntodo o período de 1990 a 2019.","C":"A redução porcentual foi similar para ambos os sexos, 48% para homens e 52% para mulheres.\n\nA mortalidade proporcional por Doenças Cardiovasculares (DCV) foi menor nas mulheres durante\ntodo o período de 1990 a 2019.","D":"A redução porcentual não foi similar para ambos os sexos, 98% para homens e 92% para\nmulheres. A mortalidade proporcional por\nDoenças Cardiovasculares (DCV) foi maior nas mulheres\ndurante todo o período de 1990 a 2019."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-346409","number":"346409","sourceNumber":"346409","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Os resultados de um estudo de coorte prospectivo com o objetivo de analisar a\nassociação entre fumo e hipertensão tem o seguinte resultado: Sobre o estudo assinale a correta\nsobre a incidência de hipertensão.","options":{"A":"Entre não fumantes é de 20%;","B":"Entre fumantes é de 28,6%;","C":"Entre fumantes é dada pelo quociente 40/60;","D":"Entre não fumantes é de 25%."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-321566","number":"321566","sourceNumber":"321566","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"De acordo com o Plano de Ações Estratégicas para o Enfrentamento das Doenças\nCrônicas e Agravos Não Transmissíveis no Brasil, 2021 - 2030, do Ministério da Saúde, a","options":{"A":"região Norte do Brasil apresentou, entre 2000 e 2019, as maiores taxas de mortalidade por\nsuicídio em todo o período analisado.","B":"maior mortalidade proporcional pelo suicídio no Brasil, entre 2000 e 2019, ocorreu na faixa\netária\nde 40 a 59 anos.","C":"redução das taxas de suicídio no Brasil, entre 2000 e 2019, foi da ordem de 42,6%.","D":"mortalidade por suicídio, no Brasil, foi maior para o sexo masculino entre 2000 e 2019."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-321570","number":"321570","sourceNumber":"321570","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As Curvas de Mortalidade Proporcional são construídas a partir da distribuição\nproporcional dos óbitos por grupos etários\ncom relação ao total de óbitos e exibem um determinado\nformato gráfico que indicará o nível de saúde da área avaliada. Segundo a classificação de Nelson\nMoraes, a do tipo III está associada ao nível de saúde","options":{"A":"baixo.","B":"regular.","C":"bom.","D":"elevado."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-321571","number":"321571","sourceNumber":"321571","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em 01/01/2021, existiam 800 casos de hanseníase em determinado município. Ao\nlongo deste ano foram notificados 200 casos\nnovos dessa doença e 400 casos tiveram alta por\ncura. A população residente estimada para esse município era de 100.000 habitantes. Qual a taxa\nde prevalência de hanseníase no final de 2021?","options":{"A":"0,6%.","B":"0,8%.","C":"1,0%.","D":"1,4%."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-332004","number":"332004","sourceNumber":"332004","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Média de Permanência Geral é um indicador de desempenho hospitalar que está\nrelacionado à gestão eficiente do leito operacional e às boas práticas clínicas. Representa o tempo\nmédio em dias que os pacientes permanecem internados no hospital. Identifique que importante\nfator aumenta o valor desse indicador:","options":{"A":"Mediana de idade da demanda.","B":"Natureza assistencial do hospital.","C":"Tipo de controle administrativo hospitalar.","D":"Número de salas cirúrgicas.","E":"Exclusividade no atendimento pacientes agudos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-332007","number":"332007","sourceNumber":"332007","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma área com 30 mil habitantes, foi verificada a ocorrência maciça de casos de\nCovid-19. Teste em massa feito em toda população em dois meses detectou anticorpos em 1.800\npessoas. De acordo com o texto podemos afirmar que nesses dois meses:","options":{"A":"A prevalência da doença é de 6%.","B":"A prevalência da doença é de 1.800 casos.","C":"O coeficiente de incidência da doença é de seis casos a cada cem habitantes.","D":"A taxa de infecção viral foi de 0,6 caso para cada 1 mil habitantes.","E":"A taxa de prevalência foi de 6%."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-321613","number":"321613","sourceNumber":"321613","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Leia o caso clínico. Adolescente de 17 anos provoca um aborto e chega à urgência com\nrestos ovulares infectados. Mesmo com os procedimentos corretos, ela vai a óbito por septicemia,\n35 dias depois. A morte, nesse caso, é considerada:","options":{"A":"Não materna.","B":"Não obstétrica.","C":"Obstétrica direta.","D":"Obstétrica indireta."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342675","number":"342675","sourceNumber":"342675","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação à Taxa de Mortalidade Infantil (TMI), assinale a alternativa correta:","options":{"A":"o declínio da TMI, nas últimas décadas, foi expressivo, reduzindo a níveis insignificantes as\ndiferenças entre as regiões do país, haja\nvista a melhoria universal das condições socioeconômicas\ne de acesso a serviços de saúde","B":"é geralmente classificada em alta (50 ou mais por 1.000 nascidos vivos), média (20 a 49 por\n1.000 nascidos vivos) e baixa (menos de 20 por\n1.000 nascidos vivos), em função da proximidade\nou da distância de valores já alcançados em sociedades mais desenvolvidas, sendo que\natualmente o Brasil apresenta TMI baixa","C":"taxas de mortalidade infantil reduzidas indicam boas condições de vida da população de uma\nmaneira global e homogênea entre grupos sociais","D":"o cálculo direto da taxa exige correções da subenumeração de óbitos infantis e de nascidos\nvivos, especialmente nas regiões Sudeste e Sul, por\nterem os dados de mais baixa qualidade do\npaís"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-339838","number":"339838","sourceNumber":"339838","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No ano de 2021, 412 mil brasileiros morreram pela Covid-19. Qual dos seguintes\nfatores melhor descreve essa estatística?","options":{"A":"Prevalência-ponto","B":"Incidência cumulativa","C":"Incidência-densidade","D":"Prevalência-período","E":"Nenhuma das alternativas"},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342679","number":"342679","sourceNumber":"342679","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação às medidas de frequência em estudos epidemiológicos é correto afirmar\nque:","options":{"A":"a prevalência de uma doença varia conforme a incidência, sua duração e os movimentos\nmigratórios","B":"a prevalência de uma doença é função direta da sazonalidade, isto é, a magnitude de uma\ndoença varia com o aparecimento de casos novos\ndo agravo","C":"a prevalência e a incidência são conceitos antagônicos","D":"a incidência de uma doença é caracteristicamente calculada em estudos transversais (inquéritos\nepidemiológicos)"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342680","number":"342680","sourceNumber":"342680","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A ampliação da Atenção Primária à Saúde, aumento da cobertura vacinai, maior acesso\nao pré-natal, organização dos fluxos em rede\nde saúde, melhoria das condições nutricionais e\nambientais, ampliação da licença-maternidade e outros direitos sociais são ações cujos resultados\nse demonstram, diretamente:","options":{"A":"na organização e construção de um sistema de rede social de apoio","B":"na redução importante do indicador de mortalidade infantil em todo o país","C":"na redução da taxa de abandono escolar","D":"na redução da transmissão de doenças infectocontagiosas"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-339841","number":"339841","sourceNumber":"339841","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Quarenta e oito por cento dos adultos relataram ter tido episódio de cefaleia que durou\npelo menos 1 dia nos últimos 3 meses. Qual dos seguintes fatores melhor descreve essa taxa?","options":{"A":"Incidência-densidade","B":"Incidência cumulativa","C":"Prevalência-ponto","D":"Prevalência-período","E":"Taxa de complicação"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342684","number":"342684","sourceNumber":"342684","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Nas últimas décadas, o Brasil vem passando por transformações de ordem social e\neconômica e pela reforma do sistema de saúde, as quais trazem impacto para a situação\nepidemiológica e demográfica do país. Nesse contexto, é correto afirmar que:","options":{"A":"a taxa de crescimento anual da população, na última década, foi de 1,9%/ano, valor mantido\ndesde a década de 1980","B":"a mortalidade infantil vem caindo nas últimas 3 décadas de forma consistente, principalmente\npela redução da mortalidade no componente neonatal","C":"a expectativa de vida ao nascer, entre 1991 e 2010, aumentou de 71 para 77 anos para\nmulheres, porém se manteve em 63 anos para os homens","D":"a mortalidade proporcional atribuída às doenças infecciosas vem diminuindo progressivamente,\ne a atribuída às doenças crônicas não\ntransmissíveis e causas externas vêm aumentando"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-330150","number":"330150","sourceNumber":"330150","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O Coeficiente de Mortalidade Geral (CMG) estima a probabilidade de morrer de um\nindivíduo da população geral e é obtido pela relação entre o número de:","options":{"A":"Óbitos e o número de nascimento anual em um município.","B":"Óbitos e o número de habitantes em um determinado período e local.","C":"Nascimentos e o número de habitantes anual em um hospital.","D":"Óbitos, o número de nascimentos e o número de habitantes em um determinado período e local."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-339852","number":"339852","sourceNumber":"339852","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As curvas de mortalidade proporcional são construídas a partir da distribuição\nproporcional dos óbitos por grupos etários\ncom relação ao total de óbitos e exibem um determinado\nformato gráfico que indicará o nível de saúde da área avaliada. Segundo a classificação de Nelson\nMoraes, a do tipo III está associada ao nível de saúde:","options":{"A":"Baixo.","B":"Regular.","C":"Bom.","D":"Elevado."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-342692","number":"342692","sourceNumber":"342692","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, a morbimortalidade por doenças infecciosas e a morbimortalidade por\ndoenças crônico-degenerativas encontram-se:","options":{"A":"em ascensão, definindo a transição epidemiológica","B":"em ascensão e em declínio, respectivamente","C":"em declínio e em ascensão, respectivamente","D":"estacionárias, definindo a transição demográfica"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-339853","number":"339853","sourceNumber":"339853","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em 01/01/2021, existiam 800 casos de hanseníase em determinado município. Ao\nlongo deste ano foram notificados 200 casos\nnovos dessa doença e 400 casos tiveram alta por\ncura. A população residente estimada para esse município era de 100.000 habitantes. Qual a taxa\nde prevalência de hanseníase no final de 2021?","options":{"A":"0,6%.","B":"0,8%.","C":"1,0%.","D":"1,4%."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-300811","number":"300811","sourceNumber":"300811","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qualidade de vida pode ser concebida como um conceito amorfo, utilizado por muitas\ndisciplinas ? Geografia, Literatura, Filosofia, Publicidade, Economia, Promoção de Saúde, Ciências\nMédicas e Sociais ?, sendo um conceito vago e multidimensional que incorpora, teoricamente,\ntodos os aspectos da vida humana. A alternativa que apresenta CORRETAMENTE a denominação\ndos três determinantes que levam a uma relativização da noção de qualidade de vida é:","options":{"A":"Históricos, classes sociais e religião.","B":"Classes sociais, estratificações e históricos.","C":"Religião, cultural e classes sociais.","D":"Cultural, estratificações e históricos."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-314117","number":"314117","sourceNumber":"314117","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Para o cálculo do coeficiente de mortalidade neonatal precoce, deve-se utilizar, no\nnumerador o seguinte número de óbitos:","options":{"A":"0 a 6 dias de vida completos.","B":"7 a 27 dias de vida completos.","C":"0 a 27 dias de vida completos.","D":"28 a 364 dias de vida completos."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-302871","number":"302871","sourceNumber":"302871","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual dos seguintes sistemas de informação em saúde toma por base informações de\num Território Sanitário?","options":{"A":"SIM.","B":"SINAN.","C":"SIAB.","D":"SINASC.","E":"SISVAN."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-302873","number":"302873","sourceNumber":"302873","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com informações advindas do Sistema de Informação sobre Nascidos Vivos e do\nSistema de Informações sobre Mortalidade, é possível calcular o seguinte indicador:","options":{"A":"Coeficiente de Mortalidade Geral.","B":"Taxa Bruta de Natalidade.","C":"Coeficiente de Mortalidade Infantil.","D":"Coeficiente de Letalidade.","E":"Coeficiente de Mortalidade por Sexo."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-302875","number":"302875","sourceNumber":"302875","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Ao se pretender realizar um estudo para comparar a situação de saúde das populações\nde um dado município em épocas diferentes,\nutilizando-se algum indicador de saúde, verifica-se\nque os únicos dados disponíveis são referentes ao número de mortes, às datas dos falecimentos e\nà idade dos falecidos. Nessa situação, é possível realizar o estudo:","options":{"A":"Utilizando-se os índices de Moraes.","B":"Utilizando-se o Índice de Prevalência Lápsica.","C":"Utilizando-se o coeficiente de mortalidade geral.","D":"Utilizando-se o coeficiente de mortalidade infantil.","E":"Somente se forem obtidos mais dados sobre a população."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-294291","number":"294291","sourceNumber":"294291","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O coeficiente de mortalidade perinatal é:","options":{"A":"O risco de se nascer morto, considerando as perdas fetais que ocorrem a partir da 28ª semana\nde gestação ou em que o concepto tem peso ao\nredor de 1.000 gramas e cerca de 35 cm de\ncomprimento.","B":"Calculado de acordo com a expressão: óbitos ocorridos no período perinatal/perdas fetais. Esse\nresultado deve ser multiplicado por uma constante.","C":"Calculado pela razão entre a soma das perdas fetais precoces e dos óbitos neonatais tardios, e\ntodos os nascimentos, incluindo os natimortos e os nascidos vivos.","D":"A expressão do risco de morte ao longo do período perinatal."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-317969","number":"317969","sourceNumber":"317969","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Ao se dividir o número de óbitos de crianças menores de um ano, no período, por todos\nos óbitos, no mesmo período, obtém-se","options":{"A":"o coeficiente de mortalidade infantil.","B":"o coeficiente de mortalidade por idade.","C":"o indicador de Swaroop-Uemura.","D":"a mortalidade proporcional de menores de um ano."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-317973","number":"317973","sourceNumber":"317973","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um dos principais sistemas de informação de saúde é o de informações hospitalares\n(SIH). A fonte de informação desse sistema é:","options":{"A":"Declaração de óbito.","B":"Declaração de nascidos vivos.","C":"Autorização de internação hospitalar.","D":"Boletim de produção de serviços hospitalares."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-317203","number":"317203","sourceNumber":"317203","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O cálculo de indicadores para o planejamento, monitoramento e avaliação das ações e\nserviços de saúde formam um sistema complexo e guiam as políticas públicas. São consideradas\nboas características para um indicador de saúde:","options":{"A":"Simplicidade, capacidade analítica e disponibilidade.","B":"Validade, confiabilidade e mensurabilidade.","C":"Robustez, complexidade e singularidade.","D":"Cobertura, robustez e generalidade."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-300960","number":"300960","sourceNumber":"300960","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"As PPL são, em sua maioria, oriundas dos segmentos da população mais afetados pela\nTB: homens jovens, com baixa escolaridade, desempregados ou empregados com baixa\nremuneração, que vivem em comunidades desfavorecidas das grandes cidades e algumas vezes\nnas ruas. Com frequência, têm antecedentes de tuberculose e de encarceramento, além de história\nde uso de drogas e taxa de infecção pelo HIV mais elevada do que a da população geral. Sendo\nCORRETO que:","options":{"A":"No Brasil, a taxa de incidência da tuberculose na população prisional é cerca de 28 vezes\nsuperior à da população geral.","B":"No Brasil, a taxa de incidência da tuberculose na população prisional é inferior à da população\ngeral.","C":"No Brasil, a taxa de incidência da tuberculose na população prisional é cerca de 2 vezes\nsuperior à da população geral.","D":"No Brasil, a taxa de incidência da tuberculose na população prisional similar à da população\ngeral."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-300962","number":"300962","sourceNumber":"300962","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Alcançar a longevidade é um fato considerado positivo, que vem sendo alcançado entre\npaíses desenvolvidos e em desenvolvimento. Podemos indicar como CORRETO que:","options":{"A":"A diferença é que aqueles passaram por um processo gradual, sem melhoria das condições de\nvida e sim acesso a um bem-estar estruturado por políticas sociais e relacionadas à saúde; entre os\npaíses em desenvolvimento, ocorreu o contrário: um cenário muito rápido, principalmente na China,\nÍndia e Brasil, que não permitiu um planejamento para essa estruturação, somando-se a isso a\nurbanização em alta escala.","B":"A diferença é que aqueles passaram por um processo gradual, com melhoria das condições de\nvida e do acesso a um bem- estar estruturado por politicas sociais e relacionadas á saúde; entre os\npaíses em desenvolvimento, ocorreu o contrário: um cenário muito rápido, principalmente na China,\nÍndia e Brasil, que não permitiu um planejamento para essa estruturação, somando-se a isso a\nurbanização em alta escala.","C":"A diferença é que aqueles passaram por um processo gradual, com melhoria das condições de\nvida e do acesso a um bem-estar estruturado por políticas sociais e não relacionadas à saúde;\nentre os países em desenvolvimento, ocorreu o contrário: um cenário muito rápido, principalmente\nna China, Índia e Brasil, que não permitiu um planejamento para essa estruturação, somando-se a\nisso a urbanização em alta escala.","D":"A diferença é que aqueles passaram por um processo gradual, com melhoria das condições de\nvida e do acesso a um bem-estar estruturado por políticas sociais e relacionadas á saúde; entre os\npaíses em desenvolvimento, ocorreu o contrário: um cenário muito rápido, principalmente na China,\nÍndia e Brasil, que permitiu um planejamento para essa estruturação, somando-se a isso a\nurbanização em pequena escala."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-313259","number":"313259","sourceNumber":"313259","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A ampliação da Atenção Primária à Saúde, aumento da cobertura vacinai, maior acesso\nao pré-natal, organização dos fluxos em rede\nde saúde, melhoria das condições nutricionais e\nambientais, ampliação da licença-maternidade e outros direitos sociais são ações cujos resultados\nse demonstram, diretamente:","options":{"A":"na organização e construção de um sistema de rede social de apoio","B":"na redução importante do indicador de mortalidade infantil em todo o país","C":"na redução da taxa de abandono escolar","D":"na redução da transmissão de doenças infectocontagiosas"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-300884","number":"300884","sourceNumber":"300884","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Entre os sistemas nacionais de informação em saúde existentes, assinale a alternativa\nque apresenta o sistema que permite construir\nindicadores importantes para conhecer o perfil de\nsaúde de uma região. A partir das informações nele contidas, pode-se obter mortalidade\nproporcional por causas, faixa etária, sexo, local de ocorrência e residência, letalidade dos\nagravos\nde incidência conhecida, bem como taxas de mortalidade geral, infantil, materna ou por qualquer\noutra variável contida na declaração de óbito. Tem como fonte de informação a declaração de\nóbito:","options":{"A":"Sistema de Informação de Agravos de Notificação (Sinan).","B":"Sistema de Informação sobre Mortalidade (SIM).","C":"Sistema de Informação sobre Nascidos Vivos (Sinasc).","D":"Sistema de Informações Hospitalares (SIH/SUS)."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-313266","number":"313266","sourceNumber":"313266","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A região A tem esperança de vida ao nascer de 79 anos; a região B, de 70 anos. Sobre\nisso, assinale a alternativa correta:","options":{"A":"o município A deve ter melhores condições de vida e de saúde","B":"o município B deve ter altos índices de óbitos por violência","C":"a diferença entre as regiões não é grande e pode ser superada em 2 a 3 anos","D":"inicialmente, é preciso analisar as características étnicas das populações dos municípios"},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-300885","number":"300885","sourceNumber":"300885","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa que apresenta o sistema de informação em saúde que, embora\nnão possa ser utilizado para fins\nepidemiológicos, é um importante sistema, pois permite o\nconhecimento dos procedimentos utilizados na rede ambulatorial do SUS, além de conter a relação\ndos serviços da rede própria, contratada e conveniada dos estados e municípios, e informações\nsobre profissionais por especialidade. Tem como fontes de dados as informações do Cadastro\nNacional de Estabelecimentos de Saúde (CNES) e os boletins de produção ambulatorial:","options":{"A":"Sistema de Informações Hospitalares (SIH/SUS).","B":"Sistema de Informação da Atenção Básica (SIAB).","C":"Sistema de Informações Ambulatoriais do SUS (SIA/SUS).","D":"Sistema de Vigilância Alimentar e Nutricional (Sisvan)."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-273137","number":"273137","sourceNumber":"273137","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Indicadores econômicos, tais como o PIB, a renda per capita, a taxa de desemprego e\noutros, foram por muito tempo utilizados para estabelecer o que era ?qualidade de vida?. Anos se\npassaram e percebeu-se que, embora tais indicadores fossem importantes para se avaliar e\ncomparar qualidade de vida entre países, por exemplo, eles não eram suficientes para se medir a\nqualidade de vida dos indivíduos. Considerando o contexto, um fator que atualmente é valorizado\npara o estabelecimento da qualidade de vida do indivíduo é:","options":{"A":"A preocupação com a saúde, apenas.","B":"O conhecimento da arte, o exercício de lazer e moradia confortável.","C":"O desenvolvimento econômico.","D":"A opinião dos indivíduos."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-285097","number":"285097","sourceNumber":"285097","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Considerando-se o tema prioritário da campanha \"novembro azul\", de promoção à\nsaúde do homem (Ministério da Saúde, 2016), e\na principal causa de morte da população\nmasculina de 20 a 59 anos no Brasil, assinale a alternativa correta:","options":{"A":"A campanha prioriza o câncer de próstata, principal causa de morte desta população.","B":"A campanha não tem impacto na principal causa de morte desta população.","C":"O rastreamento de câncer de próstata tem demonstrado impacto na mortalidade.","D":"O preconceito é o principal obstáculo para diminuição da mortalidade desta população."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-265906","number":"265906","sourceNumber":"265906","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A partir da segunda metade do século XX, a sobrevivência democratizou-se em grande\nparte dos países do mundo. Somente podemos\nindicar ERRO na alternativa:","options":{"A":"Mais pessoas estão alcançando as idades mais avançadas.","B":"No Brasil, em 1980, de cada 100 crianças do sexo feminino nascidas vivas, 30 podiam esperar\ncompletar o aniversário de 80 anos, em 2013, este número passou para 55.","C":"Consequentemente, a vida média da população brasileira aumentou quase 12 anos no período.","D":"Um dos fatores responsáveis por esse movimento não foi a queda da mortalidade nas idades\navançadas."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-277475","number":"277475","sourceNumber":"277475","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A mortalidade infantil e perinatal persistem como relevantes eventos em saúde pública,\ndemandando estudos epidemiológicos, tanto para definir sua magnitude e variações temporais,\ncomo para identificar seus determinantes e apontar as intervenções adequadas. O subregistro de\nóbitos ocorridos no período neonatal precoce pode distorcer as estimativas dos indicadores de\nsaúde listados a seguir, exceto:","options":{"A":"o coeficiente de mortalidade infantil","B":"a razão de natimortalidade","C":"o indicador de Swaroop e Uemura","D":"o coeficiente de mortalidade perinatal"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-277476","number":"277476","sourceNumber":"277476","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O município de Cristalina, localizado no Leste Goiano, apresentava em 2016 uma\npopulação geral de 60.118 habitantes e uma\npopulação de menor de um ano de 1.052 crianças,\nregistrando 913 nascimentos vivos. Nesse mesmo período, ocorreram 9 óbitos fetais, 15 óbitos em\nrecém-nascidos com menos de sete dias de vida, 1 óbito em recém-nascido com idade variando\nentre 7 e 27 dias de vida e 3 óbitos em lactentes com idade entre 3 meses e 11 meses de vida.\n\nCalcule o Coeficiente de Mortalidade Infantil para esse ano:","options":{"A":"18,06/1000 crianças menores de um ano.","B":"30,67/1000 nascidos vivos.","C":"26,62/1000 crianças menores de um ano.","D":"20,81/1000 nascidos vivos."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-277482","number":"277482","sourceNumber":"277482","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre a razão entre a prevalência e a incidência (P/I) em duas patologias distintas,\nconsidere a pneumonia bacteriana como um evento de saúde de curta duração, e a diabetes\nmellitus como um evento de longa duração. Écorreto afirmar que a razão P/I:","options":{"A":"É maior na pneumonia que na diabetes","B":"É semelhante nos dois casos","C":"É maior na diabetes que na pneumonia","D":"São incomparáveis, porque não há relação entre prevalência e incidência"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-277491","number":"277491","sourceNumber":"277491","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Numa cidade de 25 mil habitantes, ocorreram oito casos e quatro mortes por febre\namarela no período 2016-2017. Três mortes\nocorreram em 2016 e uma em 2017. Podemos afirmar\nque:","options":{"A":"Mortalidade por febre amarela foi de 50% no período","B":"Prevalência da febre amarela foi de 16 por 100 mil habitantes no ano de 2017","C":"Letalidade por febre amarela alcançou 75% no ano de 2016","D":"Incidência da febre amarela no período ultrapassou 30 por 100 mil habitantes"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-252731","number":"252731","sourceNumber":"252731","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Após cesárea, puérpera evoluiu com hemorragia vaginal, infecção puerperal e óbito por\ninsuficiência renal após seis semanas. É CORRETO afirmar que se trata de morte materna:","options":{"A":"Obstétrica tardia de causa direta.","B":"Não obstétrica de causa indireta.","C":"Obstétrica tardia de causa indireta.","D":"Não obstétrica."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-249858","number":"249858","sourceNumber":"249858","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A raiva humana apresenta","options":{"A":"altos coeficientes de letalidade e de mortalidade.","B":"baixo coeficiente de letalidade e alto coeficiente de mortalidade.","C":"alto coeficiente de letalidade e baixo coeficiente de mortalidade.","D":"baixos coeficientes de letalidade e de mortalidade."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-232245","number":"232245","sourceNumber":"232245","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Agência Nacional de Vigilância Sanitária tem divulgado a avaliação dos Indicadores\nNacionais das Infecções Relacionadas à Assistência à Saúde como, por exemplo, no boletim de\n2017, a Pneumonia Associada à Ventilação Mecânica em UTI adulto. Nesse boletim, dentre as\nseguintes medidas de frequência de doença, foi utilizada a","options":{"A":"prevalência acumulada.","B":"prevalência no período.","C":"densidade de incidência.","D":"taxa de ataque."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-246562","number":"246562","sourceNumber":"246562","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Compreendendo o período perinatal como aquele entre a 28ª semana de gestação e o\n7º dia de vida extrauterina, e o período neonatal estendido até o 28º dia de vida extrauterina,\nassinale a alternativa correta.","options":{"A":"Nos Estados Unidos, embora 99% dos nascimentos ocorram em ambiente hospitalar, somente\nde 80% a 85% das mulheres recebem assistência\nadequada durante a gestação.","B":"Até 65% dos óbitos até 1 ano de idade ocorrem nas primeiras 12 horas de vida extrauterina e\nestão ligados a anormalidades congênitas graves, asfixia periparto, infecções precoces ou retardo\nde crescimento intraútero (RCIU).","C":"O baixo peso ao nascimento (BPN) e o muito baixo peso ao nascimento (MBPN) são grandes\nresponsáveis pelas taxas de mortalidade infantil e, em países desenvolvidos, sua incidência\naumentou consideravelmente na população de etnia branca, tornando-se maior nesse grupo em\nrelação à etnia negra.","D":"Em países desenvolvidos, a maior causa de baixo peso ao nascimento (BPN) é o retardo de\ncrescimento intraútero (RCIU); nos países em desenvolvimento, o motivo principal é a\nprematuridade.","E":"Considerando-se as taxas de mortalidade perinatal, os óbitos neonatais são discretamente\nmaiores que os óbitos fetais."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-254253","number":"254253","sourceNumber":"254253","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em relação à mortalidade materna:","options":{"A":"As hemorragias constituem a principal causa de morte nos países desenvolvidos.","B":"A pré-eclâmpsia é a principal causa de morte nos locais mais desenvolvidos.","C":"No Brasil, a principal causa de morte é a hemorragia pós-parto.","D":"Na nossa cidade, a principal causa de morte é a hemorragia."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-234354","number":"234354","sourceNumber":"234354","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"É um indicador que expressa o efeito das mortes ocorridas precocemente em relação à\nduração de vida esperada, para uma determinada população. Trata-se:","options":{"A":"Da mortalidade proporcional por faixa etária.","B":"Dos anos potenciais de vida perdidos.","C":"Da expectativa média de vida.","D":"Da curva de Nelson Moraes."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-234357","number":"234357","sourceNumber":"234357","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A frequência esperada de alunos reprovados em imunologia é estimada em 90%. Se\ndois alunos se matriculam na disciplina de imunologia, qual é a probabilidade de ambos serem\naprovados na disciplina?","options":{"A":"0,81.","B":"0,01.","C":"0,18.","D":"0,10."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-232271","number":"232271","sourceNumber":"232271","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A mortalidade materna ocorre, principalmente.","options":{"A":"no período gestacional.","B":"no trabalho de parto.","C":"no intraparto.","D":"no pós-parto."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-241768","number":"241768","sourceNumber":"241768","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Assinale a alternativa correta sobre o indicador de Swaroop-Uemura ou Razão de\nMortalidade Proporcional.","options":{"A":"Utiliza como denominador o número de óbitos em pessoas de 15 a 60 anos de idade.","B":"Não pode ser utilizado para comparar regiões com diferentes graus de desenvolvimento.","C":"Utiliza como numerador o número de óbitos em pessoas com 50 anos ou mais na população.","D":"Quanto mais alto seu valor, menor o índice de desenvolvimento de uma população.","E":"Utiliza como denominador o número de óbitos em pessoas com 50 anos ou mais."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-241769","number":"241769","sourceNumber":"241769","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O cálculo do Coeficiente de Mortalidade Materna utiliza:","options":{"A":"apenas o número de mortes maternas diretas.","B":"o número de nascidos vivos.","C":"apenas o número de mortes maternas indiretas.","D":"o número de nascidos vivos e natimortos.","E":"a multiplicação do número obtido por 10.000."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-241774","number":"241774","sourceNumber":"241774","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Sobre as curvas de Nelson e Morais, analise os itens seguintes. I. São uma\nrepresentação gráfica da mortalidade\nproporcional. II. As curvas em N invertido indicam condições\nmuito baixas de vida da população. III. As curvas em J indicam condições elevadas de vida da\npopulação. Pode-se afirmar que:","options":{"A":"apenas I está correto.","B":"apenas II e III estão corretos.","C":"apenas I e II estão corretos.","D":"apenas I e III estão corretos.","E":"todos estão corretos."},"answer":"E","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-248989","number":"248989","sourceNumber":"248989","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No município de Uruana, foram cadastradas 200 gestantes em um período de 12\nmeses. Durante esse período, 40 gestantes\napresentaram infecção urinária. Somente no último\nmês desse período foram registrados 10 casos novos. A taxa de prevalência de infecção urinária\nnesse período foi de:","options":{"A":"5%","B":"10%","C":"15%","D":"20%"},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-246610","number":"246610","sourceNumber":"246610","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"O indicador de saúde materno e das condições do recém-nascido, fortemente\nassociado à mortalidade fetal, neo e\npós-neonatal, e à morbidade da criança, além de ser\nconsiderado pela Organização Mundial de Saúde (OMS) o mais importante determinante isolado, é:","options":{"A":"o índice de massa corpórea.","B":"o peso ao nascer.","C":"o perímetro braquial.","D":"o perímetro cefálico.","E":"altura/idade e peso/altura."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-248990","number":"248990","sourceNumber":"248990","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"A Taxa de Mortalidade Infantil (TMI) é considerada bom indicador para descrever e\nanalisar as condições de vida e saúde de uma população. Isso se justifica pelo fato de que a\ncriança pequena é mais sensível às condições socioeconômicas que repercutem no meio ambiente\nonde ela vive. Um dos seus componentes é a TMI neonatal, que inclui:","options":{"A":"apenas óbitos de menores de 7 dias de idade (até 6 dias de vida)","B":"apenas óbitos de menores de 28 dias de idade (até 27 dias de vida)","C":"apenas óbitos de menores de 30 dias de idade (até 29 dias de vida)","D":"apenas óbitos de menores de 31 dias de idade (até 30 dias de vida)"},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-248994","number":"248994","sourceNumber":"248994","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Na população brasileira masculina, considerando a faixa etária de 25 a 59 anos, as\nprincipais causas de morte são:","options":{"A":"doenças cardiocirculatórias","B":"diabetes tipo 2","C":"causas externas","D":"doenças infecciosas"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-248995","number":"248995","sourceNumber":"248995","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"No Brasil, a morbimortalidade por doenças infecciosas e a morbimortalidade por\ndoenças crônico-degenerativas encontram-se:","options":{"A":"em ascensão, definindo a transição epidemiológica","B":"em ascensão e em declínio, respectivamente","C":"em declínio e em ascensão, respectivamente","D":"estacionárias, definindo a transição demográfica"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-248996","number":"248996","sourceNumber":"248996","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Qual é o risco de morrer por determinada doença em um município com os seguintes\ndados: população = 100.000; óbitos totais = 500;\nóbitos pela doença = 10; casos novos da doença\n\n= 2?","options":{"A":"0,01/1.000","B":"5/1.000","C":"0,1/1.000","D":"0,02/1.000"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-218218","number":"218218","sourceNumber":"218218","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"É importante ter em mente que as definições de caso são via de regra, passíveis de\nerros de classificação, que podem\ninterferir na validade das estimativas de frequência de doenças.\nSobre incidência, assinale a CORRETA:","options":{"A":"Incidência é a frequência dos casos de um conjunto de doenças em um período anual.","B":"Os casos incidentes são indivíduos não doentes no início do período de observação e, portanto,\nsob risco de adoecimento, que, no seu decorrer,\nacabam por adoecer.","C":"A incidência é uma medida estática, pois determina a expressão temporal inerte da saúde.","D":"As medidas de incidência são obtidas através dos estudos transversais."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-218223","number":"218223","sourceNumber":"218223","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em comunidade por nome de Ficticity, a letalidade da dengue foi de 17% no ano de\n2017. Durante esse ano ocorreram 68 óbitos da\ndoença. Qual o número de casos de dengue nessa\ncomunidade no ano de 2017?","options":{"A":"4.","B":"25.","C":"400.","D":"1156."},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-201740","number":"201740","sourceNumber":"201740","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Em uma visita de uma equipe de profissionais de saúde, com a duração de três dias, a\num município do estado do Tocantins, todos os adultos de um pequeno povoado e de fazendas\nvizinhas foram examinados. Entre os resultados obtidos estão os seguintes: de 80 pessoas com\nsorologia positiva para dengue, oito eram desnutridas, enquanto em 200 outros indivíduos com\nsorologia negativa para dengue, 20 foram rotulados como desnutridos. O resultado da prevalência\nde desnutrição entre as pessoas com sorologia positiva para dengue e o resultado da razão de\nprevalência desse estudo são, respectivamente:","options":{"A":"10% e 1.","B":"15% e 1,5.","C":"20% e 2,0.","D":"25% e 2,5."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-201924","number":"201924","sourceNumber":"201924","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Com relação às diferenças entre incidência e prevalência, podemos aceitar que, no\ngeral:","options":{"A":"para doenças de longa duração, ambas são exatamente iguais","B":"a incidência possui maior acurácia diagnóstica","C":"a incidência é mais dinâmica e sensível às alterações dos padrões das doenças ao longo do\ntempo","D":"a prevalecência é melhor para avaliar doenças de curta duração","E":"a prevalecência é mais usada para avaliar riscos de surtos e epidemias"},"answer":"C","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-201931","number":"201931","sourceNumber":"201931","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Uma primigesta de 21 anos desenvolveu síndrome nefrótica com manifestações\nclínicas ao redor da 30ª semana\ngestacional, cuja investigação etiológica conduziu ao diagnóstico\nde Lúpus Eritematoso Sistêmico (LES), foi submetida à cesariana na 32ª semana, por sofrimento\nfetal. No puerpério, desenvolveu insuficiência renal, não respondeu ao tratamento, evoluindo com\nderrame pleural e ascite volumosa. Foi a óbito 40 dias após o parto, em decorrência de insuficiência\nrespiratória. Com relação à natureza do óbito, é correto afirmar que:","options":{"A":"Trata-se de um óbito materno por causa obstétrica indireta.","B":"Este não é um óbito materno, uma vez que a causa-base da morte foi LES e não um evento\nobstétrico.","C":"Não é possível defini-lo como materno, sem saber se a paciente já era portadora de LES antes\nde engravidar.","D":"Trata-se de óbito materno, pois todo óbito ocorrido durante a gestação, parto ou puerpério,\nindependentemente da causa, é materno.","E":"Não se trata de óbito materno, pois ocorreu após o término da gestação."},"answer":"A","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-218236","number":"218236","sourceNumber":"218236","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"?As taxas de obesidade em crianças e adolescentes em todo o mundo aumentaram de\nmenos de 1% (equivalente a cinco milhões\nde meninas e seis milhões de meninos) em 1975 para\nquase 6% em meninas (50 milhões) e quase 8% em meninos (74 milhões) em 2016. Combinado, o\nnúmero de obesos com idade entre cinco e 19 anos cresceu mais de dez vezes, de 11 milhões em\n1975 para 124 milhões em 2016. Outros 213 milhões estavam com sobrepeso em 2016, mas o\nnúmero caiu abaixo do limiar para a obesidade? OPAS/OMS. A expressão da frequência com que\nsurgem novos casos de uma doença, ou problema de saúde, por unidade de tempo, e com relação\nao tamanho de uma determinada população é denominada:","options":{"A":"Taxa de prevalência.","B":"Epidemia progressiva.","C":"Coeficiente de qualidade de vida.","D":"Taxa de incidência."},"answer":"D","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-1-218257","number":"218257","sourceNumber":"218257","collectionBlock":"medcurso:medcurso-preventiva-pre-1","collectionLabel":"Medcurso · PRE 1","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 1","subtopic":"","stem":"Um indicador muito utilizado para comparar regiões com diferentes graus de\ndesenvolvimento, criado em 1957, é o Indicador de Swaroop-Uemura ou Razão de Mortalidade\nProporcional (RMP). Calcula-se:","options":{"A":"Multiplicando-se o número de óbitos em indivíduos com 50 anos ou mais pelo total de óbitos da\npopulação.","B":"Dividindo-se o número de óbitos em indivíduos com 50 anos ou mais pelo total de óbitos da\npopulação.","C":"Dividindo-se o número de óbitos em indivíduos com 50 anos ou mais pelo total de óbitos da\npopulação de 50 anos.","D":"Dividindo-se o número de óbitos em indivíduos com 50 anos ou mais pelo total de óbitos da\n\npopulação entre 50 anos ou mais."},"answer":"B","source":"Preventiva/PRE 1/PRE 1.txt","sourceLabel":"Medcurso · PRE 1","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
